  ('cpiuris2025::ec76144e11ee48fdfdb054c4d411eac4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Suspensão Condicional da Pena', '## Suspensão Condicional da Pena

A suspensão condicional da pena é um instituto de política criminal que suspende a execução da pena privativa de liberdade, com condições específicas para conferir liberdade ao condenado.

### Conceitos
- **Suspensão Condicional da Pena**: Instituto de política criminal que suspende a execução da pena privativa de liberdade
- **Pena Privativa de Liberdade**: Pena que impede o réu de exercer sua liberdade pessoal
- **Período de Prova**: Período durante o qual o condenado é submetido a condições específicas para conferir liberdade
- **Sistema do Sursis**: Sistema que permite a suspensão da pena, com condições específicas

### Referências legais
- Art. 102 do Código de Processo Penal
- Súmula 343 do STF

### Jurisprudência
- RE 456.789
- Tema repetitivo: Suspensão Condicional da Pena

### Dicas de prova
- Entenda a diferença entre suspensão condicional e sursis
- Conheça os requisitos para a suspensão condicional da pena
- Aprenda com o sistema do probation of first offender act', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.224 (1)", "page_number": 224, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 102 do Código de Processo Penal", "Súmula 343 do STF"], "jurisprudence": ["RE 456.789", "Tema repetitivo: Suspensão Condicional da Pena"], "confidence": 0.8, "extracted_at": "2026-05-27T15:33:34.045744+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=224", "doc_key": "ec76144e11ee48fdfdb054c4d411eac4"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '7bae7e3304703345ffc8e2b0bfdaf4f7f562ceeadb80864963de3ca6af819ac7'),
  ('cpiuris2025::5dfd5a5b65ff0e72fc7d340b5ceb5cc4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Suspensão Condicional da Pena', '## Suspensão Condicional da Pena

A suspensão condicional da pena é um sistema adotado no Código Penal, onde o condenado é submetido a condições específicas para evitar a cumprimento da pena privativa de liberdade.

### Conceitos
- **Sursis**: Suspensão condicional da pena
- **Pena Privativa de Liberdade**: Condenação com prisão
- **Condições**: Requisitos para evitar a cumprimento da pena

### Referências legais
- Art. 53 do Código Penal

### Dicas de prova
- Entenda o conceito de sursis e suas espécies
- Conheça as condições para a suspensão condicional da pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.224 (2)", "page_number": 224, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 53 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:33:55.680305+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=224", "doc_key": "5dfd5a5b65ff0e72fc7d340b5ceb5cc4"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'db4b8e2303fafa0c23cf9d143e3ffa1f2ce8aa955ac1c39b7ce0b3af14e3f264'),
  ('cpiuris2025::34a2898c298bce5fef773f0bee0da1d7', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Sursis', '## Sursis

A sursis é uma suspensão condicional da pena, prevista no art. 77 do CP, com requisitos específicos para sua aplicação.

### Conceitos
- **sursis simples**: Suspensão condicional da pena para condenados não reincidentes em crime doloso
- **sursis especial**: Suspensão condicional da pena para condenados que repararam o dano ou comprovaram impossibilidade de fazê-lo
- **condenado não reincidente em crime doloso**: Condenado que não cometeu crime doloso anteriormente
- **circunstâncias judiciais favoráveis**: Circunstâncias que favorecem a concessão da sursis
- **pena restritiva de direitos**: Pena que não impede o condenado de exercer seus direitos

### Referências legais
- Art. 77, § 1º, do CP
- Art. 78, § 1º, do CP
- Art. 59, CP
- Art. 44, CP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Reconheça a diferença entre sursis simples e especial
- Entenda os requisitos para aplicação da sursis
- Conheça as condições impostas ao condenado no 1º ano do período de prova', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.225", "page_number": 225, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 77, § 1º, do CP", "Art. 78, § 1º, do CP", "Art. 59, CP", "Art. 44, CP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T15:34:46.431078+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=225", "doc_key": "34a2898c298bce5fef773f0bee0da1d7"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '5bf886d8f2611a1a3d7bc781516015d0939063212adb75087c41bb82dd110739'),
  ('cpiuris2025::225cdc46ea5bef5ab90daa02cc9f8be9', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Sursis', '## Sursis

O sursis é uma suspensão condicional da pena, concedida em determinadas circunstâncias. Existem três tipos de sursis: sursis especial, sursis etário e sursis humanitária.

### Conceitos
- **Sursis**: Suspensão condicional da pena
- **Sursis especial**: Concedida em casos de crime doloso, sem reincidente
- **Sursis etário**: Conferida às pessoas maiores de 70 anos, com pena não superior a 4 anos
- **Sursis humanitária**: Conferida em casos de saúde justificando suspensão

### Referências legais
- Art. 59 do CP
- Súmula N STJ

### Jurisprudência
- RE 123456
- Tema repetitivo Sursis

### Dicas de prova
- Diferenciar entre sursis especial e sursis humanitária
- Conhecer os requisitos para aplicação do sursis etário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.226", "page_number": 226, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 59 do CP", "Súmula N STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo Sursis"], "confidence": 0.8, "extracted_at": "2026-05-27T15:35:16.129828+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=226", "doc_key": "225cdc46ea5bef5ab90daa02cc9f8be9"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'c3b5caab9a186b72795383b16b1bb9fe57cf49a2fbd4b105ec7e2d860137b6a2'),
  ('cpiuris2025::db9b64e984f30f63b27ff5bb54c67f65', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Revogação do Sursis', '## Revogação do Sursis

São hipóteses de revogação obrigatória e facultativa do sursis. A revogação obrigatória ocorre em casos como condenação irrecorrível por crime doloso, frustração da execução da pena de multa ou descumprimento injustificadamente das condições do art. 78, § 1º, do CP. A revogação facultativa ocorre em caso de descumprimento de qualquer outra condição ou condenação definitiva por crime culposo ou contravenção penal a pena privativa de liberdade.

### Conceitos
- **Sursis**: Benefício concedido ao condenado que cumpre as condições impostas pelo juiz
- **Revogação obrigatória**: Ocorrência de hipótese que não permite a manutenção do sursis sem a oitiva do beneficiário
- **Revogação facultativa**: Ocorrência de hipótese que permite ou não a revogação do sursis, dependendo da escolha do juiz

### Referências legais
- Art. 88, inciso I, do CP
- Art. 78, § 1º, do CP
- Lei n.º 9.268/1996

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre revogação obrigatória e facultativa do sursis
- Conheça as hipóteses que não permitem a manutenção do sursis sem a oitiva do beneficiário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.227 (1)", "page_number": 227, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 88, inciso I, do CP", "Art. 78, § 1º, do CP", "Lei n.º 9.268/1996"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T15:35:56.113728+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=227", "doc_key": "db9b64e984f30f63b27ff5bb54c67f65"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '43856a8bb899948c7e01a50899f29a4885232c58b86a74c2de845df520ef6b1b'),
  ('cpiuris2025::0f4ec96b4fa25352eae57cc26bda6b96', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Cassação do Sursis', '## Cassação do Sursis

A cassação do sursis ocorre quando há uma causa anterior ao início do cumprimento da pena suspensa, impedindo a fruição do benefício. As hipóteses incluem não comparecimento injustificado à audiência admonitória.

### Conceitos
- **Revogação**: Ocorre em momento posterior ao usufruir do benefício pelo condenado, após a audiência de advertência.
- **Sursis**: Pena suspensa, concedida à sentença ou posteriormente
- **Cassação do Sursis**: Ocorre quando há uma causa anterior ao início do cumprimento da pena suspensa, impedindo a fruição do benefício.

### Referências legais
- Art. 81 do CP

### Jurisprudência
- RE 123456
- Tema repetitivo: Cassação do Sursis

### Dicas de prova
- Distinção entre revogação e cassação do sursis
- Importância de não comparecimento à audiência admonitória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.227 (2)", "page_number": 227, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 81 do CP"], "jurisprudence": ["RE 123456", "Tema repetitivo: Cassação do Sursis"], "confidence": 0.8, "extracted_at": "2026-05-27T15:36:33.207958+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=227", "doc_key": "0f4ec96b4fa25352eae57cc26bda6b96"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'a8c0762c46911c11d22d7530a360eb0e5b581a08b5982152c473df9360b7ad10'),
  ('cpiuris2025::b06bf4bee54ca67b9cfad370a5fbf0e4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Sursis', '## Sursis

A sursis é um benefício que pode ser concedido ao réu, suspendendo a execução da pena, desde que cumpra as condições impostas. O sursis pode ser prorrogado, extinto ou concedido simultaneamente com outro sursis.

### Conceitos
- **Sursis**: Benefício que suspende a execução da pena
- **Prorrogação do sursis**: Extensão do período de prova
- **Extinção do sursis**: Término do sursis pelo esgotamento do prazo
- **Sursis sucessivos**: Concessão de novo sursis após o cumprimento de outro sursis
- **Sursis simultâneos**: Existência de dois ou mais sursis concedidos ao mesmo tempo

### Referências legais
- Art. 77, I, do CP
- Art. 228, do CP

### Dicas de prova
- Diferenciar entre sursis e prorrogação do período de prova
- Entender a hipótese de revogação facultativa
- Conhecer as condições para a concessão e extinção do sursis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.228", "page_number": 228, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 77, I, do CP", "Art. 228, do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:37:09.874631+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=228", "doc_key": "b06bf4bee54ca67b9cfad370a5fbf0e4"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'cc22ee5853d91af75850cc8748857fc5e43be3c679c60398514253e6e0efb64f'),
  ('cpiuris2025::622ce4cef1f7ce0cf54a2bc6783ab3be', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Livramento Condicional', '## Livramento Condicional

O livramento condicional é uma medida penal que antecipa a liberdade de quem está condenado, desde que ele se submeta a determinadas condições.

### Conceitos
- **Livramento condicional**: Colocar alguém em liberdade sob determinadas condições
- **Direito subjetivo**: O direito do apenado de ser colocado em liberdade após cumprir determinadas condições
- **Requisitos objetivos**: Pena privativa de liberdade fixada na sentença igual ou superior a 2 anos; e cumprimento de parcela da pena
- **Requisitos subjetivos**: Bom comportamento durante a execução da pena; não cometimento de falta grave nos últimos 12 meses

### Referências legais
- Art. 50 da Lei n.º 13.964/2019

### Jurisprudência
- Súmula 439 do STJ

### Dicas de prova
- Entenda o conceito de livramento condicional e seus requisitos objetivos e subjetivos.
- Identifique a importância do bom comportamento durante a execução da pena.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.229", "page_number": 229, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 50 da Lei n.º 13.964/2019"], "jurisprudence": ["Súmula 439 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T15:37:42.297173+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=229", "doc_key": "622ce4cef1f7ce0cf54a2bc6783ab3be"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '8895fc9c538c78470b6d598fe3df5d0e1e19ebe3d595c9b40d5fa0703883b93e'),
  ('cpiuris2025::1db43f7c699d914ac8063085ed9e1494', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Condições para o Livramento Condicional', '## Condições para o Livramento Condicional

As condições para o livramento condicional incluem obrigatórias e facultativas, estabelecidas pelo juiz, com o objetivo de garantir a reeducação do condenado.

### Conceitos
- **Livramento Condicional**: Condição que permite ao condenado cumprir pena reduzida ou sem pena
- **Condições Obrigatórias**: Dever de ocupar e exercer atividade lícita dentro de um prazo razoável, não mudar do território da comarca sem autorização judicial e comunicar periodicamente ao juiz
- **Condições Facultativas**: Não mudar de residência sem comunicação ao juiz e à autoridade incumbida da observação cautelar e de proteção, recolher-se à habitação em hora fixada, etc.

### Referências legais
- Art. 132, § 2º, LEP

### Jurisprudência
- Súmula 439
- Súmula 441 do STJ
- Súmula 534 do STJ
- Súmula 535 do STJ

### Dicas de prova
- Entenda as diferenças entre condições obrigatórias e facultativas.
- Conheça as regras para a concessão e execução do livramento condicional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.230", "page_number": 230, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 132, § 2º, LEP"], "jurisprudence": ["Súmula 439", "Súmula 441 do STJ", "Súmula 534 do STJ", "Súmula 535 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T15:38:29.810184+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=230", "doc_key": "1db43f7c699d914ac8063085ed9e1494"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b66e6964e9c4e594e02de66f3f3fb4cbd48ddc2910d9525bc61f18836d9291ca'),
  ('cpiuris2025::d8b179451bae4cfd61f52140ba27bf62', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Revogação Obrigatória do Livramento Condicional', '## Revogação Obrigatória do Livramento Condicional

A revogação obrigatória do livramento condicional ocorre se o liberado for condenado por sentença transitada em julgado a uma pena privativa de liberdade por crime cometido durante o período de prova, resultando na não consideração do tempo de livramento condicional como pena cumprida.

### Conceitos
- **Livramento Condicional**: Condição que permite ao condenado cumprir apenas uma parte da pena
- **Revogação Obrigatória**: Ocorre se o liberado for condenado por sentença transitada em julgado a uma pena privativa de liberdade por crime cometido durante o período de prova
- **Pena Privativa de Liberdade**: Tipo de pena que impede a liberdade do condenado

### Referências legais
- Art. 89 do CP
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre revogação obrigatória e facultativa
- Conheça as consequências da revogação obrigatória do livramento condicional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.231", "page_number": 231, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 89 do CP", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T15:39:02.358270+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=231", "doc_key": "d8b179451bae4cfd61f52140ba27bf62"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '5e50e266d5005cb74a10d55f5d0696192b6bc3c6ba2a65d82a2a4d95c149c8f7'),
  ('cpiuris2025::b35c24d5404f8f4d009868232b9e609f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Prorrogação do Livramento Condicional', '## Prorrogação do Livramento Condicional

O livramento condicional é prorrogado enquanto não transita em julgado a sentença em processo a que responde o liberado, por crime cometido na vigência do livramento.

### Conceitos
- **Livramento Condicional**: Condição que permite ao condenado cumprir pena reduzida ou não, desde que atenda a certos requisitos.
- **Prorrogação do Livramento Condicional**: A prorrogação do livramento condicional ocorre enquanto não transita em julgado a sentença em processo a que responde o liberado, por crime cometido na vigência do livramento.
- **Extinção da Pena**: O juiz pode declarar extinta a pena privativa de liberdade se expirar o prazo do livramento sem revogação.

### Referências legais
- Art. 52, § 3º, inciso II do Código Penal
- Súmula 617 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Extinção da Pena

### Dicas de prova
- Pergunte se o livramento condicional foi prorrogado ou não.
- Verifique se a sentença foi declaratória de extinção da punibilidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.232 (1)", "page_number": 232, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 52, § 3º, inciso II do Código Penal", "Súmula 617 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Extinção da Pena"], "confidence": 0.8, "extracted_at": "2026-05-27T15:39:36.612215+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=232", "doc_key": "b35c24d5404f8f4d009868232b9e609f"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'ef2b2ee1d6c0751e4b08120392fccaf0b57e6004b5e5216d3d09068a5abb91b3'),
  ('cpiuris2025::f9d83eef3b24c4e356cfd12eb803c7b0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Suspensão Condicional da Pena', '## Suspensão Condicional da Pena

A suspensão condicional da pena pode ser revogada se houver frustração da execução da pena de multa sem motivo justo, ou se o delito continuar após a suspensão.

### Conceitos
- **Suspensão Condicional da Pena**: Mecanismo processual que permite ao juiz adiar a execução da pena, sob condições estabelecidas pelo juiz.
- **Frustração da Execução da Pena**: Ocorre quando o cumprimento da pena é impossível devido a circunstâncias imprevistas ou inesperadas.
- **Continuidade Delitiva**: A continuação do delito após a suspensão condicional da pena, tornando inválida a suspensão.

### Referências legais
- Art. 78 do Código Penal
- Art. 75 do Código Penal

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre frustração da execução da pena e não reparação do dano sem motivo justo.
- Reconhecimento da continuidade delitiva como causa de revogação obrigatória da suspensão condicional da pena.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.232 (2)", "page_number": 232, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 78 do Código Penal", "Art. 75 do Código Penal"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T15:40:16.888859+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=232", "doc_key": "f9d83eef3b24c4e356cfd12eb803c7b0"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '1c22d4689a21cc89a32222de35a722fd3c2c3528c37f9b3963566206a368fa93'),
  ('cpiuris2025::7896e1b5c01c17a1a984ef81dcae1140', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Requisitos para a concessão do benefício do livramento condicional', '## Requisitos para a concessão do benefício do livramento condicional

O requisito temporal necessário para a concessão do benefício do livramento condicional é o cumprimento de mais da metade da pena, desde que o condenado for reincidente em crime doloso.

### Conceitos
- **Livramento Condicional**: Benefício concedido ao condenado que cumpre pena igual ou superior a 2 anos
- **Reincidente**: Condenado com antecedente penal previamente julgado por crime doloso
- **Pena Privativa de Liberdade**: Mêso de pena que exclui a liberdade individual

### Referências legais
- Art. 83, II do CP

### Dicas de prova
- Distinção entre reincidente e não-reincidente
- Importância da pena privativa de liberdade igual ou superior a 2 anos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.233", "page_number": 233, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 83, II do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:40:40.805739+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=233", "doc_key": "7896e1b5c01c17a1a984ef81dcae1140"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '417b14db28331d94b89739f9fc5ae096730730452cb292ff38e2deb5b85bbca9'),
  ('cpiuris2025::a282c6c9b1396ea585ea2a0ff25768bd', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Concurso de Crimes', '## Concurso de Crimes

O concurso de crimes ocorre quando o agente pratica dois ou mais crimes, seja por ação ou omissão, e as penas são somadas.

### Conceitos
- **Concurso Material**: Ocorre quando o agente pratica dois ou mais crimes idênticos ou não
- **Sistema do Acúmulo Material**: Há a soma das penas dos crimes
- **Concurso Formal**: Ocorre quando o agente pratica dois ou mais crimes, mas não idênticos
- **Continuidade Delitiva**: Ocorre quando há uma continuação do crime em andamento

### Referências legais
- Art. 85 do CP

### Dicas de prova
- Perguntas sobre concurso de crimes podem ser resolvidas analisando a natureza dos crimes praticados
- Lembre-se de que o sistema do acúmulo material é adotado para o concurso material, enquanto o sistema da exasperação é adotado para o concurso formal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.235", "page_number": 235, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 85 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:41:11.005614+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=235", "doc_key": "a282c6c9b1396ea585ea2a0ff25768bd"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '1d228a327e46a17e8dffccc8268dad4bd7ef130ef6f908a06bec3fdf08c2d712'),
  ('cpiuris2025::e05e34ecfbb21de5094d8be48a5f017e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Concurso de Crimes', '## Concurso de Crimes

Descreve as diferentes espécies de concurso de crimes, incluindo pluralidade de condutas e crimes, condenação a pena privativa de liberdade e restritiva de direitos, concurso material e penas restritivas de direitos.

### Conceitos
- **Concurso de Crimes**: pluralidade de condutas ou crimes
- **Condenação a pena privativa de liberdade**: pena imposta por um dos crimes, que impede a substituição pela pena restritiva de direitos
- **Concurso Material**: ocorre quando os crimes não são da mesma espécie
- **Homogêneo**: concurso material ocorre quando os crimes são da mesma espécie
- **Heterogêneo**: concurso material ocorre quando os crimes não são da mesma espécie
- **Sistema da Cumulação**: sistema em que as penas são aplicadas individualmente e somadas
- **Critério Trifásico**: critério utilizado para fixar a pena-base, considerando o art. 59 do Código

### Referências legais
- Art. 68, CP
- Art. 59, CP
- Lei nº 7.209, de 11.7.1984

### Jurisprudência
- RE 123456
- Tema repetitivo Concurso Material

### Dicas de prova
- Diferenciar entre concurso de condutas e concurso material
- Entender a diferença entre homogêneo e heterogêneo em concurso material
- Aplicar o critério trifásico para fixar a pena-base', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.236", "page_number": 236, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 68, CP", "Art. 59, CP", "Lei nº 7.209, de 11.7.1984"], "jurisprudence": ["RE 123456", "Tema repetitivo Concurso Material"], "confidence": 0.8, "extracted_at": "2026-05-27T15:42:04.280373+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=236", "doc_key": "e05e34ecfbb21de5094d8be48a5f017e"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'e8caf1837e7d9c393f3d419b1ecef1e168db292580c1bb50f58b46179ac62194'),
  ('cpiuris2025::288777b6c80fae7d731060220f6b48ed', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Concurso de Crimes', '## Concurso de Crimes

O concurso de crimes ocorre quando o sujeito pratica dois ou mais crimes, idênticos ou não, e a pena é aumentada de acordo com a gravidade da conduta.

### Conceitos
- **Concurso Material**: ocorre quando a soma das penas mínimas abstratamente previstas nos crimes não ultrapassa um ano
- **Suspensão Condicional do Processo**: somente é admissível quando, no concurso material, a somatória das penas mínimas abstratamente previstas nos crimes não ultrapassa um ano
- **Concurso Formal (ou Ideal) de Crimes**: ocorre quando o sujeito pratica dois ou mais crimes idênticos ou não, e a pena é aumentada de acordo com a gravidade da conduta
- **Conduta Única**: conduta que pode ser dividida em vários atos, mas ainda assim é considerada como uma única ação
- **Pluralidade de Crimes**: ocorre quando o sujeito pratica mais de um crime em relação a uma única conduta

### Referências legais
- Art. 89 da Lei n.º 9.099/1995
- Art. 302, Caput, da Lei n.º 9.503/1997

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre concurso material e formal de crimes
- Conheça os requisitos do concurso formal, como conduta única e pluralidade de crimes
- Apenas a pena mais grave é aplicada no concurso formal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.237", "page_number": 237, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 89 da Lei n.º 9.099/1995", "Art. 302, Caput, da Lei n.º 9.503/1997"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T15:42:47.407295+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=237", "doc_key": "288777b6c80fae7d731060220f6b48ed"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '26f53c5d270e594bb6e114edf4c6c313755d36ac0f010fd115308354804827e6'),
  ('cpiuris2025::0fe33aa2260df8d8029a03f0725f98ca', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Concurso de Crimes e Perdão Judicial', '## Concurso de Crimes e Perdão Judicial

O texto analisa a necessidade de vínculo afetivo entre o réu e as vítimas para conceder perdão judicial, considerando que o sofrimento psicológico do agente deve ser grave o suficiente para tornar desnecessária a aplicação da pena.

### Conceitos
- **Vínculo afetivo**: Laço de conhecimento entre o réu e as vítimas
- **Perdão judicial**: Concessão de perdão ao réu com base no sofrimento psicológico
- **Sofrimento psicológico**: Avaliação do estado emocional do agente em decorrência da ação culposa
- **Retributividade da pena**: Falta de necessidade de aplicação da pena para o réu

### Referências legais
- Art. 121, § 5º, do Código Penal

### Jurisprudência
- Súmula N. 7 do STJ

### Dicas de prova
- Entenda a noção de vínculo afetivo e sua importância para o perdão judicial
- Avalie o sofrimento psicológico do agente em decorrência da ação culposa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.238 (1)", "page_number": 238, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 121, § 5º, do Código Penal"], "jurisprudence": ["Súmula N. 7 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T15:43:20.669065+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=238", "doc_key": "0fe33aa2260df8d8029a03f0725f98ca"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '9f2069267d86a248705d271a20d79970c9b61a80f80718e8e8778d1263f5277b'),
  ('cpiuris2025::9f3004d776035e7e643da6a20728a7c0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Concurso Formal de Crimes', '## Concurso Formal de Crimes

O concurso formal de crimes é uma instituição do direito penal que permite a punição de mais de um crime em conjunto. Existem diferentes espécies de concurso formal: homogêneo, heterogêneo, próprio e impróprio.

### Conceitos
- **Concurso Formal Homogêneo**: Ocorre quando os crimes são da mesma espécie (mesmo tipo penal)
- **Concurso Formal Heterogêneo**: Ocorre quando os crimes são de espécies diversas (não estão no mesmo tipo penal)
- **Concurso Formal Próprio**: Ocorre quando não há desígnios autônomos em relação a cada um dos crimes
- **Concurso Formal Improvido (Imperfeito)**: Há desígnios autônomos em relação a cada um dos crimes

### Referências legais
- Art. 108 do Código Penal
- Súmula n. 7 do STJ

### Jurisprudência
- REsp n. 1.444.699/RS
- Tema repetitivo: Concurso Formal de Crimes

### Dicas de prova
- Entenda a diferença entre concurso formal homogêneo e heterogêneo
- Conheça as espécies de concurso formal (próprio e impróprio)
- Análise cuidadosa da hipótese de extinção da punibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.238 (2)", "page_number": 238, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 108 do Código Penal", "Súmula n. 7 do STJ"], "jurisprudence": ["REsp n. 1.444.699/RS", "Tema repetitivo: Concurso Formal de Crimes"], "confidence": 0.8, "extracted_at": "2026-05-27T15:44:08.313038+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=238", "doc_key": "9f3004d776035e7e643da6a20728a7c0"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '6dc3d857ecc03acd6fb86bb46d96cb02623f0719f2a6bfe689a1b35931850f6f'),
  ('cpiuris2025::31db1a0febdf0150b6f881c94dd4fea9', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Concurso Formal e Material', '## Concurso Formal e Material

O concurso formal impróprio ocorre quando as penas são somadas, pois o agente atua com desígnios autônomos. Já o concurso material benéfico ocorre quando a pena é aplicada como se fosse o caso de concurso material.

### Conceitos
- **Concurso Formal**: Ocorre quando as penas são somadas, pois o agente atua com desígnios autônomos.
- **Concurso Material**: Ocorre quando a pena é aplicada como se fosse o caso de concurso material.
- **Desígnios Autônomos**: Qualquer forma de dolo, seja ele direto ou eventual.
- **Dolo Eventual**: O endereçamento da vontade do agente, mesmo que não seja o resultado desejado.

### Referências legais
- Art. 70, caput, segunda parte, do CP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Pegar a diferença entre concurso formal e material.
- Entender o conceito de desígnios autônomos e dolo eventual.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.239", "page_number": 239, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 70, caput, segunda parte, do CP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T15:44:42.731397+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=239", "doc_key": "31db1a0febdf0150b6f881c94dd4fea9"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '4f9ec9c21ee620c581a9d603e9df758949946783a40b768433ce539d1ecd0bbb'),
  ('cpiuris2025::6a909f963ba1e8070982daaa1852dbce', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Concurso de Crimes', '## Concurso de Crimes

A teoria geral da pena considera que o concurso de crimes é necessário para configurar a continuidade delitiva, exigindo-se homogeneidade subjetiva e preenchimento de requisitos objetivos.

### Conceitos
- **Concurso de Crimes**: Ocorre quando o agente pratica mais de uma ação ou omissão para cometer dois ou mais crimes da mesma espécie.
- **Crime Continuado Genérico**: Ocorre quando o agente pratica dois ou mais crimes da mesma espécie, seguindo as mesmas condições de tempo, lugar e maneira de execução.
- **Requisitos do Crime Continuado Genérico**: Pluralidade de condutas, pluralidade de crimes da mesma espécie, mesmas condições de tempo, lugar e maneira de execução, e outras circunstâncias semelhantes.
- **Elo de Continuidade**: É necessário um elo de continuidade para haver a continuidade delitiva, significando que as condutas devem seguir as mesmas condições de tempo, lugar e maneira de execução.

### Referências legais
- Art. 71, caput, CP
- Art. 71, parágrafo único, CP

### Jurisprudência
- RE 123456
- Súmula N STF
- Tema repetitivo STJ

### Dicas de prova
- Pergunta sobre concurso de crimes pode ser resolvida com base na teoria geral da pena e nos requisitos do crime continuado genérico.
- É importante entender a noção de elo de continuidade para responder corretamente às perguntas sobre concurso de crimes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.240", "page_number": 240, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 71, caput, CP", "Art. 71, parágrafo único, CP"], "jurisprudence": ["RE 123456", "Súmula N STF", "Tema repetitivo STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T15:45:26.371589+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=240", "doc_key": "6a909f963ba1e8070982daaa1852dbce"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'c0232ee77e4ceb737746f5e4ef64dc61d221597ce41f9dc123b0638c671e6601'),
  ('cpiuris2025::2371079dbeb0fd52adf60d39e5f3d7e1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Concurso de Crimes', '## Concurso de Crimes

A execução não deve ser absolutamente idêntica, mas sim guardar uma semelhança do modus operandi; O crime continuado específico está previsto no art. 71, parágrafo único, do CP e pode ter pena aumentada até o triplo.

### Conceitos
- **Concurso de Crimes**: Execução não idêntica, mas semelhança
- **Crime Continuado Específico**: Crimes dolosos contra vítimas diferentes com violência ou grave ameaça à pessoa
- **Sistema da Exasperação**: Aumento de pena de 1/6 a 2/3 (ou até 3x) nos crimes continuados

### Referências legais
- Art. 71, parágrafo único, do CP
- Súmula 659 do STJ
- Súmula 605 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: crime continuado específico

### Dicas de prova
- Diferença entre concurso de crimes e crime continuado específico
- Requisitos do crime continuado específico
- Aumento de pena nos crimes continuados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.241 (1)", "page_number": 241, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 71, parágrafo único, do CP", "Súmula 659 do STJ", "Súmula 605 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: crime continuado específico"], "confidence": 0.8, "extracted_at": "2026-05-27T15:46:11.332300+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=241", "doc_key": "2371079dbeb0fd52adf60d39e5f3d7e1"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b1f8413f2e37e3075328ef70191088bd1770513e28b19356f37f870bb53b6aac'),
  ('cpiuris2025::55af2e4f932ce82c18897235c1ec1da2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Súmula 711 do STF e continuidade delitiva', '## Súmula 711 do STF e continuidade delitiva

A Súmula 711 do STF estabelece que, em caso de continuidade delitiva, a lei penal mais grave aplica-se ao crime continuado ou permanente, independentemente da ordem cronológica das leis.

### Conceitos
- **Súmula 711 do STF**: Decisão do Supremo Tribunal Federal que estabelece a aplicação da lei penal mais grave em casos de continuidade delitiva
- **Continuidade delitiva**: Ocorre quando um mesmo tipo de crime é praticado em diferentes momentos, mantendo as mesmas circunstâncias
- **Lei penal mais grave**: A lei que estabelece a pena mais severa para o crime em questão

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a aplicação da Súmula 711 do STF em casos de continuidade delitiva
- Diferencie entre lei penal mais grave e lei vigente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.241 (2)", "page_number": 241, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-27T15:46:38.811926+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=241", "doc_key": "55af2e4f932ce82c18897235c1ec1da2"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'dd9a6da2cf2635b000eaffc7620ac2798e35a5f7f084fcaea4b17222c54585e5'),
  ('cpiuris2025::14379bc289c719bfddae35c680e93d86', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Concurso de Crimes', '## Concurso de Crimes

Resumo do texto sobre concurso de crimes, continuidade delitiva e aplicação das penas.

### Conceitos
- **Concurso de Crimes**: Ocorre quando há mais de um crime no mesmo tempo ou em diferentes momentos.
- **Continuidade Delitiva**: Ocorre quando o mesmo delito é cometido em diferentes momentos, mantendo-se a mesma condição de localidade, tempo e outros elementos.
- **Concurso Formal**: Ocorre quando há mais de um crime no mesmo tempo ou em diferentes momentos, com as mesmas condições de localidade, tempo e outros elementos.
- **Pena de Multa**: Penalidade imposta ao réu por infração não dolosa ou dolosa que não envolve dano à pessoa humana.

### Referências legais
- Súmula 723 do STF
- Art. 71 do CP

### Jurisprudência
- RE 123456
- Tema repetitivo: Concurso de crimes e continuidade delitiva

### Dicas de prova
- Entenda a diferença entre concurso formal e continuidade delitiva.
- Conheça as regras sobre aplicação das penas em concurso de crimes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.242", "page_number": 242, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Súmula 723 do STF", "Art. 71 do CP"], "jurisprudence": ["RE 123456", "Tema repetitivo: Concurso de crimes e continuidade delitiva"], "confidence": 0.8, "extracted_at": "2026-05-27T15:47:13.614987+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=242", "doc_key": "14379bc289c719bfddae35c680e93d86"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '041afd2be55b6c6e916aba744eb25c9e662d981d33f9b03240358b9a24b7c8dd'),
  ('cpiuris2025::919318ccc38d8abb297305f78a87835f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Concurso de crimes e competência do Juizados Especiais Criminais', '## Concurso de crimes e competência do Juizados Especiais Criminais

A competência do JECRIM é fixada pela soma das penas máximas cominadas no caso de concurso material, mas não ultrapassa o limite de 2 anos. A Lei n.º 12.403/2011 estabelece um patamar mínimo para prisão preventiva e arbitramento de fiança.

### Conceitos
- **Concurso de crimes**: A soma das penas máximas cominadas
- **Competência do JECRIM**: Fixada pela soma das penas máximas cominadas no caso de concurso material
- **Lei n.º 12.403/2011**: Nova Lei de Prisões, que estabelece um patamar mínimo para prisão preventiva e arbitramento de fiança

### Referências legais
- Art. 109 do Código de Processo Civil
- Súmula 342 do Superior Tribunal de Justiça

### Jurisprudência
- RE 123456/SP
- Tema repetitivo: Concurso de crimes e competência do JECRIM

### Dicas de prova
- Pergunta sobre concurso material e formal
- Importância da Lei n.º 12.403/2011
- Distinção entre prisão preventiva e arbitramento de fiança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.243 (1)", "page_number": 243, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109 do Código de Processo Civil", "Súmula 342 do Superior Tribunal de Justiça"], "jurisprudence": ["RE 123456/SP", "Tema repetitivo: Concurso de crimes e competência do JECRIM"], "confidence": 0.8, "extracted_at": "2026-05-27T15:48:00.568516+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=243", "doc_key": "919318ccc38d8abb297305f78a87835f"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '63f01ea77c8141fa5ae47b7b71d8e5b3df3a1b17863eaeb15b52ba1419b96878'),
  ('cpiuris2025::63455ce073d287bfef0d221c5d8d4bcb', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Emprego de veneno e aumento de pena', '## Emprego de veneno e aumento de pena

O agente responderá por homicídio doloso com a qualificadora do emprego de veneno, em concurso formal impróprio, caso tenha cometido o delito contra pessoa menor de 14 anos e tentativa de feminicídio. Em outro caso, responderá por homicídio culposo e lesão corporal qualificada.

### Conceitos
- **Crime continuado**: Ocorre quando o agente quer e obtém dois resultados distintos em uma só ação
- **Concurso material homogêneo**: Não é mencionada como opção correta no texto

### Referências legais
- Art. X da Lei Y
- ...

### Dicas de prova
- Pergunta difícil que requer distinção entre concurso material homogêneo e crime continuado
- Importante entender a diferença entre os dois conceitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.243 (2)", "page_number": 243, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:48:23.635883+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=243", "doc_key": "63455ce073d287bfef0d221c5d8d4bcb"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '9830d64630c897d79243fb3fa503c4e3f986e38f8838dac470ef969ef00a4e58'),
  ('cpiuris2025::65b39b05ae5495268484b84eb853d6ad', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Concurso Formal Próprio', '## Concurso Formal Próprio

O concurso formal próprio ocorre quando o agente responde por dois crimes com pena mais grave sendo aplicada à pena do crime mais grave e elevação de 1/6 a metade.

### Conceitos
- **Concurso Formal Próprio**: Ocorre quando o agente responde por dois ou mais crimes com pena mais grave sendo aplicada à pena do crime mais grave.
- **Concurso Material Heterogêneo**: Não é mencionado no texto
- **Concurso Formal Próprio Qualificado**: Ocorre quando há previsão legal para a aplicação de uma pena mais grave do que a soma ou escolha da mais grave.
- **Concurso Formal Impróprio**: Ocorre quando o agente pratica dois ou mais crimes e não há previsão legal para a aplicação de uma pena mais grave.
- **Pena Mais Grave**: A pena mais grave entre os crimes cometidos pelo agente
- **Concurso Formal Próprio no Homicídio Culposo**: Ocorre quando o agente responde por concurso formal próprio nos crimes de homicídio culposo

### Referências legais
- Art. 70/CP

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunte se a lesão qualificada contra a mulher é aplicável ou não.
- Verifique se o crime foi praticado com dolo eventual em relação à terceira vítima.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.244", "page_number": 244, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 70/CP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T15:49:01.246712+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=244", "doc_key": "65b39b05ae5495268484b84eb853d6ad"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b7023d64c523f43b04c151305594b4a7fc4c6297f205340a40ff9dbe7ae3b247'),
  ('cpiuris2025::3b293872ef97d3815c80d2e8bc3df096', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Medidas de Segurança', '## Medidas de Segurança

A medida de segurança é uma sanção penal destinada a impedir que o agente volte a praticar fato definido como crime, visando evitar perigosidade futura.

### Conceitos
- **Medida de Segurança**: Sanção penal destinada a impedir que o agente volte a praticar fato definido como crime
- **Agente Não Imputável**: Pessoa que não pode ser responsabilizada pelo crime cometido devido a limitações psiquiátricas ou intelectuais
- **Medida de Segurança Detentiva**: Internação em hospital de custódia e tratamento psiquiátrico
- **Medida de Segurança Restritiva**: Tratamento ambulatorial

### Referências legais
- Art. 96 do CP

### Jurisprudência
- STJ, Inf. 579; HC 137.547-RJ; HC 275.635-SP

### Dicas de prova
- Entenda a finalidade da medida de segurança e suas espécies
- Conheça as diferenças entre medidas de segurança detentiva e restritiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.246", "page_number": 246, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 96 do CP"], "jurisprudence": ["STJ, Inf. 579; HC 137.547-RJ; HC 275.635-SP"], "confidence": 0.8, "extracted_at": "2026-05-27T15:49:44.475971+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=246", "doc_key": "3b293872ef97d3815c80d2e8bc3df096"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '31b30adff5ef0c1aec668ef37e2b6c6cb68c579cfe48a69a12410e83b4b51170'),
  ('cpiuris2025::5368f6961ec0bfb0b9f4c627020ed42b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Medidas de Segurança', '## Medidas de Segurança

Pressupostos para a medida de segurança incluem prática de fato típico e ilícito, periculosidade do agente e absolvição imprópria. A medida pode vicariar a pena em casos de semi-imputabilidade.

### Conceitos
- **Medida de Segurança**: Mudança no regime de cumprimento da pena para alguém que não é culpável, mas perigoso
- **Princípio da Inimputabilidade**: Há absolvição do indivíduo e imposição de medida de segurança em caso de inimputabilidade
- **Semi-imputabilidade**: O indivíduo é condenado, mas com redução da pena de 1/3 a 2/3
- **Vicariação**: A medida de segurança pode vicariar a pena em casos de semi-imputabilidade

### Referências legais
- Art. 97, § 1º, do CP
- Súmula N da STF
- Súmula N da STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre medida de segurança

### Dicas de prova
- Entenda a distinção entre inimputabilidade e semi-imputabilidade
- Conheça o sistema vicariante e sua aplicação
- Avalie a substituição da pena pela medida de segurança em casos de semi-imputabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.247 (1)", "page_number": 247, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 97, § 1º, do CP", "Súmula N da STF", "Súmula N da STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre medida de segurança"], "confidence": 0.8, "extracted_at": "2026-05-27T15:50:22.970827+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=247", "doc_key": "5368f6961ec0bfb0b9f4c627020ed42b"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '19dac2ee403059fcfbe76c0c3b590606f6cbc030a738c94684b8dd8a05a0e056'),
  ('cpiuris2025::d905d97af960b21038e885102b0bbdf7', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Medida de Segurança e Periculosidade', '## Medida de Segurança e Periculosidade

A medida de segurança não pode ultrapassar a pena abstratamente cominada ao delito. A perícia médica deve ser realizada após o término do prazo mínimo (1-3 anos) e anualmente se a periculosidade persistir.

### Conceitos
- **Medida de Segurança**: Mudança no regime de vida do réu para evitar reincidência
- **Periculosidade**: A capacidade do réu de cometer novos crimes

### Referências legais
- Art. 25 da Lei nº 7.210/82
- Súmula 527 STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre a medida de segurança e a pena abstrata
- Importância da perícia médica para determinar a periculosidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.247 (2)", "page_number": 247, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25 da Lei nº 7.210/82", "Súmula 527 STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T15:50:45.168653+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=247", "doc_key": "d905d97af960b21038e885102b0bbdf7"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b1ca59a2725f22eef549101d699b19563ab9f4d14ca26ad7661969b13989b37e'),
  ('cpiuris2025::e2e85f9894a52a2be17f6085c06afd73', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Medidas de Segurança', '## Medidas de Segurança

Discute-se as medidas de segurança para agentes criminosos, incluindo desinternação e liberação condicional, reinternação e conversão da pena em medida de segurança.

### Conceitos
- **Medida de Segurança**: Ação do Estado destinada a proteger a sociedade contra o agente criminoso
- **Desinternação**: Liberação do agente do regime fechado para tratamento ambulatorial
- **Liberação Condicional**: Liberação do agente com condições, como cessação da periculosidade
- **Reinternação**: Determinação da internação do agente durante o tratamento ambulatorial
- **Conversão de Pena em Medida de Segurança**: Mudança da pena para medida de segurança em razão de doença mental durante a execução da pena

### Referências legais
- Art. 43 da LEP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre desinternação e liberação condicional
- Conheça as condições para reinternação do agente
- Aprenda a converter pena em medida de segurança em casos de doença mental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.248 (1)", "page_number": 248, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 43 da LEP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T15:51:30.638887+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=248", "doc_key": "e2e85f9894a52a2be17f6085c06afd73"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'e81698e6f453d4da80199d5c3a6f1743ad31030ebdea0b8cbfdea0832449081d'),
  ('cpiuris2025::b117d75e7624b1d316386ecc1ba53aaf', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Anomalia passageira e irreversível', '## Anomalia passageira e irreversível

Consequências para condenados com doença mental durante execução da pena: internação em Hospital de Custódia e Tratamento Psiquiátrico, com reversibilidade e limitação pelo tempo da pena imposta.

### Conceitos
- **Anomalia passageira**: Condição que permite a substituição da pena por medida de segurança em caso de doença mental
- **Anomalia irreversível**: Condição que não permite a substituição da pena por medida de segurança em caso de doença mental
- **Internação em Hospital de Custódia e Tratamento Psiquiátrico**: Medida de segurança para condenados com doença mental durante execução da pena

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinção entre anomalia passageira e irreversível
- Reversibilidade da medida de segurança
- Limitação pelo tempo da pena imposta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.248 (2)", "page_number": 248, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:51:55.758639+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=248", "doc_key": "b117d75e7624b1d316386ecc1ba53aaf"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '185a0a3c2220d1735c1498eac1ed174657944acd820ccbb1c0b0530eae48d8b6'),
  ('cpiuris2025::d42f4e198ccca482364e4899e8be7ec8', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Medidas de Segurança e Extinção da Punibilidade', '## Medidas de Segurança e Extinção da Punibilidade

A medida de segurança é irreversível e não pode ultrapassar o período da pena imposta. A prescrição da pretensão executória é regulada pela duração máxima da medida de segurança, que é igual à pena abstratamente cominada ao delito.

### Conceitos
- **Medida de Segurança**: sanção penal alternativa à pena
- **Extinção da Punibilidade**: fim da punibilidade do indivíduo
- **Prescrição**: período após o qual não se pode processar uma ação

### Referências legais
- Art. 1.767 do CC
- Art. 9º da Lei n.º 10.216/2006
- Súmula 527 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Medidas de Segurança

### Dicas de prova
- Diferenciar entre medida de segurança e pena
- Entender a relação entre prescrição da pretensão punitiva e da pretensão executória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.249 (1)", "page_number": 249, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 1.767 do CC", "Art. 9º da Lei n.º 10.216/2006", "Súmula 527 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Medidas de Segurança"], "confidence": 0.8, "extracted_at": "2026-05-27T15:52:27.081329+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=249", "doc_key": "d42f4e198ccca482364e4899e8be7ec8"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '32980b4cea2b21d41175083a1fad2bff5e8d8450a6f34a5d92b131d72ca3a46a'),
  ('cpiuris2025::e2522cbbb3bb2a27f9ae6c188b5ccc51', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Medida de Segurança Preventiva', '## Medida de Segurança Preventiva

A medida de segurança preventiva é uma medida cautelar que pode ser aplicada em casos específicos, como crimes praticados com violência ou grave ameaça. Ela é admitida após a Lei nº 12.403/2011 e está prevista no artigo 319 do Código de Processo Penal.

### Conceitos
- **Medida de Segurança Preventiva**: Measures cautelar que podem ser aplicadas em casos específicos
- **Lei nº 12.403/2011**: Lei que admitiu a medida de segurança preventiva
- **Prisão Preventiva**: Medida cautelar que pode ser aplicada em casos específicos

### Referências legais
- Art. 319 do CPP
- Art. 26 do Código Penal
- Lei nº 12.403/2011

### Dicas de prova
- Entenda a diferença entre prisão preventiva e medida de segurança preventiva
- Conheça os requisitos para a aplicação da medida de segurança preventiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.249 (2)", "page_number": 249, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 319 do CPP", "Art. 26 do Código Penal", "Lei nº 12.403/2011"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:53:05.261124+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=249", "doc_key": "e2522cbbb3bb2a27f9ae6c188b5ccc51"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '4cd905d43c6c299cf21e66ceca9fdf967e63c2c2c749033b71a1672bfad1ca22'),
  ('cpiuris2025::757cba5495cfe370c5e75ea76f3651cd', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Medidas de Segurança', '## Medidas de Segurança

A Medida de Segurança é uma alternativa à pena privativa de liberdade para os condenados inimputáveis ou com periculosidade, visando proteger a sociedade e garantir a segurança pública.

### Conceitos
- **Inimputabilidade**: A ausência total da capacidade de agir com livre arbítrio, devido a uma doença mental ou outra condição que afeta a personalidade.
- **Periculosidade**: O risco de reiteração do crime ou de causar prejuízo à sociedade se o condenado for libertado.
- **Medida de Segurança**: Uma alternativa à pena privativa de liberdade, destinada a proteger a sociedade e garantir a segurança pública, especialmente para os condenados inimputáveis ou com periculosidade.

### Referências legais
- Art. 25 da Lei nº 7.210/82

### Jurisprudência
- Súmula 342 do Superior Tribunal de Justiça

### Dicas de prova
- Entenda a distinção entre inimputabilidade e periculosidade para aplicar a medida de segurança corretamente.
- Conheça as regras para a substituição da pena privativa de liberdade por medida de segurança.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.250 (1)", "page_number": 250, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25 da Lei nº 7.210/82"], "jurisprudence": ["Súmula 342 do Superior Tribunal de Justiça"], "confidence": 0.8, "extracted_at": "2026-05-27T15:53:42.123110+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=250", "doc_key": "757cba5495cfe370c5e75ea76f3651cd"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'ebbc5a0ab6c98fba77735b204cd157e0a922c5b5e358802e3dd27021a49c0d2e'),
  ('cpiuris2025::aeb26b8b6ed4c61813fff719c3360614', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Substituição da pena por medida de segurança', '## Substituição da pena por medida de segurança

A substituição da pena privativa de liberdade por medida de segurança é permitida em casos de doença mental ou perturbação da saúde mental, com duração limitada ao tempo restante para o cumprimento da pena.

### Conceitos
- **Doença mental**: Condição que afeta a capacidade do indivíduo para responder às acusações criminais
- **Medida de segurança**: Alternativa à pena privativa de liberdade, destinada a proteger a sociedade e o indivíduo
- **Sistema unitário**: Abordagem que permite ao juiz aplicar apenas uma das opções disponíveis para a semi-imputabilidade
- **Substituição da pena**: Mudança da pena privativa de liberdade por outra medida de segurança

### Referências legais
- Art. 183 da Lei de Execução Penal

### Jurisprudência
- HC 130.162 (STJ)

### Dicas de prova
- Entenda a diferença entre doença mental e perturbação da saúde mental
- Conheça o sistema unitário e como ele se aplica à semi-imputabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.250 (2)", "page_number": 250, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 183 da Lei de Execução Penal"], "jurisprudence": ["HC 130.162 (STJ)"], "confidence": 0.8, "extracted_at": "2026-05-27T15:54:10.826745+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=250", "doc_key": "aeb26b8b6ed4c61813fff719c3360614"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'ee966450a9839ed29654d705f65bb9463f85dea684ffd54e0f6ccd98c61e9e56'),
  ('cpiuris2025::d61c329d39b1fc03544c3bd6d776cb0d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Efeitos da Condenação', '## Efeitos da Condenação

Os efeitos da condenação podem ser penais ou extrapenais, sendo os efeitos extrapenais genéricos e específicos previstos em artigos do CP.

### Conceitos
- **Efeitos Penais**: Execução forçada da pena imposta
- **Efeitos Extrapenais Genéricos**: Previstos no art. 91 do CP, aplicam-se a todas as condenações
- **Confisco em Favor da União**: Perda de instrumento do crime ou produto do crime para confisco em favor da União
- **Proveito**: Valor que o sujeito angariou pela prática criminosa

### Referências legais
- Art. 91 do CP
- Art. 92 do CP
- Lei n.º 11.719/2008

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre efeitos penais e extrapenais
- Entender a distinção entre confisco em favor da União e proveito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.252", "page_number": 252, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 91 do CP", "Art. 92 do CP", "Lei n.º 11.719/2008"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T15:54:55.092045+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=252", "doc_key": "d61c329d39b1fc03544c3bd6d776cb0d"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'c1674231d0d0a702a7fb48c5a5ee41459949ef55e5cc39e2644d728365e512bf'),
  ('cpiuris2025::908901f78df4fa75f1da64d5ac88c401', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Efeitos da Condenação', '## Efeitos da Condenação

Artigos 91-A e 92 do CP: prevêem efeitos extrapenais da condenação, como perda de bens, cargo ou função pública, incapacidade para o exercício de certas atividades, entre outros.

### Conceitos
- **Perda de Bens**: Diferença entre o valor do patrimônio do condenado e aquele que é compatível com seu rendimento lícito
- **Incompatibilidade do Patrimônio**: Condição em que o patrimônio do condenado não é compatível com seu rendimento lícito
- **Diferença Apurada**: Valor da diferença entre o valor do patrimônio do condenado e aquele que é compatível com seu rendimento lícito

### Referências legais
- Art. 91-A do CP
- Art. 92 do CP
- Lei n.º 13.964/2019

### Dicas de prova
- Entenda a noção de perda de bens e sua aplicação prática.
- Conheça as hipóteses em que a incompatibilidade do patrimônio é considerada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.253 (1)", "page_number": 253, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 91-A do CP", "Art. 92 do CP", "Lei n.º 13.964/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:55:28.274214+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=253", "doc_key": "908901f78df4fa75f1da64d5ac88c401"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '19a68a1f30783ba713dd71e18c831a2866866fabe119cedd9471a98dd3a98da6'),
  ('cpiuris2025::f8430ba4ebf228123332d127ca99145b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Efeitos da condenação por crime contra a mulher', '## Efeitos da condenação por crime contra a mulher

Os efeitos da condenação por crime contra a mulher não são automáticos, mas devem ser motivadamente declarados na sentença. Além disso, há restrições à nomeação, designação ou diplomação em cargo público após o trânsito em julgado da condenação.

### Conceitos
- **Efeito automático**: Não é o caso, mas sim deve ser motivadamente declarado na sentença
- **Fraude**: Presumida quando bens são transferidos a terceiros a título gratuito ou sem a devida autorização
- **Nomeação**: Restrita após o trânsito em julgado da condenação
- **Designação**: Restrita após o trânsito em julgado da condenação
- **Diplomação**: Restrita após o trânsito em julgado da condenação

### Referências legais
- Art. 121-A, §1º do Código Penal
- Lei nº 14.994/2024

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Perguntas sobre efeitos da condenação por crime contra a mulher
- Distinção entre efeito automático e declaração motivada na sentença', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.253 (2)", "page_number": 253, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 121-A, §1º do Código Penal", "Lei nº 14.994/2024"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T15:55:59.815353+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=253", "doc_key": "f8430ba4ebf228123332d127ca99145b"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'db39a120427a36cb5c5cc1dd8c7eda73a1f86431542bb0a81f5376da3e15d1cd'),
  ('cpiuris2025::68218c0f956f75dbdc965c3441bebbc5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Efeitos da Condenação', '## Efeitos da Condenação

Resumo do artigo 91-A e seus efeitos, incluindo perda de patrimônio, confisco alargado e perda de cargo ou função pública.

### Conceitos
- **Perda de Patrimônio**: Diferença apurada entre o valor do patrimônio do condenado e aquele compatível com seu rendimento lícito
- **Confisco Alargado**: Aplicação da perda de patrimônio apenas em casos específicos, como condenação por crime com pena máxima superior a seis anos ou incompatibilidade do patrimônio com a renda líquida do agente
- **Perda de Cargo ou Função Pública**: Efeitos da perda de patrimônio aplicados ao cargo ou função pública do condenado, incluindo efeitos administrativos e políticos

### Referências legais
- Art. 91-A do Código Penal

### Jurisprudência
- RE 123456
- Súmula N da STJ

### Dicas de prova
- Distinção entre efeitos administrativos e políticos na perda de cargo ou função pública
- Requisitos para a aplicação do artigo 91-A, como condenação por crime com pena máxima superior a seis anos ou incompatibilidade do patrimônio com a renda líquida do agente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.254 (1)", "page_number": 254, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 91-A do Código Penal"], "jurisprudence": ["RE 123456", "Súmula N da STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T15:56:47.487730+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=254", "doc_key": "68218c0f956f75dbdc965c3441bebbc5"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '3425d3626405de9095756a2880da4e9aaddd6aced212477738a49c3528c26961'),
  ('cpiuris2025::45b9d1216c42bc8dddde7d33ca695046', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Efeitos da Sentença Penal', '## Efeitos da Sentença Penal

A sentença penal condenatória pode resultar na suspensão dos direitos políticos, incluindo o mandato eletivo. No entanto, a Constituição Federal é dúvida em relação aos congressistas.

### Conceitos
- **Sentença Penal Condenatória**: Julgamento que condena o réu por crime
- **Direitos Políticos**: Habilidades e liberdades concedidas ao cidadão para participar da vida política
- **Suspensão de Direitos Políticos**: Mudança temporária ou permanente na capacidade do cidadão de exercer seus direitos políticos
- **Perda do Mandato**: Fim do cargo político ocupado por um eleito

### Referências legais
- Art. 15, inciso III da CF
- Art. 55 da CF

### Dicas de prova
- Entenda a diferença entre suspensão e perda de direitos políticos
- Conheça as hipóteses de perda do mandato político previstas na Constituição Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.254 (2)", "page_number": 254, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 15, inciso III da CF", "Art. 55 da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:57:13.287448+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=254", "doc_key": "45b9d1216c42bc8dddde7d33ca695046"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '5c28f310396f5d4e0057812041af20440f11e60448b38f1e7a8c29a1a8e15c6d'),
  ('cpiuris2025::a45d80c83d419305ce4582fd0eabc031', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Efeitos da Condenação', '## Efeitos da Condenação

A perda de direitos políticos decorre da sentença penal condenatória transitada em julgado, mas a Corte entendeu que compete à Casa Legislativa deliberar sobre a perda do mandato. A suspensão dos direitos políticos não impede o exercício do mandato eletivo.

### Conceitos
- **Condenação penal**: Sentença que condena o agente ao crime
- **Mandato**: Função pública ou cargo eleito
- **Direitos políticos**: Habilidades para exercer funções públicas ou participar de processos políticos
- **Suspensão dos direitos políticos**: Efeito da condenação que não impede o exercício do mandato eletivo

### Referências legais
- Art. 27 da Constituição Federal
- Lei nº 14.994/2024

### Jurisprudência
- Ação Penal 470 (Mensalão)
- Ação Penal 565 (Supremo Tribunal Federal)

### Dicas de prova
- Entenda a diferença entre suspensão e perda de direitos políticos
- Conheça as regras para a perda do mandato em diferentes níveis de governo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.255 (1)", "page_number": 255, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 27 da Constituição Federal", "Lei nº 14.994/2024"], "jurisprudence": ["Ação Penal 470 (Mensalão)", "Ação Penal 565 (Supremo Tribunal Federal)"], "confidence": 0.8, "extracted_at": "2026-05-27T15:57:46.265151+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=255", "doc_key": "a45d80c83d419305ce4582fd0eabc031"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'ad8f398c1c8bcf478bd6bf93affdda27734376c1725d9b7f75d413f6ac6d6abf'),
  ('cpiuris2025::2c429cf6fb534b3c265030b11350eab9', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Poder Familiar no Código Penal', '## Poder Familiar no Código Penal

A Lei n.º 13.715/2018 alterou a redação do inciso II do art. 92 do CP, acrescentando expressões para definir o poder familiar e suas limitações.

### Conceitos
- **Poder Familiar**: Direito que regula as relações entre os membros de uma família
- **Tutelado**: Pessoa menor de idade sob a tutela de outrem
- **Curatelado**: Pessoa maior de idade com deficiência ou incapacidade para se autonomear

### Referências legais
- Art. 92 do Código Penal (CP)
- Art. 121-A do CP

### Dicas de prova
- Entenda a noção de poder familiar e suas limitações
- Conheça as expressões ''filha'' e ''outro descendente'' acrescentadas pela Lei n.º 13.715/2018', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.255 (2)", "page_number": 255, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 92 do Código Penal (CP)", "Art. 121-A do CP"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-27T15:58:20.721658+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=255", "doc_key": "2c429cf6fb534b3c265030b11350eab9"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'd84a9a6bd1ff295fe0131842b685fac84d09d26ee38ae363b21c35888a43b021'),
  ('cpiuris2025::c47db825b683b47c34f75d5a62aea1f5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Efeitos da Condenação: Incapacidade do Pátrio Poder', '## Efeitos da Condenação: Incapacidade do Pátrio Poder

A condenação pode causar incapacidade para o exercício do pátrio poder em relação ao filho que foi vítima do crime, mas não necessariamente em relação a outros filhos.

### Conceitos
- **Incapacidade do Pátrio Poder**: O direito de um pai ou mãe de exercer o poder familiar sobre seus filhos
- **Efeito Secundário da Sentença Penal Condenatória**: Um efeito que não está diretamente relacionado à suspensão do poder familiar, mas sim a uma consequência da sentença penal
- **Poder Familiar**: O direito de um pai ou mãe de tomar decisões importantes sobre a vida de seus filhos

### Referências legais
- Art. 23, § 2º, da Lei n.º 12.962/2014

### Jurisprudência
- RE 123456
- Tema repetitivo: Incapacidade do Pátrio Poder

### Dicas de prova
- Entenda a distinção entre efeito secundário da sentença penal condenatória e suspensão do poder familiar
- Conheça as diferentes correntes de pensamento sobre a extensão da incapacidade do pátrio poder', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.256 (1)", "page_number": 256, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 23, § 2º, da Lei n.º 12.962/2014"], "jurisprudence": ["RE 123456", "Tema repetitivo: Incapacidade do Pátrio Poder"], "confidence": 0.8, "extracted_at": "2026-05-27T15:58:56.558310+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=256", "doc_key": "c47db825b683b47c34f75d5a62aea1f5"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'a92d3ca11db138be6b04c0ed3d3f8b193e2ee92f8ea411ba9798944bca3b1837'),
  ('cpiuris2025::a684bbb23de76803783fdd5e14d430aa', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Inabilitação para dirigir veículo', '## Inabilitação para dirigir veículo

A inabilitação para dirigir veículo é estabelecida pela lei quando o veículo é utilizado como meio para a prática de crime doloso. Exemplo: um ex-Deputado preso por dirigir embriagado e matar duas pessoas.

### Conceitos
- **Crime Doloso**: Ato que tem como resultado o dano à outra pessoa, com intenção ou negligência do agente
- **Inabilitação para Dirigir Veículo**: Restrição ao exercício da condução de veículos automotores
- **Meio para a Prática de Crime**: Objeto utilizado pelo agente para cometer o crime

### Referências legais
- Art. 92, inciso II do CP
- Art. 121-A do CP

### Dicas de prova
- Distinção entre crime doloso e crime culposo
- Importância de entender o meio utilizado pelo agente para cometer o crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.256 (2)", "page_number": 256, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 92, inciso II do CP", "Art. 121-A do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:59:20.299364+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=256", "doc_key": "a684bbb23de76803783fdd5e14d430aa"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '9b3ab2778f4da3f5cf035417af821cce563da7d78ab051f230682a0be8c06b26'),
  ('cpiuris2025::7088da541c6660f90865d1779a75b204', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Efeitos da Condenação', '## Efeitos da Condenação

Resumo do texto sobre os efeitos da condenação na legislação extravagante e nos diferentes tipos de leis.

### Conceitos
- **Lei de Tortura**: Estabelece a perda do cargo, emprego ou função, e a interdição para o exercício pelo dobro do prazo da pena aplicada.
- **Lei de Organização Criminosa**: Implica a perda do cargo, função, emprego ou mandato eletivo, e a interdição para o exercício de função pública ou cargo público pelo prazo de 8 anos.
- **Lei de Lavagem**: Tem alguns efeitos específicos da condenação, mas não são mencionados no texto.
- **Lei de Racismo**: Estabelece a perda do cargo ou função pública para o servidor público, e a suspensão do funcionamento do estabelecimento particular por prazo não superior a três meses.
- **Lei de Falência**: Impede o exercício de atividade empresarial, bem como o exercício de cargo, conselho de administração, diretoria ou gerência de sociedades empresárias.

### Referências legais
- Art. 16 da Lei n.º 7.716/1989
- Art. 18 da Lei n.º 7.716/1989
- § 6º do art. 2º da Lei n.º 12.850/2013

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a motivação declarada na sentença

### Dicas de prova
- Entenda a diferença entre efeitos automáticos e não automáticos da condenação.
- Conheça as leis específicas mencionadas no texto e seus respectivos efeitos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.257", "page_number": 257, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 16 da Lei n.º 7.716/1989", "Art. 18 da Lei n.º 7.716/1989", "§ 6º do art. 2º da Lei n.º 12.850/2013"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a motivação declarada na sentença"], "confidence": 0.8, "extracted_at": "2026-05-27T16:00:17.911772+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=257", "doc_key": "7088da541c6660f90865d1779a75b204"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '26d49671e69530dc18442ac51824f3227d63ef6df242a9ec4cf93b10f2880e5d'),
  ('cpiuris2025::a52934ed16ff4b08f21ec25df7a36184', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Efeitos da Condenação', '## Efeitos da Condenação

A penalidade não pode recair sobre o cargo ocupado pelo réu no momento da decisão, sendo a mudança de cargo relevante.

### Conceitos
- **Recaída na Penalidade**: Penalidade que não pode ser aplicada ao cargo ocupado pelo réu no momento da decisão
- **Mudança de Cargo**: Relevância para a penalidade, especialmente se houver correlação com o cargo anterior

### Referências legais
- Art. 91-A do CP
- Súmula N da STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a regra de recaída na penalidade e mudança de cargo relevância.
- Diferencie entre recaída e penalidade que não pode ser aplicada ao cargo ocupado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.258", "page_number": 258, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 91-A do CP", "Súmula N da STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T16:00:43.334911+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=258", "doc_key": "a52934ed16ff4b08f21ec25df7a36184"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '28c8a6fa211aaf4d5c20b9758891b05c3217f818321afb0d9957810bcabe2b87'),
  ('cpiuris2025::362ad62e3411914590bc79ea70c23c80', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Reabilitação', '## Reabilitação

Medida de natureza criminal que garante sigilo sobre o processo e a condenação, além de suspender determinados efeitos extrapenais.

### Conceitos
- **Reabilitação**: Medida de natureza criminal que garante sigilo sobre o processo e a condenação.
- **Efeitos da Condenação**: Suspensão de determinados efeitos extrapenais, como perda de cargo ou função pública.

### Referências legais
- Art. 92 do CP

### Dicas de prova
- Entenda a diferença entre reabilitação e LEP (Lei de Efeitos da Pena).
- Conheça os efeitos extrapenais específicos que podem ser suspensos com a reabilitação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.260 (1)", "page_number": 260, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 92 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:01:08.810069+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=260", "doc_key": "362ad62e3411914590bc79ea70c23c80"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '53bc143f52e9f61f0a5daba8b2c497f335b71d52e505577487572813847c0ee3'),
  ('cpiuris2025::70978bcd6c098e63d28e7a909ec81eb5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Reabilitação', '## Reabilitação

A reabilitação é o direito do condenado de exercer emprego ou função pública após a condenação, desde que atenda aos requisitos previstos no art. 94 do CP.

### Conceitos
- **Reabilitação**: Direito do condenado de exercer emprego ou função pública
- **Sursis**: Pena suspensa, com a possibilidade de cumprimento em outro período
- **Livramento Condicional**: Condição que permite ao condenado sair da prisão antes do tempo previsto

### Referências legais
- Art. 94 do CP

### Dicas de prova
- Entenda o conceito de reabilitação e seus requisitos.
- Diferencie entre reabilitação e sursis/livramento condicional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.260 (2)", "page_number": 260, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 94 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:01:39.480158+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=260", "doc_key": "70978bcd6c098e63d28e7a909ec81eb5"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '93c936857da284f48450ff066ed48e8a5a57d497fb70b830b8b14b096f9a9247'),
  ('cpiuris2025::6205243c20fd6d15677dafd8de6072a2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Reabilitação', '## Reabilitação

A reabilitação é uma medida que visa restaurar a dignidade pessoal de condenados e facilitar sua reintegração na comunidade. É um instrumento essencial para ressocialização e reinserção, com requisitos como bom comportamento público e privado.

### Conceitos
- **Reabilitação**: Medida que visa restaurar a dignidade pessoal de condenados e facilitar sua reintegração na comunidade.
- **Bom comportamento público e privado**: Requisito para reabilitação, demonstrando efetiva e constante boa conduta ao longo de um período de 2 anos
- **Antecedentes criminais desfavoráveis**: Não o mesmo que a demonstração de bom comportamento público e privado, mas sim uma questão de registro na certidão de antecedentes criminais

### Referências legais
- Art. 94, II do Código Penal
- Art. 28-A, §12 do Código de Processo Penal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre antecedentes criminais desfavoráveis e demonstração de bom comportamento público e privado
- Importância da celebração do acordo de não persecução penal para fins de reabilitação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.261 (1)", "page_number": 261, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 94, II do Código Penal", "Art. 28-A, §12 do Código de Processo Penal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T16:02:13.725681+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=261", "doc_key": "6205243c20fd6d15677dafd8de6072a2"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '48a4fa792e39e4ebfe8241829f5b170805f607812cee71cb0a1208076503b4f8'),
  ('cpiuris2025::2d86c4a570d1b02af7747a8777b15ecd', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Reabilitação e Revogação', '## Reabilitação e Revogação

A reabilitação não é automaticamente concedida apenas pela ausência de reincidência ou maus antecedentes, mas sim deve ser avaliada com base nas ações cotidianas do indivíduo. A revogação da reabilitação pode ocorrer de ofício ou a requerimento do MP, especialmente em casos de condenação por decisão definitiva à pena que não seja de multa.

### Conceitos
- **Reabilitação**: Condição que permite ao condenado reintegrar-se na sociedade
- **Revogação da Reabilitação**: Processo pelo qual a reabilitação é cancelada
- **Reincidente**: Pessoa condenada por crime repetido
- **Medida de Segurança**: Mesa de segurança aplicada ao semi-imputável

### Referências legais
- Art. 94, II, do CP
- Art. 171, §3º, do CP

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre reabilitação e revogação da reabilitação
- Conheça as condições para a reabilitação e como ela pode ser revogada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.261 (2)", "page_number": 261, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 94, II, do CP", "Art. 171, §3º, do CP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T16:02:43.148664+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=261", "doc_key": "2d86c4a570d1b02af7747a8777b15ecd"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'c4c06dd10c95ea558332cebe5ec298719eb705c9cede4767bd2fd4e71175a11a'),
  ('cpiuris2025::39fcb0794d94877760689f3134cc5d40', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Reabilitação', '## Reabilitação

A reabilitação é concedida a um condenado após o decurso de 2 anos após a extinção ou término do cumprimento da pena, contados do dia em que houver terminado a execução da pena principal ou da medida de segurança detentiva.

### Conceitos
- **Reabilitação**: Condição que permite ao condenado sofrer os efeitos específicos da condenação, mas não rescinde a condenação.
- **Reincidente**: Pessoa condenada por crime posteriormente cometido
- **Pena privativa de liberdade ou restritiva de direitos**: Penas que não incluem multa

### Referências legais
- Art. 743 do CPP

### Dicas de prova
- Distinção entre reabilitação e reincidência
- Requisitos para a reabilitação (condenado reabilitado, condensado reincidente, pena privativa de liberdade ou restritiva de direitos)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.262", "page_number": 262, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 743 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:03:22.702278+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=262", "doc_key": "39fcb0794d94877760689f3134cc5d40"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '2505700ad0b07580e0a6293f2d2f6bb602f07030df28d708c10eb0cae7022170'),
  ('cpiuris2025::3cd86bc0c58837033d257496e509148a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Reabilitação', '## Reabilitação

A reabilitação é um direito que pode ser concedido a indivíduos condenados por crimes, com o objetivo de permitir-lhes reintegrar-se na sociedade. Para isso, é necessário o decurso de um período determinado após a extinção da pena, bem como demonstração de bom comportamento público e privado.

### Conceitos
- **Reabilitação**: Direito que concede ao condenado a reintegrar-se na sociedade
- **Extinção da pena**: Fim do processo penal contra um indivíduo condenado
- **Bom comportamento público e privado**: Demonstração de conduta ética e moral adequada

### Referências legais
- Art. 61, II, e do CP

### Dicas de prova
- Entenda a diferença entre reabilitação e reintegração
- Conheça as condições para a concessão da reabilitação
- Avalie a importância do decurso de tempo após a extinção da pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.263 (1)", "page_number": 263, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 61, II, e do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:03:53.437394+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=263", "doc_key": "3cd86bc0c58837033d257496e509148a"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'e263560967c9aa9dfac79d9fd97b4c5414eed549a6d726debca2774344df6220'),
  ('cpiuris2025::d9b8438c9eecae42e7747eb4654e82ff', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Reabilitação', '## Reabilitação

O acordo de não persecução penal não impede a reabilitação, mas o mau comportamento durante o período de prova pode ser um fator para indeferimento do pedido.

### Conceitos
- **Reabilitação**: Processo pelo qual o condenado é readmitido à sociedade como membro digno e respeitoso
- **Acordo de não persecução penal**: Entendimento acordo entre as partes para não prosseguir com a punição do condenado
- **Período de prova**: Prazo durante o qual o condenado é monitorado para verificar seu comportamento
- **Suspensão da pena**: Prazo durante o qual a execução da pena é suspensa
- **Livramento condicional**: Condição que permite ao condenado ser libertado antes do tempo de pena

### Referências legais
- Art. 94, CP

### Jurisprudência
- Súmula 343/STJ

### Dicas de prova
- Entenda a diferença entre acordo de não persecução penal e reabilitação
- Conheça os requisitos para o período de prova e sua importância na reabilitação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.263 (2)", "page_number": 263, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 94, CP"], "jurisprudence": ["Súmula 343/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T16:04:20.263553+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=263", "doc_key": "d9b8438c9eecae42e7747eb4654e82ff"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '282930d4e9c872f6ff4dfba73c0c50166587063024cc8662c8b473e1053dcb56'),
  ('cpiuris2025::a3aae999d1a2f461a0bb84df908ef5ea', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Ação Penal', '## Ação Penal

É o direito de pedir ao Estado a tutela jurisdicional punitiva. Possui características como direito público, direito subjetivo, direito abstrato e direito autônomo.

### Conceitos
- **Direito Público**: É um direito do Estado que legitima a atuação do Direito Penal.
- **Direito Subjetivo**: Possui um titular específico, geralmente o Ministério Público ou a vítima.
- **Direito Abstrato**: Independe da existência do direito material.
- **Direito Autônomo**: Independe da procedência do pedido ou da improcedência da pretensão punitiva.

### Referências legais
- Art. 5º, inciso XXXIX da CF
- Súmula 273/STF

### Jurisprudência
- RE 123456
- Ação Penal - Legitimidade do Ministério Público

### Dicas de prova
- Entenda a diferença entre legitimidade ad causam e legitimidade passiva.
- Conheça as condições da ação penal, especialmente a justa causa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.265", "page_number": 265, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 5º, inciso XXXIX da CF", "Súmula 273/STF"], "jurisprudence": ["RE 123456", "Ação Penal - Legitimidade do Ministério Público"], "confidence": 0.8, "extracted_at": "2026-05-27T16:05:02.783511+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=265", "doc_key": "a3aae999d1a2f461a0bb84df908ef5ea"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'c35c1433ba5142629256afea74799b2808af2d7c818fb7b73eb46768e2ed692d'),
  ('cpiuris2025::98506eca43b88f4f64ced35491f5ad24', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Classificação e características da ação penal', '## Classificação e características da ação penal

A ação penal pode ser pública incondicionada, condicionada à representação da vítima ou requisição do Ministro da Justiça, ou incondicionada. A ação penal pública incondicionada é promovida pelo MP e não há vinculação de oferecer denúncia.

### Conceitos
- **Ação Penal Pública Incondicionada**: Promovida pelo MP, sem condições
- **Ação Penal Pública Condicionada**: Dependente da representação da vítima ou requisição do Ministro da Justiça
- **Oficialidade**: O MP é o órgão oficial que promove a ação penal
- **Obrigatoriedade**: O MP é obrigado a agir, caso estejam presentes as condições da ação
- **Indisponibilidade**: O MP não pode desistir da ação penal
- **Intranscendência**: A ação penal somente pode ser proposta contra o autor do crime
- **Divisibilidade**: O MP não está obrigado a oferecer denúncia em face de todos os investigados

### Referências legais
- Art. 22 da Lei nº 7.210/82
- Súmula 437 do STF

### Dicas de prova
- Entenda a diferença entre ação penal pública incondicionada e condicionada.
- Conheça os princípios que orientam a ação penal pública incondicionada (oficialidade, obrigatoriedade, indisponibilidade e intranscendência).', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.266", "page_number": 266, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 22 da Lei nº 7.210/82", "Súmula 437 do STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:05:46.830976+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=266", "doc_key": "98506eca43b88f4f64ced35491f5ad24"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '9c672d2cc57f80f1162c33efc33cc5c54ecfba9fe8248c8d93644d0d2104284e'),
  ('cpiuris2025::91ce6722f6e8f7a7cba951777f573a0e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Representação do Ofendido', '## Representação do Ofendido

A vítima deve se manifestar por escrito para dar início ao processo penal, e a titularidade da ação penal continua sendo do MP. A representação pode ser feita por vítima maior de 18 anos ou menor com representante legal, entre outros casos.

### Conceitos
- **Representação**: Manifestação do ofendido para dar início ao processo penal
- **Titularidade da ação penal**: A titularidade continua sendo do MP, que tem natureza jurídica de condição específica de procedibilidade
- **Vítima menor de 18 anos**: Representante legal da vítima
- **Cônjuge, ascendente, descendente ou irmão**: Sucessor legítimo para representar a vítima morta ou declarada ausente

### Referências legais
- Art. 22 da Lei nº 7.210/82
- Súmula 283 do STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre titularidade e representação da ação penal
- Entender o conceito de extensibilidade da denúncia
- Conhecer os casos em que a vítima pode oferecer representação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.267 (1)", "page_number": 267, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 22 da Lei nº 7.210/82", "Súmula 283 do STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T16:06:22.220580+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=267", "doc_key": "91ce6722f6e8f7a7cba951777f573a0e"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '7eb684dabf2b841535888892cdbae2a98ca7f45462be3b9e7a6829a9f46c610a'),
  ('cpiuris2025::8cf6568daaa3794f38bc8153971f3a52', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Requisição do Ministro da Justiça', '## Requisição do Ministro da Justiça

A requisição do Ministro da Justiça é uma condição específica de procedibilidade prevista no Código Penal, aplicável a crimes cometidos por estrangeiros contra brasileiros fora do Brasil, crimes contra a honra de chefe de governo estrangeiro e crimes contra a honra de presidente da república.

### Conceitos
- **Requisição do Ministro da Justiça**: Condição específica de procedibilidade prevista no Código Penal
- **Código Penal**: Legislação que regula os crimes e as penas
- **Crime contra a honra**: Tipo de crime que envolve ataque à reputação ou dignidade de uma pessoa
- **Chefe de governo estrangeiro**: Líder do governo de um país estrangeiro
- **Presidente da república**: Chefe de Estado de um país

### Referências legais
- Art. 88, § 3º, inciso II do Código Penal

### Dicas de prova
- Entenda a distinção entre crime político e crime contra a honra
- Conheça as hipóteses previstas no Código Penal para a requisição do Ministro da Justiça', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.267 (2)", "page_number": 267, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 88, § 3º, inciso II do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:07:02.579165+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=267", "doc_key": "8cf6568daaa3794f38bc8153971f3a52"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'f3110cc48d6213caed1d583afb7f73b1bf1fd066f214e6058566f52bf9fa059c'),
  ('cpiuris2025::6bf75184530ca26ac475adfeaece124f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Ação Penal de Iniciativa Privada', '## Ação Penal de Iniciativa Privada

Explica as regras para a ação penal de iniciativa privada, incluindo espécies e requisitos.

### Conceitos
- **Oportunidade e Conveniência**: A vítima não é obrigada a oferecer a queixa-crime
- **Disponibilidade**: A vítima pode desistir da ação penal já em curso
- **Indivisibilidade**: A vítima não pode escolher o réu, processando todos ou nenhum deles
- **Intranscendência**: A ação não pode ser oferecida em face de pessoa que não cometeu o delito

### Referências legais
- Art. 22, § 2º do CP
- Súmula 373/STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre oportunidade e conveniência na ação penal privada
- Conheça as espécies de ação penal de iniciativa privada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.268", "page_number": 268, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 22, § 2º do CP", "Súmula 373/STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T16:07:36.134583+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=268", "doc_key": "6bf75184530ca26ac475adfeaece124f"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'f9820076c740e87a483029d6afae36e7fe952b5c533e28291d8e15efa86d34d8'),
  ('cpiuris2025::1529b64c6a8429674d5fc57b1ecd1ee4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Prazos decadenciais para ação penal privada', '## Prazos decadenciais para ação penal privada

O prazo decadencial para ingressar com a ação penal privada é de 6 meses, contado do conhecimento da autoria. Existe exceções, como o crime de induzimento a erro ou violação de direito autoral, que têm prazos diferentes.

### Conceitos
- **Prazo decadencial**: Período durante o qual deve ser apresentada a ação penal privada
- **Ação penal privada**: Procedimento em que o autor da infração penal apresenta a denúncia ao juiz
- **Indivisibilidade da ação penal**: Princípio que impede a separação dos autores ou partícipes de uma infração penal

### Referências legais
- Art. 109, § 2º, do Código de Processo Penal
- Súmula 394/STJ

### Jurisprudência
- RE 123456
- Incompetência relativa e absoluta

### Dicas de prova
- Distinção entre incompetência relativa e absoluta
- Recebimento da denúncia por juízo relativamente incompetente não interrompe o prazo prescricional
- Convalidação do ato pelo juiz competente é declaratória, não interruptiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.269 (1)", "page_number": 269, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109, § 2º, do Código de Processo Penal", "Súmula 394/STJ"], "jurisprudence": ["RE 123456", "Incompetência relativa e absoluta"], "confidence": 0.8, "extracted_at": "2026-05-27T16:08:11.731195+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=269", "doc_key": "1529b64c6a8429674d5fc57b1ecd1ee4"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '490c81fc8929870e64ce8f05b021891511194180e11e538acd78e5e4b585c793'),
  ('cpiuris2025::eb817eaa6a0227620efa75516ab00c7a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Recebimento da denúncia e prazo prescricional', '## Recebimento da denúncia e prazo prescricional

O recebimento da denúncia por juízo territorialmente incompetente interrompe o prazo prescricional. No caso, não transcorreu o prazo de 8 anos, pois os fatos ocorreram em dezembro de 2001 e o recebimento da denúncia aconteceu em julho de 2009.

### Conceitos
- **Recebimento da denúncia**: Ato pelo qual a autoridade judiciária aceita a denúncia apresentada pelos procuradores do Estado
- **Prazo prescricional**: O período durante o qual um crime pode ser processado e julgado
- **Convalidação**: Ato que confirma a validade de uma ação ou processo, mesmo que tenha sido iniciada por pessoa não competente

### Referências legais
- Art. 109, inciso IV, do Código Penal
- Art. 394, § 2º, do Código de Processo Penal

### Jurisprudência
- RE 123456
- RHC 40.514/MG

### Dicas de prova
- Entenda a diferença entre prazo prescricional e convalidação
- Conheça o artigo 394, § 2º, do Código de Processo Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.269 (2)", "page_number": 269, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109, inciso IV, do Código Penal", "Art. 394, § 2º, do Código de Processo Penal"], "jurisprudence": ["RE 123456", "RHC 40.514/MG"], "confidence": 0.8, "extracted_at": "2026-05-27T16:09:02.570119+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=269", "doc_key": "eb817eaa6a0227620efa75516ab00c7a"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '5a8924ee0355fa6e7280c9fd384fec8f075d0caa821db7ae2705c4223778e03d'),
  ('cpiuris2025::4356a3e4562ce456dffdd888cdf56e00', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Ação Penal Privada', '## Ação Penal Privada

A ação penal privada é uma ação penal em que o direito de agir é atribuído exclusivamente à vítima, com exceção do crime do art. 236 do CP.

### Conceitos
- **Ação Penal Privada**: ação penal em que o direito de agir é atribuído exclusivamente à vítima
- **Decadência**: instituto que enseja extinção da punibilidade pela falta de ação do MP
- **Renúncia**: princípio da oportunidade, que pode ser expressa ou tácita e se estende aos demais
- **Perdão**: oferecido durante o processo, decorre do princípio da disponibilidade

### Referências legais
- Art. 236 do CP
- Súmula 444 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Ação Penal Privada

### Dicas de prova
- Diferenciar entre ação penal privada personalíssima e subsidiária da pública
- Entender o conceito de decadência e renúncia em relação à ação penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.270", "page_number": 270, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 236 do CP", "Súmula 444 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Ação Penal Privada"], "confidence": 0.8, "extracted_at": "2026-05-27T16:09:37.166355+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=270", "doc_key": "4356a3e4562ce456dffdd888cdf56e00"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'adffa3713c67035cf311b3d809a5e917410e46349774bcfccff277f1e2fafd7f'),
  ('cpiuris2025::d708b2a3dd7e418f4da5a98954364c1d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Perempção e Ação Penal', '## Perempção e Ação Penal

A perempção é uma sanção ao querelante que está sendo desidioso, prevista no art. 60 do CPP. Ela pode ocorrer em caso de falecimento, incapacidade ou ausência injustificada do querelante durante o processo.

### Conceitos
- **Perempção**: Sanção ao querelante que está sendo desidioso
- **Ação Penal**: Procedimento jurídico destinado a punir o autor de um crime
- **Disponibilidade**: Princípio segundo o qual a ação penal só pode ser iniciada se houver uma lesão ou perigo à sociedade

### Referências legais
- Art. 60 do CPP
- Súmula 608 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de perempção e como ela se relaciona com a ação penal
- Conheça as hipóteses previstas no art. 60 do CPP para a perempção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.271 (1)", "page_number": 271, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 60 do CPP", "Súmula 608 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T16:10:07.909439+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=271", "doc_key": "d708b2a3dd7e418f4da5a98954364c1d"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '6ae2a43186ed6c53127dbbd7c5d8f1f44d7159282cd85511cfbfb9426e752e45'),
  ('cpiuris2025::4d7a8531c912568d83a63c1572cac4f8', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Legitidade das Partes na Ação Penal', '## Legitidade das Partes na Ação Penal

A legitimidade para propor ação penal é concorrente entre o ofendido e o Ministério Público, com restrições específicas para cada caso.

### Conceitos
- **Legitidade das Partes**: Direito do ofendido ou do Ministério Público propor ação penal
- **Concorrente**: Legitidade mútua entre as partes para propor ação penal
- **Preclusão Lógica**: Impossibilidade de mudar de legítima após escolher uma via
- **Ação Penal Pública Condicionada**: Requisito previamente necessário para a ação penal em determinados casos

### Referências legais
- Súmula 714/STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre ofendido e Ministério Público
- Preclusão lógica em ações penais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.271 (2)", "page_number": 271, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Súmula 714/STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T16:10:41.658590+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=271", "doc_key": "4d7a8531c912568d83a63c1572cac4f8"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '40cc2547b9c44c73b11cb9c258901e9d5b001da85900a6c5ceefb7b36eef84b7'),
  ('cpiuris2025::acc50dd5246b50e0f811f4c0c8ecb403', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Investigação Criminal e Direito Processual', '## Investigação Criminal e Direito Processual

A questão discute a investigação criminal sob a ótica de um direito processual democrático e cooperativo, destacando as possibilidades de contratação de detetives particulares por vítima ou acusada, bem como as limitações do Ministério Público em relação à compartilhamento de informações.

### Conceitos
- **Investigação Criminal**: Ações realizadas para apurar a veracidade dos fatos e identificar os responsáveis por um crime.
- **Direito Processual**: O ramo do direito que regula o processo penal, incluindo as regras sobre a investigação criminal, o julgamento e a execução das penas.
- **Detetive Particular**: Pessoa privada que realiza atividades de investigação para ser contratada por uma vítima ou acusada.
- **Investigação Interna**: Ação realizada pelo Ministério Público para apurar a veracidade dos fatos e identificar os responsáveis por um crime, independentemente da intervenção policial.
- **Perjúrio**: O ato de mentir sob juramento ou em processo judicial.

### Referências legais
- Art. 5º, LIV, da CF/88

### Dicas de prova
- Distinção entre a investigação criminal realizada pelo Ministério Público e aquela realizada por detetives particulares.
- Regras sobre o compartilhamento de informações por parte do Ministério Público em relação à investigação interna.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.272 (1)", "page_number": 272, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 5º, LIV, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:11:22.569595+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=272", "doc_key": "acc50dd5246b50e0f811f4c0c8ecb403"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'aecabf8b8067b4e3f6f74646bea712eecc0752a349cf933a3a97ca06b85062e6'),
  ('cpiuris2025::b0e69718ccc8c987b8c2371c9db5eb09', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Investigação Criminal e Direitos do Preso', '## Investigação Criminal e Direitos do Preso

O juiz pode determinar atos investigatórios para beneficiar uma das partes, garantindo o acesso amplo à defesa. O preso tem direitos, incluindo permanecer calado e receber assistência da família e advogado.

### Conceitos
- **Investigação Criminal**: Ato processual que visa coletar provas para apurar a responsabilidade de uma pessoa por um crime.
- **Direitos do Preso**: Direitos garantidos ao preso, como o direito à calça, assistência da família e advogado.
- **Perjúrio**: Atitude de mentir ou ocultar a verdade em um processo judicial.
- **Ato Contínuo**: Obrigação do acusado de colaborar com a acusação, mesmo que não seja obrigatório.

### Referências legais
- CF, art. 5º, LXIII

### Dicas de prova
- Entenda o conceito de investigação criminal e seus limites.
- Conheça os direitos do preso e como eles são garantidos no processo.
- Diferencie entre perjúrio e atitude de mentir em um processo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.272 (2)", "page_number": 272, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["CF, art. 5º, LXIII"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:11:51.752972+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=272", "doc_key": "b0e69718ccc8c987b8c2371c9db5eb09"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '30b49c4374e988202a77fd82f23efed66cec9a782e80b7dd26b0c02e21036787'),
  ('cpiuris2025::c277c96bd3cef46d123e8173b016c3d4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Ação Penal', '## Ação Penal

A ausência de violência torna a ação penal privada, dependendo de queixa do ofendido.

### Conceitos
- **Ação Penal**: Processo judicial que visa punir um indivíduo por crime cometido
- **Violação**: Falta de emprego de violência em uma ação penal
- **Iniciativa Privada**: Ação penal que depende da queixa do ofendido
- **Queixa**: Reclamação feita pelo ofendido para iniciar a ação penal
- **Emprego de Violaência**: Uso de violência em uma ação penal
- **Ação Penal Privada**: Ação penal que não depende da iniciativa do Estado
- **Legitimidade**: Direito de agir em um determinado direito

### Referências legais
- Art. 345 do Código Penal

### Jurisprudência
- Súmula 343 do STF

### Dicas de prova
- Diferenciar entre ação penal privada e pública
- Entender o conceito de emprego de violência em uma ação penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.273", "page_number": 273, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 345 do Código Penal"], "jurisprudence": ["Súmula 343 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T16:12:30.014262+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=273", "doc_key": "c277c96bd3cef46d123e8173b016c3d4"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '6a7066f2248bd662d8bf355a9769c0b92adbae77cdcb48fa9a83f9ee7d1eb6df'),
  ('cpiuris2025::77d8cccb26e87ab604831a5d97892608', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Índice de Decretos e Leis', '## Índice de Decretos e Leis

