  ('cpiuris2025::64e9cf7c2685e0baa1cd8ce6bb6c2b48', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Introdução ao Direito Previdenciário', '## Introdução ao Direito Previdenciário

Resumo objetivo: Este texto apresenta uma visão geral do Direito Previdenciário, destacando sua importância e estrutura. É uma introdução ao tema, abordando suas principais características.

### Conceitos
- **Direito Previdenciário**: Brancha do direito que regula a previdência social no Brasil
- **Previdência Social**: Instituição pública que fornece benefícios a trabalhadores e pensionistas

### Referências legais
- Art. 40 da Constituição Federal de 1988

