  ('cpiuris2025::160b39a5f5cb8eff02ff63fa186344d8', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Origem e Conceito do Direito Previdenciário', '## Origem e Conceito do Direito Previdenciário

O direito previdenciário tem origem na seguridade social, com evolução histórica no mundo e no Brasil.

### Conceitos
- **Hierarquia das normas**: Ordem lógica das normas que regem o direito previdenciário
- **Seguridade Social**: Sistema de segurança social que regula a previdência social
- **Evolução histórica**: Mudanças e desenvolvimentos ao longo do tempo no direito previdenciário
- **Benefícios Eventuais**: Benefícios temporários concedidos pela seguridade social
- **Previdência Social**: Sistema que regula a previdência social e seus objetivos
- **Princípios Constitucionais Específicos**: Regras constitucionais que regulam o sistema de seguridade social
- **Solidariedade**: Princípio que exige a solidariedade entre os contribuintes e os beneficiários

### Referências legais
- Art. 40 da Constituição Federal
- Súmula 342 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Seguridade Social

### Dicas de prova
- Entenda a hierarquia das normas no direito previdenciário
- Conheça os benefícios eventuais e seus requisitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.4 (1)", "page_number": 4, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 40 da Constituição Federal", "Súmula 342 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Seguridade Social"], "confidence": 0.8, "extracted_at": "2026-05-27T16:15:32.161024+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=4", "doc_key": "160b39a5f5cb8eff02ff63fa186344d8"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'cb7419d78331724d7c9191066e704a1a166b77b45596346ce53bbe374b9f0608'),
  ('cpiuris2025::b2d559f0103831655aa6364b8d5afed0', 'doutrina', 'cp_iuris', 'Direito Previdenciaro — Princípios Gerais da Previdência Social', '## Princípios Gerais da Previdência Social

São apresentados vários princípios que regem a previdência social, incluindo universalidade, uniformidade, equidade e democracia.

### Conceitos
- **Universalidade**: A cobertura deve ser universal, abrangendo todos os trabalhadores.
- **Uniformidade**: Os benefícios devem ser uniformes em relação às condições de trabalho e aos custos de saúde.
- **Equivalência**: Os benefícios devem ser equivalentes para todos os trabalhadores.
- **Seletividade**: A seleção dos benefícios deve ser feita com base em critérios objetivos e neutros.
- **Distributividade**: Os benefícios devem ser distribuídos de forma justa e equitativa.
- **Irredutibilidade do valor dos benefícios**: O valor dos benefícios não pode ser reduzido ou alterado.
- **Equidade**: A administração da previdência social deve agir com equidade e justiça.
- **Diversidade da base de financiamento**: A base de financiamento da previdência social pode variar.

### Referências legais
- Art. 40 da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância dos princípios da universalidade e uniformidade.
- Conheça os critérios de seleção dos benefícios previdenciários.
- Aprenda a aplicar o princípio da equidade na administração da previdência social.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.4 (2)", "page_number": 4, "discipline": "Direito Previdenciaro", "legal_refs": ["Art. 40 da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T16:16:09.663748+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=4", "doc_key": "b2d559f0103831655aa6364b8d5afed0"}'::jsonb, '{"materia": "Direito Previdenciaro"}'::jsonb, 'cp_iuris_2025', '65bf8051e2d67e9d2035b2f8e8f364333dbac28acb794799a0c8c423a21ba92e'),
