- **Base do Sistema Previdenciário**: O valor total das contribuições pagas pelos empregados e empregadores
- **Estrutura das Contribuições Previdenciárias**: A organização da contribuição previdenciária em diferentes tipos, como GILRAT
- **Contribuições das Empresas**: As contribuições pagas pelas empresas para o sistema previdenciário
- **Folha de Pagamento**: O documento que contém as informações sobre a remuneração e as contribuições do empregado
- **Contribuições Adicionais: GILRAT**: As contribuições adicionais pagas pelos empregadores para o sistema previdenciário

