  ('cpiuris2025::4f14ea6ea7ccf3ec88864047c79f4cef', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Benefícios e Salários', '## Benefícios e Salários

Descreve os benefícios previdenciários, incluindo auxílios, salário-maternidade, pensão por morte, entre outros, bem como as regras de transição.

### Conceitos
- **Auxílio-Doença**: Benefício pago aos segurados que sofrerem acidente ou doença que os impedir de exercer a atividade profissional
- **Salário-Maternidade**: Benefício pago às mulheres que estão grávidas ou têm filhos
- **Pensão por Morte**: Benefício pago aos dependentes do falecido segurado
- **Auxílio-Reclusão**: Benefício pago aos segurados que estão reclusos
- **Sustentabilidade dos Benefícios**: Regra que estabelece limites para a duração dos benefícios previdenciários

