  ('cpiuris2025::b6ff835877462d0c6d170f15ffd694b7', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Aposentadorias do RGPS', '## Aposentadorias do RGPS

Regras e critérios para aposentadorias no regime geral de previdência social, incluindo benefícios previdenciários, aposentadoria por incapacidade permanente e aposentadoria programada.

### Conceitos
- **Benefício Previdenciário**: benefício concedido pelo INSS ao segurado que atende aos critérios estabelecidos pela lei
- **Aposentadoria por Incapacidade Permanente**: benefício concedido ao segurado que sofreu lesão ou doença que o torna incapaz de trabalho
- **Acréscimo de 25%**: acréscimo de 25% ao valor do benefício para aposentadorias por incapacidade permanente
- **Data de Início do Pagamento**: data em que o segurado começa a receber o benefício
- **Aposentadoria Programada**: benefício concedido ao segurado que escolheu a data da aposentadoria

### Referências legais
- Art. 104 da Lei nº 8.213/1991

### Dicas de prova
- Entenda a classificação dos benefícios previdenciários e os critérios para aposentadorias
- Conheça o conceito de aposentadoria por incapacidade permanente e como é calculado o benefício', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.6 (2)", "page_number": 6, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 104 da Lei nº 8.213/1991"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:20:17.276954+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=6", "doc_key": "b6ff835877462d0c6d170f15ffd694b7"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'e829d73466223c1a9c8c11c84f0a3dd7a56e8ce9c7a14003c79290859bc9ddfc'),
