### Conceitos
- **Salário-Família**: Benefício previdenciário concedido aos dependentes de um beneficiário
- **Dependente**: Pessoa que depende econômica do beneficiário
- **Evento Determinante**: Acontecimento que determina a concessão ou não da Salário-Família
- **Carência**: Período durante o qual o benefício não é pago
- **Cálculo**: Procedimento para calcular o valor do benefício

