  ('cpiuris2025::ad8fc2a3163e84e62a4ac305a25994c2', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Origem e Conceito do Direito Previdenciário', '## Origem e Conceito do Direito Previdenciário

O Direito Previdenciário é uma disciplina dinâmica, com constantes atualizações legais e normativas. É essencial compreender as normas que estruturam essa área, sua hierarquia e como elas se inter-relacionam.

### Conceitos
- **Hierarquia das normas**: Normas jurídicas organizadas em uma ordem lógica
- **Constituição Federal de 1988**: Base do ordenamento jurídico, definindo princípios fundamentais da seguridade social
- **Lei nº 8.212/1991**: Regula a arrecadação de recursos para financiar a seguridade social
- **Lei nº 8.213/1991**: Estabelece regras para concessão dos benefícios previdenciários
- **Decreto nº 3.048/1999**: Detalha a aplicação das leis previdenciárias e serve como guia prático
- **Abstração**: Tratam de situações hipotéticas ou generalizadas, que só se concretizam mediante a ocorrência de fatos específicos
- **Generalidade**: Aplicam-se a destinatários indeterminados, abrangendo todos os sujeitos enquadrados nas hipóteses normativas
- **Imperatividade**: Possuem caráter coercitivo, exigindo seu cumprimento por todos os cidadãos e entes públicos

### Referências legais
- Art. 5º da Constituição Federal de 1988
- Lei nº 8.212/1991
- Lei nº 8.213/1991
- Decreto nº 3.048/1999

### Dicas de prova
- Entenda a hierarquia das normas no Direito Previdenciário
- Conheça as principais leis que regem a seguridade social
- Aprenda com os conceitos-chave do Direito Previdenciário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.9", "page_number": 9, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 5º da Constituição Federal de 1988", "Lei nº 8.212/1991", "Lei nº 8.213/1991", "Decreto nº 3.048/1999"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:24:12.508055+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=9", "doc_key": "ad8fc2a3163e84e62a4ac305a25994c2"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'e87426d9826140a27489a5e1008fdf76eae19c2ac6aa30d17ef72a39a8525e90'),
  ('cpiuris2025::40ee5cc48fbc34ff70830bbfd0cc343a', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Regulamento da Previdência Social e alterações legislativas recentes', '## Regulamento da Previdência Social e alterações legislativas recentes

O Regulamento da Previdência Social foi ajustado às mudanças da EC nº 103/2019 e às leis básicas, tornando-se uma fonte normativa confiável para o estudo. A razão do decreto regulamentar é devido às disposições transitórias da EC nº 103/2019.

### Conceitos
- **Decreto regulamentar**: Decreto que ajusta uma norma legal para a realidade nacional
- **Disposições transitórias**: Cláusulas do texto legislativo que estabelecem regras temporárias ou excepcionais
- **Hierarquia normativa**: Ordem em que as normas legais são classificadas e priorizadas

### Referências legais
- Art. 103 da Constituição Federal de 1988
- Decreto nº 10.410/2020

### Dicas de prova
- Foco na hierarquia normativa
- Estude por temas
- Utilize o Regulamento atualizado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.10 (1)", "page_number": 10, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 103 da Constituição Federal de 1988", "Decreto nº 10.410/2020"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:24:54.406954+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=10", "doc_key": "40ee5cc48fbc34ff70830bbfd0cc343a"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'e7d5e1ca36b71733f9999d69bc6c9a4b231b696b57edcbc0325a78c70e9d9145'),
  ('cpiuris2025::f04059981a69c8227c0f73fb3618a796', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Origem da proteção social no Brasil e no mundo', '## Origem da proteção social no Brasil e no mundo

A proteção social no Brasil começou por meio de instituições privadas, como as obras religiosas. A Constituição de 1824 mencionou os ''socorros públicos'' como medida de saúde pública.

### Conceitos
- **Instituições privadas**: Organizações não governamentais que oferecem assistência social
- **Obras religiosas**: Instituições fundadas por organizações religiosas para atender às necessidades sociais
- **Constituição de 1824**: Documento que estabelece as bases do Estado brasileiro
- **Socorros públicos**: Medidas de saúde pública adotadas pelo Estado
- **Previdência social**: Sistema que fornece benefícios a trabalhadores em desemprego ou inabilitação
- **Seguro-desemprego**: Tipo de seguro que protege os trabalhadores contra o desemprego
- **Relatório Beveridge**: Estudo que expandiu a ideia de seguridade social para abranger saúde, previdência e assistência social

### Referências legais
- Art. 5º da Constituição de 1824

### Dicas de prova
- Entenda a evolução da proteção social no Brasil e no mundo
- Identifique as instituições privadas que contribuíram para a formação do sistema previdenciário brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.10 (2)", "page_number": 10, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 5º da Constituição de 1824"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:25:27.074790+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=10", "doc_key": "f04059981a69c8227c0f73fb3618a796"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'f00e894816a794c570eb3ea94683607390f2aa796fddd5e16277f043e1a1342f'),
  ('cpiuris2025::087e79fe596586f0255f089937967560', 'doutrina', 'cp_iuris', 'Direito Previdenciário — História e Desenvolvimento da Previdência Social no Brasil', '## História e Desenvolvimento da Previdência Social no Brasil

A previdência social brasileira foi criada em 1835 com o Montepio Geral dos Servidores do Estado, mas evoluiu ao longo do tempo, passando por fases como Organização por Empresas e Categorias Profissionais, até a unificação total em 1966.

### Conceitos
- **Montepio Geral dos Servidores do Estado**: Instituição criada em 1835 para proteger as famílias de servidores públicos
- **Lei Eloy Chaves**: Lei que autorizou a criação das Caixas de Aposentadoria e Pensões (CAP) em 1923
- **Instituto Nacional de Previdência Social (INPS)**: Entidade criada em 1966 para unificar a legislação previdenciária
- **Sistema Nacional de Previdência e Assistência Social (SINPAS)**: Sistema criado em 1977 que integrou diversas instituições da seguridade social

### Referências legais
- Art. 1835, Código Civil
- Lei Eloy Chaves (1923)

### Jurisprudência
- RE 123456
- Tema repetitivo da Constituição de 1988

### Dicas de prova
- Entenda a evolução da previdência social no Brasil e as fases que ela passou
- Conheça os marcos iniciais da previdência social, como o Montepio Geral dos Servidores do Estado e a Lei Eloy Chaves', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.11 (1)", "page_number": 11, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 1835, Código Civil", "Lei Eloy Chaves (1923)"], "jurisprudence": ["RE 123456", "Tema repetitivo da Constituição de 1988"], "confidence": 0.8, "extracted_at": "2026-05-27T16:26:07.340631+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=11", "doc_key": "087e79fe596586f0255f089937967560"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'c91ad28d22a796c4fc44ad01b94ab7fcefebf72bf09b87faaf8b600a61fbcfa3'),
  ('cpiuris2025::45454599c5164309fded431446e74b53', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Evolução Histórica e Legislativa da Seguridade Social no Brasil', '## Evolução Histórica e Legislativa da Seguridade Social no Brasil

Resumo objetivo: A trajetória da seguridade social brasileira é apresentada em três fases, com a LOPS (1960) como início da terceira fase, o SINPAS (1977) como marco da quarta fase e a criação do INSS (1990) que centralizou a gestão previdenciária.

### Conceitos
- **Terceira Fase**: Período de uniformização legislativa, mas não institucional
- **Quarta Fase**: Período de maior eficiência administrativa e integração
- **INSS**: Instituto Nacional do Seguro Social, criado em 1990
- **SINPAS**: Sistema Nacional de Previdência Social, criado em 1977
- **LOPS**: Lei Orgânica da Previdência Social, criada em 1960
- **Previdência Social**: Sistema que visa proteger os trabalhadores e seus familiares
- **Seguridade Social**: Conceito abrangente que engloba a previdência social, saúde e assistência social

### Referências legais
- Art. 40 da Constituição Federal de 1988

### Dicas de prova
- Entenda a importância das fases na evolução da seguridade social brasileira
- Conheça as principais instituições e leis que moldaram o sistema atual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.11 (2)", "page_number": 11, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 40 da Constituição Federal de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:26:51.573472+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=11", "doc_key": "45454599c5164309fded431446e74b53"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'b86eba0fe06d27def9681628f9ccca8fb828e2a25e1a1f4a739970cee3d07cfe'),
  ('cpiuris2025::cff975c3d4508cb92751babef1b8d99f', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Evolução histórica no mundo', '## Evolução histórica no mundo

Resumo objetivo: A evolução histórica da seguridade social é apresentada, destacando marcos importantes na Inglaterra, Alemanha e EUA, como a Lei dos Pobres, criação de seguros e planos de previdência.

### Conceitos
- **Lei dos Pobres**: Estabeleceu responsabilidade comunitária pela assistência social
- **Seguro-doença**: Criação do seguro de doença na Alemanha
- **Plano Beveridge**: Marco da seguridade social abrangendo seguro, saúde e assistência social

### Referências legais
- Lei dos Pobres (Inglaterra)
- Constituição de Weimar (Alemanha)

### Dicas de prova
- Entenda a evolução histórica da seguridade social
- Destaque os marcos importantes na Inglaterra, Alemanha e EUA', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.12", "page_number": 12, "discipline": "Direito Previdenciário", "legal_refs": ["Lei dos Pobres (Inglaterra)", "Constituição de Weimar (Alemanha)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:27:16.153076+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=12", "doc_key": "cff975c3d4508cb92751babef1b8d99f"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '32a14df3bef9f8c75b80d495b94a5fec6042e2f6ed2f3471d9ada742b2cbf7ff'),
  ('cpiuris2025::295bed10e066d13b16b9ec50c6ad929a', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Evolução histórica no Brasil', '## Evolução histórica no Brasil

A evolução da previdência social no Brasil é apresentada como uma série de marcos importantes, incluindo a criação do MONGERAL, a primeira previsão de aposentadoria e a instituição do IAPM.

### Conceitos
- **MONGERAL**: garantia benefícios às famílias de empregados públicos falecidos
- **IAPM**: previdência organizada pelo Estado e por categoria profissional

### Referências legais
- Decreto nº 3.724
- Lei Eloy Chaves (Decreto nº 4.682)

### Dicas de prova
- Entenda a importância da criação do MONGERAL e como ela contribuiu para o desenvolvimento da previdência social no Brasil.
- Identifique a data em que foi utilizada pela primeira vez a expressão ''previdência social'' na Constituição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.13", "page_number": 13, "discipline": "Direito Previdenciário", "legal_refs": ["Decreto nº 3.724", "Lei Eloy Chaves (Decreto nº 4.682)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:27:39.037848+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=13", "doc_key": "295bed10e066d13b16b9ec50c6ad929a"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'cf758483229eae4589885fe7fc324c56f70502188a575b11e70f432dc87f6bfc'),
  ('cpiuris2025::158290c8c9abe70e2b485674a49cc3e4', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Lei Orgânica da Previdência Social (LOPS)', '## Lei Orgânica da Previdência Social (LOPS)

A LOPS uniformizou a legislação previdenciária, mantendo os IAPs separados, mas criando o INPS em 1967.

### Conceitos
- **IAPs**: Instituições Autônomas de Previdência Social
- **INPS**: Instituto Nacional do Seguro Social
- **SINPAS**: Sistema Nacional de Previdência Social

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a relação entre IAPs e INPS.
- Conheça o sistema de previdência social criado pela LOPS.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.14", "page_number": 14, "discipline": "Direito Previdenciário", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:28:09.245838+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=14", "doc_key": "158290c8c9abe70e2b485674a49cc3e4"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '8e356335dfcf40800738d0ea85f8fa48cd50eaa1b372d92c9698859b40ce1a87'),
  ('cpiuris2025::245c4c50f570fba001fa6038afba67c8', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Conceito de Seguridade Social', '## Conceito de Seguridade Social

A Seguridade Social é um sistema central na ordem social do Brasil, com o objetivo de garantir direitos sociais mínimos e promover a justiça social.

### Conceitos
- **Ordem Social**: Conceito fundamental que engloba questões sociais fundamentais do país
- **Justiça Social**: Objetivo principal da ordem social, buscando promover o desenvolvimento nacional e erradicar a pobreza
- **Segurança Social**: Conceito que engloba a prestação de serviços e benefícios destinados a assegurar os direitos relativos à saúde e à previdência

### Referências legais
- Art. 193 da CF/1988
- Art. 194 da CF/1988

### Dicas de prova
- Entenda o conceito de ordem social e sua relação com a justiça social
- Identifique os objetivos principais da Seguridade Social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.15 (1)", "page_number": 15, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 193 da CF/1988", "Art. 194 da CF/1988"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-27T16:28:36.587092+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=15", "doc_key": "245c4c50f570fba001fa6038afba67c8"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '0b772679ad67ebf41a7c9a2f67bd2cbbd00db59c2402c167f1c8cdb816226a67'),
  ('cpiuris2025::ca106491b0f8c2d7202358bd266fa2da', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Previdência e Assistência Social', '## Previdência e Assistência Social

A previdência e assistência social visam garantir direitos relacionados à saúde, previdência e assistência social. A sociedade civil é colaboradora no sucesso das políticas públicas voltadas para a seguridade social.

### Conceitos
- **Seguridade Social**: Conceito que implica a colaboração entre o poder público e a sociedade para garantir direitos essenciais de saúde, previdência e assistência social.
- **Colaboração Pública-Social**: Reforçada pela Emenda Constitucional nº 108/2020
- **Políticas Públicas**: Voltadas para a seguridade social

### Referências legais
- Art. 193 da CF/1988
- Emenda Constitucional nº 108/2020

### Dicas de prova
- Entenda o conceito de seguridade social e sua importância na previdência e assistência social.
- Identifique a colaboração pública-social reforçada pela Emenda Constitucional nº 108/2020.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.15 (2)", "page_number": 15, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 193 da CF/1988", "Emenda Constitucional nº 108/2020"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:29:03.974176+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=15", "doc_key": "ca106491b0f8c2d7202358bd266fa2da"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '2438b8aa4f486ff3ec92c39c0f5ca4b5833d4385b269024ff3e0ac807b9b51c1'),
  ('cpiuris2025::4611e6a5408edb92b775e8391387eafd', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Saúde e Seguridade Social', '## Saúde e Seguridade Social

O artigo 196 da CF estabelece três pontos fundamentais sobre a saúde no Brasil: direito de todos, dever do Estado, política social e econômica focada na redução do risco de doenças; o art. 198 detalha as diretrizes do SUS, incluindo descentralização, atendimento integral e participação da comunidade.

### Conceitos
- **Seguridade Social**: Política social e econômica que visa reduzir o risco de doenças e outros agravos
- **Sistema Único de Saúde (SUS)**: Rede pública de saúde que fornece assistência à população
- **Descentralização**: Divisão da gestão do SUS entre União, Estados e Municípios
- **Atendimento Integral**: Priorização das atividades preventivas para evitar doenças antes que se tornem graves
- **Participação da Comunidade**: Importância da sociedade na formulação e acompanhamento das políticas de saúde

### Referências legais
- Art. 196 da CF
- Art. 198 da CF
- Lei Complementar nº 141/2012

### Dicas de prova
- Entenda a importância da seguridade social e do Sistema Único de Saúde (SUS) no contexto brasileiro
- Destaque a descentralização, atendimento integral e participação da comunidade como diretrizes do SUS', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.16 (1)", "page_number": 16, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 196 da CF", "Art. 198 da CF", "Lei Complementar nº 141/2012"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:29:52.787128+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=16", "doc_key": "4611e6a5408edb92b775e8391387eafd"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'dffd4142cccf04deacb32cec8cc13b8c69b24c15baf9cd203f97c9568fc70705'),
  ('cpiuris2025::314a470c019c393ba1b9adaa3930b837', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Participação das Entidades Privadas na Assistência à Saúde', '## Participação das Entidades Privadas na Assistência à Saúde

As entidades privadas podem participar da assistência à saúde de forma complementar ao SUS, mas apenas quando o SUS não puder atender adequadamente. As empresas devem ser filantrópicas ou sem fins lucrativos.

### Conceitos
- **SUS**: Sistema Único de Saúde
- **Assistência à Saúde**: Serviços e benefícios destinados a promover, proteger e aumentar a saúde das pessoas
- **Participação Privada**: Involvement de entidades privadas na assistência à saúde

### Referências legais
- Art. 196 da Lei nº 8.080/1990

### Dicas de prova
- Diferenciar entre a participação complementar e a participação direta das entidades privadas na assistência à saúde
- Entender a importância do SUS como estrutura de saúde pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.16 (2)", "page_number": 16, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 196 da Lei nº 8.080/1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:30:19.400880+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=16", "doc_key": "314a470c019c393ba1b9adaa3930b837"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '7758846925475a4eb26335182498d4094eb78eae281dc95d73feaf79a294ae7b'),
  ('cpiuris2025::7d5bd76b2c816870b27a569df0cf75b4', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Sistema Único de Assistência Social (SUAS) e Benefício de Prestação Continuada (BPC)', '## Sistema Único de Assistência Social (SUAS) e Benefício de Prestação Continuada (BPC)

O SUAS organiza as políticas assistenciais no Brasil, com participação da sociedade civil. O BPC é um benefício destinado a idosos e pessoas com deficiência, condicionado à situação de vulnerabilidade social.

### Conceitos
- **Sistema Único de Assistência Social (SUAS)**: organização das políticas assistenciais no Brasil
- **Benefício de Prestação Continuada (BPC)**: benefício destinado a idosos e pessoas com deficiência
- **Vulnerabilidade social**: situação de risco ou violação de direitos que justifica o recebimento do BPC
- **Deficiência**: impedimentos de longo prazo que dificultam a participação plena na sociedade

### Referências legais
- Art. 203, V, da Constituição

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre o financiamento de saúde e assistência social
- Conheça as condições para receber o BPC
- Avalie a importância da participação da sociedade civil no SUAS', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.17 (1)", "page_number": 17, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 203, V, da Constituição"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T16:30:52.446517+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=17", "doc_key": "7d5bd76b2c816870b27a569df0cf75b4"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'dffc42f6208df4ad246318d937749a4063785c5bda8a03dd722e19ba4a88b13b'),
  ('cpiuris2025::08557d01cb5cbd1bdb03ffe77efff75e', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Critérios para concessão de benefício mensal de salário mínimo', '## Critérios para concessão de benefício mensal de salário mínimo

A Lei de Organização da Assistência Social estabeleceu critérios para concessão do benefício mensal de salário mínimo aos portadores de deficiência e idosos que comprovam não possuir meios de prover a própria manutenção. O requisito financeiro é considerar-se incapaz de prover a manutenção da pessoa portadora de deficiência ou idosa se a família cuja renda mensal per capita for inferior a 1/4 do salário mínimo.

### Conceitos
- **Benefício mensal de salário mínimo**: Concessão de benefício mensal aos portadores de deficiência e idosos que comprovam não possuir meios de prover a própria manutenção
- **Critérios objetivos**: Requisitos estabelecidos pela Lei para concessão do benefício mensal de salário mínimo
- **Renda familiar per capita**: Renda mensal da família que é considerada para determinar a capacidade de prover a manutenção da pessoa portadora de deficiência ou idosa

### Referências legais
- Art. 203, V, da Constituição da República
- Art. 20, § 3º, da Lei 8.742/1993
- ADI 1.232

### Jurisprudência
- Ação Direta de Inconstitucionalidade 1.232-1/DF
- RE 123456

### Dicas de prova
- Entenda a importância dos critérios objetivos estabelecidos pela Lei para concessão do benefício mensal de salário mínimo.
- Conheça o requisito financeiro que determina a capacidade de prover a manutenção da pessoa portadora de deficiência ou idosa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.17 (2)", "page_number": 17, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 203, V, da Constituição da República", "Art. 20, § 3º, da Lei 8.742/1993", "ADI 1.232"], "jurisprudence": ["Ação Direta de Inconstitucionalidade 1.232-1/DF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T16:31:46.461804+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=17", "doc_key": "08557d01cb5cbd1bdb03ffe77efff75e"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'ad0f955abd42dd5bd7357aea8cd768e37ba8741f1c01147eca1b3f44d51c25de'),
  ('cpiuris2025::c89a11e372e5c3338fe0f950cfc108bd', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Inconstitucionalização decorrente de mudanças fáticas e jurídicas', '## Inconstitucionalização decorrente de mudanças fáticas e jurídicas

Resumo objetivo: A inconstitucionalização ocorre quando as mudanças fáticas (políticas, econômicas e sociais) e jurídicas (sucessivas modificações legislativas dos patamares econômicos utilizados como critérios de aferição da capacidade contributiva) não são previstas na Constituição.

### Conceitos
- **Inconstitucionalização**: Ocorre quando as mudanças fáticas e jurídicas não são previstas na Constituição
- **Mudanças fáticas**: Políticas, econômicas e sociais que afetam a previdência
- **Mudanças jurídicas**: Sucessivas modificações legislativas dos patamares econômicos utilizados como critérios de aferição da capacidade contributiva

### Referências legais
- Art. 96, § 3º da Constituição

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda que inconstitucionalização ocorre quando as mudanças não são previstas na Constituição
- Diferencie entre mudanças fáticas e jurídicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.17 (3)", "page_number": 17, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 96, § 3º da Constituição"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T16:32:12.974022+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=17", "doc_key": "c89a11e372e5c3338fe0f950cfc108bd"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '4241227ec4d6d7e8775c2e9f9b294dcb1c21e3cbb53cf343f5ee4c8a6fd02063'),
  ('cpiuris2025::cf04892ea14fd302e81a8a96178773d5', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Concessão de outros benefícios assistenciais e inconstitucionalidade parcial do art. 34, parágrafo único, da Lei 10.741/2003', '## Concessão de outros benefícios assistenciais e inconstitucionalidade parcial do art. 34, parágrafo único, da Lei 10.741/2003

A Lei 10.741/2003 dispõe que o benefício assistencial já concedido a qualquer membro da família não será computado para fins do cálculo da renda familiar per capita. A inconstitucionalidade por omissão parcial é discutida em relação à discriminação dos portadores de deficiência e idosos.

### Conceitos
- **Renda Familiar Per Capita**: renda percebida por um membro da família para fins de concessão de benefícios
- **Benefício Assistencial**: ajuda financeira concedida pelo Estado brasileiro a pessoas necessitadas
- **Omissão Parcial**: falta de disposição legal que afeta a constitucionalidade de uma norma

### Referências legais
- Art. 34, parágrafo único, da Lei 10.741/2003

### Jurisprudência
- RE 580963
- RE 587970

### Dicas de prova
- Entenda a noção de Renda Familiar Per Capita e sua importância na concessão de benefícios.
- Conheça as implicações da omissão parcial em relação à constitucionalidade de uma norma.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.18 (1)", "page_number": 18, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 34, parágrafo único, da Lei 10.741/2003"], "jurisprudence": ["RE 580963", "RE 587970"], "confidence": 0.8, "extracted_at": "2026-05-27T16:32:48.759275+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=18", "doc_key": "cf04892ea14fd302e81a8a96178773d5"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '978a388311e1e772457066d39a9382796800b26ea3cbeca1d71881b5d830417f'),
  ('cpiuris2025::e620e301bc3dff5145f62a4184602f8e', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Possibilidade de demonstração da condição de miserabilidade do beneficiário', '## Possibilidade de demonstração da condição de miserabilidade do beneficiário

A lei permite a concessão de benefício assistencial aos idosos e às pessoas portadoras de deficiência que não possuem meios para prover à própria manutenção ou cuja família possui renda mensal per capita inferior a 1/4 do salário mínimo.

### Conceitos
- **Benefício assistencial**: Concessão de benefício para pessoa idosa ou com deficiência que não possuam prover à própria manutenção
- **Renda per capita**: Valor total da renda mensal de uma família
- **Salário mínimo**: Valor mínimo estabelecido pelo governo para garantir um padrão de vida básico

### Referências legais
- Art. 203, caput e inciso V da CF/1988
- Lei n. 8.742/93, alterada pela Lei 9.720/98

### Jurisprudência
- ADI 1.232/DF
- REsp 1355052/SP

### Dicas de prova
- Entenda a garantia de um salário mínimo de benefício mensal
- Conheça a limitação da renda per capita familiar para comprovar a condição de miserabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.18 (2)", "page_number": 18, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 203, caput e inciso V da CF/1988", "Lei n. 8.742/93, alterada pela Lei 9.720/98"], "jurisprudence": ["ADI 1.232/DF", "REsp 1355052/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T16:33:34.249931+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=18", "doc_key": "e620e301bc3dff5145f62a4184602f8e"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '40a554eb97d6a0317fe79f0124c1f837257352e91fcb1c4bfc22de83a868cbc8'),
  ('cpiuris2025::6f94883a2dc5d8474104e2a16a59b78c', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Miserabilidade no Benefício Previdenciário', '## Miserabilidade no Benefício Previdenciário

A miserabilidade é presumida quando a renda per capita é inferior a 1/4 do salário mínimo, mas não deve ser o único meio de prova.

### Conceitos
- **renda per capita**: valor recebido por cada membro da família
- **miserabilidade**: condição de necessidade absoluta para receber benefício previdenciário

### Referências legais
- Art. 131 do CPC

### Dicas de prova
- Entenda a importância da renda per capita na determinação da miserabilidade.
- Não confunda a delimitação do valor da renda familiar com o único meio de prova da condição de miserabilidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.18 (3)", "page_number": 18, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 131 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:33:52.271988+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=18", "doc_key": "6f94883a2dc5d8474104e2a16a59b78c"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '8104b124a8752103cb650e48ecaf9630ffa94005faf0052b31384c1b64aac2cb'),
  ('cpiuris2025::e9a2c2bf9bec5c2200f8e98be1569216', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Vinculação do Magistrado a Elemento Probatório', '## Vinculação do Magistrado a Elemento Probatório

O magistrado não pode ser vinculado a um elemento probatório que cerceie seu direito de julgar.

### Conceitos
- **Vinculação**: Conexão obrigatória de um fato ou elemento com uma decisão
- **Elemento Probatório**: Fato ou circunstância que prova a veracidade de uma alegação
- **Direito de Julgar**: O direito do juiz de tomar decisões em um caso

### Referências legais
- REsp 1112557 RS
- Súmula 48 da TNU

### Jurisprudência
- TNU, Súmula 48; REsp 1112557 RS

### Dicas de prova
- Entenda a noção de vinculação e elemento probatório
- Conheça as súmulas da TNU relacionadas à previdência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.19 (1)", "page_number": 19, "discipline": "Direito Previdenciário", "legal_refs": ["REsp 1112557 RS", "Súmula 48 da TNU"], "jurisprudence": ["TNU, Súmula 48; REsp 1112557 RS"], "confidence": 0.8, "extracted_at": "2026-05-27T16:34:19.500286+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=19", "doc_key": "e9a2c2bf9bec5c2200f8e98be1569216"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '70db8ff966f90394cd9b873c434841666294d57d3751ea32f0071f98f7ad1b1c'),
  ('cpiuris2025::39adb34128b169e3f21839ea122a2a51', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Tese fixada - Exigência de renda familiar per capita inferior a ¼ do salário-mínimo gera presunção relativa de miserabilidade', '## Tese fixada - Exigência de renda familiar per capita inferior a ¼ do salário-mínimo gera presunção relativa de miserabilidade

A lei estabelece que a exigência de renda familiar per capita inferior a ¼ do salário-mínimo gera uma presunção relativa de miserabilidade, que pode ser afastada por outros elementos de prova.

### Conceitos
- **Renda Familiar Per Capita**: Valor da renda de cada membro da família
- **Miserabilidade**: Presunção relativa de pobreza ou necessidade
- **Elementos de Prova**: Dados que comprovam a afirmação de uma situação

### Referências legais
- Art. 16 da Lei n. 8.213/91
- Art. 20 da Lei n. 8.742/93

### Dicas de prova
- Entenda a noção de miserabilidade e como ela é afastada por outros elementos de prova.
- Conheça as regras para a concessão do benefício assistencial e os benefícios por incapacidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.19 (2)", "page_number": 19, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 16 da Lei n. 8.213/91", "Art. 20 da Lei n. 8.742/93"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:34:57.993557+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=19", "doc_key": "39adb34128b169e3f21839ea122a2a51"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '25d7dcf76607192a0798d9f71fcc56999920d60e054b901c2c6ccd3d2bb19f6c'),
  ('cpiuris2025::069e8f2140054ba6d23404442b59e53c', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Auxílio-Inclusão', '## Auxílio-Inclusão

O Auxílio-Inclusão é um benefício concedido a pessoas com deficiência moderada ou grave que recebem o Benefício de Prestação Continuada (BPC) e começam a exercer atividade remunerada, com limitações na remuneração.

### Conceitos
- **Auxílio-Inclusão**: Benefício concedido a pessoas com deficiência que recebem BPC e começam a exercer atividade remunerada
- **BPC**: Benefício de Prestação Continuada
- **Deficiência moderada ou grave**: Requisito para concessão do Auxílio-Inclusão

### Referências legais
- Art. 94 da Lei 13.146/2015
- Lei 14.176/2021

### Dicas de prova
- Entenda a diferença entre o Auxílio-Inclusão e o BPC
- Conheça os requisitos para concessão do Auxílio-Inclusão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.20", "page_number": 20, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 94 da Lei 13.146/2015", "Lei 14.176/2021"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:35:24.334540+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=20", "doc_key": "069e8f2140054ba6d23404442b59e53c"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '5506eca96a492e5adbe43befa302110f66d1139e66c8fbb8c03a66b4ed65f89a'),
  ('cpiuris2025::416f6248b4cffd9ec5e5679547a90ea0', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Benefícios Eventuais - outros benefícios temporários', '## Benefícios Eventuais - outros benefícios temporários

Definição e responsabilidade pela concessão de benefícios assistenciais temporários previstos na LOAS, destinados a situações específicas como nascimento, morte, vulnerabilidade temporária e calamidade pública.

### Conceitos
- **Benefício Assistencial Temporário**: Benefício assistencial previsto na LOAS destinado a situações específicas
- **LOAS**: Lei Orgânica da Assistência Social
- **Concessão de Benefícios**: Responsabilidade dos Estados, Distrito Federal e Municípios em definir o valor e conceder os benefícios

### Referências legais
- Art. 201 da Constituição Federal
- Emenda Constitucional nº 103/2019

### Dicas de prova
- Entenda a diferença entre Previdência Social e Assistência Social
- Conheça os benefícios previstos na LOAS', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.21", "page_number": 21, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 201 da Constituição Federal", "Emenda Constitucional nº 103/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:35:52.328357+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=21", "doc_key": "416f6248b4cffd9ec5e5679547a90ea0"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'ba5de5a0aae1b162782afc44e4f7633a281e945a2ce786d9d6e508e3df226215'),
  ('cpiuris2025::59cb3c00a4920b32fba133a28c5d2555', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Objetivos da Previdência Social', '## Objetivos da Previdência Social

Os objetivos da Previdência Social são cobrir eventos de incapacidade e aposentadoria, proteger a maternidade, amparar trabalhadores desempregados e conceder benefícios previdenciários.

### Conceitos
- **Previdência Social**: organização estatal que cobre eventos de incapacidade e aposentadoria
- **Filiação compulsória**: vinculação ao sistema previdenciário automaticamente, sem manifestação voluntária do segurado
- **Sistema contributivo**: sistema em que os segurados contribuem para o regime previdenciário
- **Benefícios de auxílio-doença e aposentadoria por invalidez**: benefícios concedidos aos segurados com incapacidade temporária ou permanente
- **Salário-maternidade**: benefício concedido às gestantes
- **Seguro-desemprego**: benefício concedido aos trabalhadores desempregados, administrado pelo Ministrio do Trabalho e Emprego
- **Pensão por morte**: benefício concedido ao cônjuge, companheiro ou dependentes do segurado falecido

### Referências legais
- Art. 194, § 3º, inciso III da CF/1988

### Dicas de prova
- Entenda a organização estatal e natureza coletiva da Previdência Social
- Conheça os objetivos da Previdência Social e seus benefícios
- Identifique a diferença entre o seguro-desemprego e o auxílio-doença', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.22 (1)", "page_number": 22, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 194, § 3º, inciso III da CF/1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:36:45.808928+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=22", "doc_key": "59cb3c00a4920b32fba133a28c5d2555"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'df4c6c87efa3f8a7a8016b51026af643fbfdb533eedfe56427ff26ccaacb91c2'),
  ('cpiuris2025::b6845dad7ac7e504dbb1151ed9b8f76a', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Natureza do Sistema de Previdência Social', '## Natureza do Sistema de Previdência Social

O sistema de Previdência Social não é contratual, mas sim institucional ou estatutário, com adesão obrigatória ao regime.

### Conceitos
- **Institucionalidade**: Caracterização do sistema de Previdência Social como não contratual
- **Estatutariidade**: Adesão obrigatória ao regime de Previdência Social
- **Vontade do Segurado**: A adesão ao regime não depende da vontade do segurado

### Referências legais
- Art. 201 da CF/1988

### Dicas de prova
- Entenda a diferença entre objetivos previdenciários e assistenciais
- Conheça os exemplos de benefícios previstos para situações de incapacidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.22 (2)", "page_number": 22, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 201 da CF/1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:37:09.986753+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=22", "doc_key": "b6845dad7ac7e504dbb1151ed9b8f76a"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '295501bc751aedd6b2feebaa7f5ac381fd5f87bc363c63ed66669c3844075a3f'),
  ('cpiuris2025::d9bed6ffa590f7aec65af5397bb6fb93', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Características da Previdência Social', '## Características da Previdência Social

A previdência social é de responsabilidade do Estado, com filiação compulsória ao início da atividade remunerada. O trabalhador é obrigado a contribuir para o sistema previdenciário.

### Conceitos
- **Filiação Compulsória**: O vínculo entre o trabalhador e o Regime Geral de Previdência Social ocorre automaticamente ao início da atividade remunerada.
- **Contributividade**: O trabalhador é obrigado a contribuir para o sistema previdenciário, uma vez que se insere no regime ao exercer atividade remunerada.
- **Organização Estatal**: A previdência social é de responsabilidade do Estado.
- **Vínculo Institucional**: O vínculo entre o trabalhador e o Regime Geral de Previdência Social ocorre automaticamente, sem que o indivíduo precise manifestar vontade.
- **Contribuição Obrigatória**: Não há possibilidade de exclusão do sistema, mesmo que o trabalhador não queira contribuir.
- **Gestão do Ministério da Previdência Social**: O Ministério da Previdência Social é responsável pela gestão da previdência.
- **Legislação Vigente**: A legislação vigente orienta a concessão de benefícios de acordo com a situação de incapacidade, maternidade, desemprego involuntário, entre outros.
- **Objetivos da Previdência Social**: Descreve os objetivos da previdência social e se diferencia dos objetivos da assistência social.

### Referências legais
- Art. 194, § 3º, III da CF/1988
- Art. 201 da CF/1988

### Dicas de prova
- Entenda a filiação compulsória e a contributividade como aspectos fundamentais da previdência social.
- Conheça os objetivos da previdência social e como eles se diferenciam dos objetivos da assistência social.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.23 (1)", "page_number": 23, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 194, § 3º, III da CF/1988", "Art. 201 da CF/1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:37:57.491950+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=23", "doc_key": "d9bed6ffa590f7aec65af5397bb6fb93"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'd85bbb0815c703051d6b9d09be3fa29b74ce747c19b2e012e3b9a699667ecaf1'),
  ('cpiuris2025::09fada184f9a611bd48543b74cf25858', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Princípios da Seguridade Social no Direito Previdenciário', '## Princípios da Seguridade Social no Direito Previdenciário

Os princípios da seguridade social garantem a aplicação do sistema de maneira justa e eficiente, protegendo os cidadãos em situações de vulnerabilidade social.

### Conceitos
- **Princípio**: norma que direciona o comportamento do sistema
- **Regra**: norma que descreve ação específica e consequência
- **Filiação Compulsória**: obrigação de se filiar à previdência social para trabalhar

### Referências legais
- Art. 194 da Constituição

### Dicas de prova
- Entenda a diferença entre princípio e regra
- Conheça os princípios fundamentais da seguridade social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.23 (2)", "page_number": 23, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 194 da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:38:29.739907+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=23", "doc_key": "09fada184f9a611bd48543b74cf25858"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '38f16bd1f739808f39289fe3915c0452c0be91248fe224b301bac22dd75bc8b3'),
  ('cpiuris2025::58ae6f8e308ab59846020ab3d945996f', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Princípio da Solidariedade', '## Princípio da Solidariedade

O princípio da solidariedade é o pilar central do sistema de seguridade social brasileiro, garantindo que as contribuições sirvam para a proteção dos mais necessitados.

### Conceitos
- **Princípio da Solidariedade**: Garantia de que as contribuições sirvam para a proteção dos mais necessitados
- **Intergeracional**: Contribuições de uma geração sustentam os benefícios de outra
- **Intrageracional**: Uma pessoa contribui para que outra da mesma geração tenha acesso ao benefício

### Referências legais
- Art. 3º, inciso I da Constituição Federal de 1988
- Art. 194, parágrafo único, da Constituição Federal de 1988

### Dicas de prova
- Entenda a diferença entre intergeracional e intrageracional
- Conheça o artigo 3º, inciso I da Constituição Federal de 1988 e o artigo 194, parágrafo único, da Constituição Federal de 1988', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.24 (1)", "page_number": 24, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 3º, inciso I da Constituição Federal de 1988", "Art. 194, parágrafo único, da Constituição Federal de 1988"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-27T16:39:01.543576+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=24", "doc_key": "58ae6f8e308ab59846020ab3d945996f"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '6a839c98b7e41808204a560e952df4530aa8224c27bc8d5742e1cf22f37386ab'),
  ('cpiuris2025::c6c9f1f8598a1d552207069fef8c0d2c', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Princípios da Cobertura e Atendimento da Seguridade Social', '## Princípios da Cobertura e Atendimento da Seguridade Social

O princípio da universalidade da cobertura e do atendimento garante que todos os cidadãos tenham acesso aos benefícios da seguridade social, independentemente de sua condição econômica.

### Conceitos
- **Universalidade da Cobertura**: A abrangência do sistema de seguridade social
- **Universalidade do Atendimento**: O direito de todos a ser atendidos pela seguridade social
- **Princípio da Uniformidade e Equivalência dos Benefícios**: A igualdade de acesso a benefícios e serviços para populações urbanas e rurais

### Referências legais
- Art. 194, parágrafo único, I da CF

### Dicas de prova
- Entenda o conceito de universalidade da cobertura e do atendimento
- Identifique a distinção entre abrangência do sistema e direito de todos a ser atendidos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.24 (2)", "page_number": 24, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 194, parágrafo único, I da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:39:26.305454+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=24", "doc_key": "c6c9f1f8598a1d552207069fef8c0d2c"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'b99c13a56a2cf20adc770a3c5faceb2f1049472f5ba42c26f7907771d58bd199'),
  ('cpiuris2025::0f74be7984ea054aaad7bc9a3a3b1f7d', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Princípios da Seguridade Social', '## Princípios da Seguridade Social

Os princípios da uniformidade e equivalência garantem que os benefícios sejam proporcionais à situação de cada beneficiário, sem discriminação entre segurados urbanos e rurais.

### Conceitos
- **Uniformidade**: Impõe que os eventos cobertos pela seguridade social sejam os mesmos para todos os segurados
- **Equivalência**: Garante que os benefícios sejam proporcionais à situação de cada beneficiário, com base em condições semelhantes
- **Princípio da Seletividade e Distributividade**: Estabelece uma distribuição justa e adequada dos recursos limitados do Estado, priorizando os benefícios mais relevantes

### Referências legais
- Art. 194, parágrafo único, inciso III, da Constituição Federal de 1988

### Dicas de prova
- Entenda a importância dos princípios da uniformidade e equivalência na prestação de benefícios previdenciários
- Conheça o princípio da seletividade e distributividade e como ele atenua o princípio da universalidade da cobertura', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.25 (1)", "page_number": 25, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 194, parágrafo único, inciso III, da Constituição Federal de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:40:09.316594+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=25", "doc_key": "0f74be7984ea054aaad7bc9a3a3b1f7d"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '6d746f4597b31cf2c0012d35c3cf470da68dd3bb22b247d77b78debcb1df9b5f'),
  ('cpiuris2025::1090ea7a14b97f498c8f0c8885e3fa48', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Princípios essenciais do sistema previdenciário', '## Princípios essenciais do sistema previdenciário

Os princípios da irredutibilidade do valor dos benefícios e da equidade determinam a forma como os benefícios são concedidos e as contribuições são cobradas.

### Conceitos
- **Irredutibilidade do valor dos benefícios**: Assegura que os benefícios não tenham seu valor nominal ou real reduzido.
- **Princípio da equidade**: Determina que as contribuições sejam proporcionais à capacidade econômica de cada contribuinte.
- **Participação no custeio**: As contribuições ao sistema de seguridade social devem ser proporcionais à capacidade econômica de cada contribuinte.
- **Tabela de contribuição progressiva**: Estabelece alíquotas progressivas sobre o salário de contribuição dos segurados.
- **Contribuições das empresas**: Pode ser feita com base na equidade e em critérios definidos em lei.
- **Valor nominal do benefício**: O valor nominal do benefício é protegido pelo sistema previdenciário.
- **Valor real do benefício**: O valor real do benefício está garantido no artigo 201, §4º da CF/1988.

### Referências legais
- Art. 194, parágrafo único, IV da CF/1988
- Art. 201, §4º da CF/1988

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre valor nominal e real do benefício.
- Conheça a tabela de contribuição progressiva e como ela funciona.
- Aprenda a aplicar o princípio da equidade nas contribuições.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.25 (2)", "page_number": 25, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 194, parágrafo único, IV da CF/1988", "Art. 201, §4º da CF/1988"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T16:40:49.254638+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=25", "doc_key": "1090ea7a14b97f498c8f0c8885e3fa48"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '5ce739104945293437084a49b207a4d11828bd8d607aa3ec1e6df897a7427657'),
  ('cpiuris2025::eae2e24cc197a325f3701d526d188c95', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Princípios Fundamentais da Previdência Social', '## Princípios Fundamentais da Previdência Social

Os principios fundamentais da previdencia social garantem a justiça social e proteção dos segurados, com princípios como universalidade da participação, diversidade da base de financiamento, princípio democrático e descentralizado da administração e preexistência do custeio em relação ao benefício ou serviço.

### Conceitos
- **Universalidade da Participação**: Garante que todos os indivíduos, sem exceção, participem da rede de proteção social.
- **Diversidade da Base de Financiamento**: Busca garantir a arrecadação de contribuições a partir de diferentes fontes
- **Princípio Democrático e Descentralizado da Administração**: Estabelece a participação ativa de diferentes segmentos da sociedade na gestão do sistema.
- **Preexistência do Custo em Relação ao Benefício ou Serviço**: Determina que nenhum benefício ou serviço da seguridade social pode ser criado sem a devida fonte de custeio

### Referências legais
- Art. 194, parágrafo único, VI da CF/1988
- Art. 195, §5º da CF/1988
- Lei nº 8.213/1991, artigo 2º

### Dicas de prova
- Entenda a importância dos princípios fundamentais da previdência social
- Conheça os diferentes princípios e suas definições
- Aprenda a aplicar os princípios em situações hipotéticas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.26 (1)", "page_number": 26, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 194, parágrafo único, VI da CF/1988", "Art. 195, §5º da CF/1988", "Lei nº 8.213/1991, artigo 2º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:41:30.182704+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=26", "doc_key": "eae2e24cc197a325f3701d526d188c95"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '8aa0335444653afa1852b055de024d1711adf1fc3a0b9bb2834002bc7fa3cb30'),
  ('cpiuris2025::4c9f37c07188e3d04a03fd45ab6be6f0', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Princípios Gerais da Previdência Social', '## Princípios Gerais da Previdência Social

Os benefícios previdenciários devem ser acessíveis a todas as camadas da sociedade, com igualdade de tratamento para populações urbanas e rurais, priorizando aqueles em situação de vulnerabilidade social.

### Conceitos
- **Uniformidade**: A igualdade de tratamento para populações urbanas e rurais
- **Distributividade**: Priorizar aqueles em situação de vulnerabilidade social
- **Irredutibilidade dos Benefícios**: Preservar o poder aquisitivo dos segurados
- **Valor Mínimo dos Benefícios**: Garantir uma proteção mínima para o segurado
- **Previdência Complementar Facultativa**: De adesão voluntária e dependente da contribuição adicional do beneficiário

### Referências legais
- Art. 40 da Lei nº 8.213/1991

### Dicas de prova
- Entenda a importância da uniformidade e distributividade nos benefícios previdenciários
- Conheça o conceito de irredutibilidade dos benefícios e seu impacto no poder aquisitivo do segurado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.26 (2)", "page_number": 26, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 40 da Lei nº 8.213/1991"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:42:10.673505+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=26", "doc_key": "4c9f37c07188e3d04a03fd45ab6be6f0"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'c37bd1d12b3482ebc8e69035d9497ffe5689e3726777d7ab4cae48eb9583509b'),
  ('cpiuris2025::cd24bb91af07fb881047aa3d067fc4ec', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Cálculo dos Benefícios Previdenciários e Garantia do Valor Mínimo do Benefício', '## Cálculo dos Benefícios Previdenciários e Garantia do Valor Mínimo do Benefício

O cálculo de benefícios previdenciários é realizado com base no salário de benefício, que é a média dos salários de contribuição do segurado. A garantia do valor mínimo do benefício é estabelecida para os benefícios substitutivos, mas não se aplica aos benefícios indenizatórios.

### Conceitos
- **Salário de Benefício**: Média dos salários de contribuição do segurado
- **Correção Monetária**: Necessária para garantir que o valor do benefício não seja corroído pela inflação
- **Índice Nacional de Preços ao Consumidor (INPC)**: Usado como base para a correção monetária
- **Benefícios Substitutivos**: Aposentadorias, com garantia de valor mínimo
- **Benefícios Indenizatórios**: Auxílio-acidente e salário-família, sem garantia de valor mínimo

### Referências legais
- Art. 29-B da Lei nº 8.213/1991

### Dicas de prova
- Distinção entre benefícios substitutivos e indenizatórios
- Importância do Índice Nacional de Preços ao Consumidor (INPC) na correção monetária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.27 (1)", "page_number": 27, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 29-B da Lei nº 8.213/1991"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:42:45.697184+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=27", "doc_key": "cd24bb91af07fb881047aa3d067fc4ec"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '281dfe655179d2531db3fbeaae9c262ebe41866461190f48dc1b82efdd87d44d'),
  ('cpiuris2025::b73c5bc4a98b9f3358eaa3f970df0b4c', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Receitas dos entes federativos e seguridade social', '## Receitas dos entes federativos e seguridade social

As receitas dos Estados, Distrito Federal e Municípios destinadas à seguridade social devem constar em seus orçamentos, não fazendo parte do orçamento da União.

### Conceitos
- **Seguridade Social**: Sistema de previdência social no Brasil
- **Receitas dos entes federativos**: Renda gerada pelos Estados, Distrito Federal e Municípios
- **Orçamento da União**: Mês do orçamento anual da União
- **Lei Orçamentária Anual (LOA)**: Lei que estabelece o orçamento anual de cada ente federativo

### Referências legais
- Art. 195 da CF
- § 1º do art. 12 da Lei nº 8.848/1993

### Dicas de prova
- Entenda a distinção entre receitas dos entes federativos e orçamento da União
- Conheça a Lei Orçamentária Anual (LOA) e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.27 (2)", "page_number": 27, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 195 da CF", "§ 1º do art. 12 da Lei nº 8.848/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:43:14.780637+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=27", "doc_key": "b73c5bc4a98b9f3358eaa3f970df0b4c"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '39f5530a98fd35a86d935ceb04aed7edf689b9a5d039c9e3078511be0340a473'),
  ('cpiuris2025::dd9e5932cad8718f400555ebebfa4caf', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Contribuições Sociais e Seguridade Social', '## Contribuições Sociais e Seguridade Social

Regras para contratação com o Poder Público, isenção de contribuições para entidades beneficentes, competência residual da União, princípio da preexistência do custeio e princípio da noventena ou anteridade mitigada.

### Conceitos
- **Contribuição Social**: Contribuição paga pelos contribuintes para financiar a seguridade social
- **Entidade Beneficente de Assistência Social (EBAS)**: Organização que recebe benefícios do Estado e fornece serviços assistenciais
- **Certidão Negativa de Débito (CND)**: Documento que comprova a regularidade da contribuição social
- **Princípio da Preexistência do Custeio**: Nenhum benefício ou serviço da seguridade social pode ser criado, aumentado ou ampliado sem fonte de custeio correspondente
- **Princípio da Noventena ou Anteridade Mitigada**: Contribuições sociais somente podem ser exigidas após 90 dias da publicação da lei que as instituiu ou modificou

### Referências legais
- Art. 154, I, da CF
- Art. 7º, § 4º, da Lei nº 8.213/1991

### Dicas de prova
- Diferenciar entre EAS e EBAS
- Entender a importância da CND para contratação com o Poder Público
- Aplicar o princípio da preexistência do custeio em situações de criação, aumento ou ampliação de benefícios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.28 (1)", "page_number": 28, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 154, I, da CF", "Art. 7º, § 4º, da Lei nº 8.213/1991"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:44:09.645473+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=28", "doc_key": "dd9e5932cad8718f400555ebebfa4caf"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '73c837c80e1c3b671813ab88bd1841559931246b5a48a7c47387a8d9bc6e8cf3'),
  ('cpiuris2025::d8f022a9a05c65d1fa0cd110d13192c6', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Princípio da noventena e contribuição reduzida', '## Princípio da noventena e contribuição reduzida

A contribuição reduzida não exige aguardar o período de 90 dias para sua exigibilidade, em contraste com a contribuição majorada que deve ser aguardado esse período.

### Conceitos
- **Contribuição reduzida**: Não exige aguardar o período de 90 dias para sua exigibilidade
- **Contribuição majorada**: Exige aguardar os 90 dias da publicação da lei para sua exigibilidade
- **Princípio da noventena**: Regra que estabelece o prazo de 90 dias após a publicação da lei para a exigibilidade de contribuições

### Referências legais
- Art. 195, § 9º, da Constituição Federal

### Dicas de prova
- Entenda a diferença entre contribuição reduzida e majorada
- Conheça o princípio da noventena e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.28 (2)", "page_number": 28, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 195, § 9º, da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:44:37.291368+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=28", "doc_key": "d8f022a9a05c65d1fa0cd110d13192c6"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '91fc7d9d4737dbc776ae0a3d84459aca3319f4bed181d5c8ad64071afe29ade7'),
  ('cpiuris2025::d2bb674bd284865c9ae261511c16f92d', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Regras de Contribuições Sociais', '## Regras de Contribuições Sociais

Discute regras sobre contribuições sociais, incluindo vedação de moratória e parcelamento, limites para débitos previdenciários e não-cumulatividade de tributos.

### Conceitos
- **Contribuição Social**: Taxa paga pelos empregadores e segurados para financiar a seguridade social
- **Moratória**: Suspensão temporária da exigibilidade do crédito tributário
- **Parcelamento**: Divisão de um débito em prazos menores
- **Crédito Tributário**: Direito ao pagamento de uma obrigação tributária
- **Contribuição do Segurado**: Taxa paga pelo segurado para financiar a seguridade social

### Referências legais
- Art. 10 da Lei nº 8.212/91
- Súmula 442 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Contribuições Sociais

### Dicas de prova
- Entenda a vedação de moratória e parcelamento
- Conheça os limites para débitos previdenciários
- Aprenda sobre não-cumulatividade de tributos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.29", "page_number": 29, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 10 da Lei nº 8.212/91", "Súmula 442 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Contribuições Sociais"], "confidence": 0.8, "extracted_at": "2026-05-27T16:45:09.737887+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=29", "doc_key": "d2bb674bd284865c9ae261511c16f92d"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '274a426f10375935ca95e273e041a2f10b49bbd6405d26ee783549675632c100'),
  ('cpiuris2025::c16a168d000447af134c7cdad725077b', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Relação Jurídica de Previdência Social e Regime Geral da Previdência Social (RGPS)', '## Relação Jurídica de Previdência Social e Regime Geral da Previdência Social (RGPS)

O Regime Geral da Previdência Social (RGPS) é o principal sistema de proteção social no Brasil, gerenciado pelo Instituto Nacional do Seguro Social (INSS), com base na Constituição Federal e regulamentado pelas Leis Nº8.212/1991 e Nº8.213/1991.

### Conceitos
- **Regime Geral da Previdência Social (RGPS)**: O principal sistema de proteção social no Brasil, gerenciado pelo INSS
- **Instituto Nacional do Seguro Social (INSS)**: Entidade responsável por administrar o RGPS
- **Leis Nº8.212/1991 e Nº8.213/1991**: Leis que regulamentam o custeio e os benefícios da Previdência

### Referências legais
- Art. 40 da Constituição Federal
- Lei Nº8.212/1991
- Lei Nº8.213/1991

### Dicas de prova
- Entenda a relação entre o RGPS e os Regimes Próprios de Previdência Social (RPPS)
- Conheça as exigências para a criação de RPPS e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.32 (1)", "page_number": 32, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 40 da Constituição Federal", "Lei Nº8.212/1991", "Lei Nº8.213/1991"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:45:53.816670+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=32", "doc_key": "c16a168d000447af134c7cdad725077b"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '5d9e921b78fa87070c5a3970d6f09b0d2e1d68ef8124e4680a82fadb7f1718b3'),
  ('cpiuris2025::648a4e0125e492b2cb86b64becca6b0f', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Características Fundamentais do RGPS', '## Características Fundamentais do RGPS

A proteção previdenciária é condicionada ao pagamento de contribuições por parte dos segurados e empregadores, sendo obrigatória a filiação de todos os trabalhadores remunerados.

### Conceitos
- **Contributividade**: A proteção previdenciária é condicionada ao pagamento de contribuições
- **Filiação Obrigatória**: Todos os trabalhadores remunerados devem se filiar ao RGPS

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a natureza contributiva e a obrigatória filiação ao RGPS
- Não confunda com outras formas de proteção social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.32 (2)", "page_number": 32, "discipline": "Direito Previdenciário", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:46:12.195752+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=32", "doc_key": "648a4e0125e492b2cb86b64becca6b0f"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'fcced65b9fd5ec1a0ab2fa61997c36e60c2d7dab9827ff9e0bd1eb20cc995c7d'),
  ('cpiuris2025::327ba6c694bf7c575a2f6d8da65e43de', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Segurados Obrigatórios e Facultativos', '## Segurados Obrigatórios e Facultativos

Os segurados obrigatórios são aqueles vinculados ao RGPS em razão do exercício de uma atividade remunerada, sendo automaticamente inscritos no RGPS. Já os segurados facultativos podem aderir à previdência social, como donas de casa.

### Conceitos
- **RGPS**: Regime Geral de Previdência Social
- **Vínculo empregatício**: Relação de trabalho formalizada por meio de contrato regido pela CLT
- **Trabalhador autônomo**: Pessoa física ou jurídica que exerce atividade profissional independente
- **Empregado doméstico**: Profissional que prestam serviços de maneira contínua em residências
- **Trabalhador avulso**: Pessoa que exerce atividades de forma independente, mas com intermediação de um sindicato ou órgão gestor de mão de obra
- **Segurado especial**: Pequenos produtores rurais, pescadores artesanais e seus familiares que trabalham em regime de economia familiar

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre segurados obrigatórios e facultativos.
- Conheça as categorias principais de segurados (empregado, empregado doméstico, trabalhador avulso e segurado especial).', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.33 (1)", "page_number": 33, "discipline": "Direito Previdenciário", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:46:49.659052+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=33", "doc_key": "327ba6c694bf7c575a2f6d8da65e43de"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '1bf172ae00612443cde1aa170239449458e0807d37e6de04c3038ce94e702f90'),
  ('cpiuris2025::3cb104dd42b62b259bd93250b95103e0', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Contribuintes e Segurados Facultativos', '## Contribuintes e Segurados Facultativos

Descreve as categorias de contribuintes e segurados facultativos no RGPS.

### Conceitos
- **Contribuinte Individual**: Trabalhador autônomo ou empresário responsável pelo recolhimento de sua contribuição ao RGPS
- **Segurado Facultativo**: Pessoa que não exerce atividade remunerada, mas opta contribuir voluntariamente para o RGPS
- **Donas de Casa**: Pessoas que se dedicam exclusivamente às atividades do lar, sem exercer atividade remunerada

### Referências legais
- Art. 102 da Lei nº 8.213/1991

### Dicas de prova
- Diferenciação entre contribuinte individual e segurado facultativo
- Exemplo de pessoa que se enquadra na categoria de donas de casa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.33 (2)", "page_number": 33, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 102 da Lei nº 8.213/1991"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:47:22.231363+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=33", "doc_key": "3cb104dd42b62b259bd93250b95103e0"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'fc4229903a2bf96fa96b55ade8aa82f2045fd261047f2901314c61ace3e40980'),
  ('cpiuris2025::fd6e279d9351bff499787a65f8a80d5e', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Definição e Classificação dos Segurados no RGPS', '## Definição e Classificação dos Segurados no RGPS

O RGPS classifica os segurados em obrigatórios e facultativos, permitindo uma ampla cobertura a trabalhadores urbanos e rurais, formais e informais.

### Conceitos
- **Segurado Obrigatório**: Indivíduo automaticamente incluído no RGPS devido à natureza de sua atividade
- **Facultativo**: Indivíduo que opta por se filiar ao RGPS, garantindo proteção previdenciária sem vínculo formal de trabalho
- **Contribuição Previdenciária**: Pagamento obrigatório para os segurados obrigatórios e facultativos

### Referências legais
- Art. 12 da Lei nº 8.213/1991

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre segurado obrigatório e facultativo
- Conheça os requisitos para contribuição previdenciária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.34", "page_number": 34, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 12 da Lei nº 8.213/1991"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T16:47:50.337369+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=34", "doc_key": "fd6e279d9351bff499787a65f8a80d5e"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'c3dd9eb4f7bb84ca48d9741e0c4e2480aa0947dc3b4b99e964959cd71dd4bb3f'),
  ('cpiuris2025::65b38fe1ca2f597cf96295d234e608b0', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Contribuições proporcionais à capacidade econômica do segurado', '## Contribuições proporcionais à capacidade econômica do segurado

A contribuição proporcional é um tipo de contribuição para o regime geral da previdência social, destinada a compensar a diferença entre a renda do segurado e a média da renda dos trabalhadores no setor. É obrigatória para todos os trabalhadores que não estão incluídos em outro regime previdenciário.

### Conceitos
- **Contribuição proporcional**: Contribuição destinada a compensar a diferença entre a renda do segurado e a média da renda dos trabalhadores no setor
- **Segurado obrigatório**: Trabalhador que está incluído em outro regime previdenciário ou não tem condições de contribuição

### Referências legais
- Art. 104 da Lei nº 8.213/1991

### Dicas de prova
- Entenda a diferença entre contribuição proporcional e contribuição de valor, que é destinada a financiar o regime geral.
- Conheça os requisitos para a inclusão de um trabalhador no regime geral da previdência social.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.35", "page_number": 35, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 104 da Lei nº 8.213/1991"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:48:20.800720+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=35", "doc_key": "65b38fe1ca2f597cf96295d234e608b0"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '016238efd1501e27392516577317520fe6e48207e93ba925ebfb9ef3c58ec028'),
  ('cpiuris2025::e2bc5ab803b574957ac1a5b710868c4e', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Estrutura e Políticas da Previdência Social', '## Estrutura e Políticas da Previdência Social

A estrutura da previdência social assegura a consideração dos interesses de todas as partes envolvidas, incluindo governos, trabalhadores, empregadores e aposentados. O sistema enfrenta desafios financeiros e demográficos, com reformas visando mitigar o impacto econômico crescente.

### Conceitos
- **Equilíbrio financeiro e atuarial**: Refere-se à gestão eficaz dos recursos financeiros e atuariais da Previdência Social
- **Contribuições sobre a folha de salários**: Fonte principal de financiamento do sistema previdenciário
- **Mudanças demográficas e expectativa de vida**: Fatores que afetam o equilíbrio financeiro e atuarial da Previdência Social
- **Regimes previdenciários**: Básico, Complementar e Suplementar, cada um com suas características e benefícios
- **Reserva remunerada**: Benefício concedido aos militares que podem ser chamados de volta ao serviço ativo em situações de necessidade
- **Reforma**: Benefício concedido aos militares que estão definitivamente desligados do serviço, sem possibilidade de retorno
- **Previdência complementar**: Instituída para aumentar a proteção social e compensar as limitações impostas pelos tetos do RGPS e dos RPPS
- **Planos de previdência complementar**: Disponíveis para qualquer pessoa física ou jurídica, com modalidades aberta e fechada

### Referências legais
- Art. 3º da Lei nº 8.213/1991
- EC nº 103/2019

### Dicas de prova
- Entenda a estrutura e políticas da Previdência Social
- Conheça os desafios financeiros e demográficos enfrentados pelo sistema
- Diferencie entre os regimes previdenciários (básico, complementar e suplementar)
- Avalie as características dos benefícios de reserva remunerada e reforma para os militares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.36 (1)", "page_number": 36, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 3º da Lei nº 8.213/1991", "EC nº 103/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:49:27.798930+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=36", "doc_key": "e2bc5ab803b574957ac1a5b710868c4e"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'c6c902c19091c993947dc3d200f3a4a5c9dcd1c21e193f113c99cc66d3152486'),
  ('cpiuris2025::34ae7b11f0630c3e7b9cec949e23ee4f', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Limitação dos benefícios de aposentadoria no RGPS', '## Limitação dos benefícios de aposentadoria no RGPS

Os benefícios de aposentadoria passaram a ter limites ao teto do RGPS, permitindo contribuir para previdência complementar e receber uma complementação ao benefício.

### Conceitos
- **RGPS**: Regime Geral da Previdência Social
- **RPPS**: Regime Próprio de Previdência Social
- **Previdência Complementar**: Plano de previdência que complementa o RGPS

### Referências legais
- EC nº 103/2019

### Dicas de prova
- Entenda a relação entre RGPS, RPPS e previdência complementar.
- Conheça as regras do plano de previdência complementar.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.36 (2)", "page_number": 36, "discipline": "Direito Previdenciário", "legal_refs": ["EC nº 103/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:49:49.669475+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=36", "doc_key": "34ae7b11f0630c3e7b9cec949e23ee4f"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'b8384f3e11ec785babfb76fc13b82c1bf817a5874a07afe127063d98553348a2'),
  ('cpiuris2025::6da39ff99d2298921d229e8c7b7504b7', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Beneficiários e Filiação no Regime Geral de Previdência Social', '## Beneficiários e Filiação no Regime Geral de Previdência Social

O RGPS é um regime que garante proteção social a seus beneficiários, incluindo segurados e dependentes. Os beneficiários são divididos em duas categorias principais: dependentes e segurados.

### Conceitos
- **Beneficiário**: Pessoa que tem direito a benefícios do RGPS
- **Dependente**: Pessoa que tem direito a benefícios específicos, como pensão por morte, devido a laços familiares ou econômicos com o segurado
- **Segurado**: Pessoa que contribui diretamente ao sistema e tem direito a uma série de benefícios
- **Filiação**: Relação jurídica entre o beneficiário e o sistema previdenciário brasileiro

### Referências legais
- Art. 12 da Lei nº 8.213/1991
- Súmula 342 do TST

### Jurisprudência
- RE 123456
- Tema repetitivo: Benefícios de Dependentes

### Dicas de prova
- Entenda a distinção entre dependente e segurado
- Conheça as categorias principais de beneficiários do RGPS', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.37", "page_number": 37, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 12 da Lei nº 8.213/1991", "Súmula 342 do TST"], "jurisprudence": ["RE 123456", "Tema repetitivo: Benefícios de Dependentes"], "confidence": 0.8, "extracted_at": "2026-05-27T16:50:24.938525+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=37", "doc_key": "6da39ff99d2298921d229e8c7b7504b7"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '7fa8962a1050318b37254e70eac1159c5dc594ff57f853ceda74dab940bbdcdb'),
  ('cpiuris2025::6a56a7bb7823351bfd7993580e335528', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Tipos de Segurados no Regime Geral da Previdência Social (RGPS)', '## Tipos de Segurados no Regime Geral da Previdência Social (RGPS)

Os segurados obrigatórios incluem profissionais que prestam serviços contínuos e subordinados, enquanto os segurados facultativos são trabalhadores autônomos ou empresários que exercem atividade econômica com ou sem fins lucrativos.

### Conceitos
- **Segurado Obrigatório**: Profissionais que prestam serviços contínuos e subordinados
- **Contribuinte Individual**: Trabalhadores autônomos e empresários com ou sem fins lucrativos
- **Trabalhador Avulso**: Profissionais que trabalham de forma não contínua para diversas empresas
- **Segurado Especial**: Trabalhadores rurais em regime de economia familiar, pescadores artesanais e seus cônjuges ou companheiros
- **Segurado Facultativo**: Trabalhadores autônomos ou empresários que optam por contribuir para garantir cobertura previdenciária

### Referências legais
- Art. 150 da Lei Complementar nº 150/2015

### Dicas de prova
- Entenda a distinção entre segurado obrigatório e facultativo
- Conheça as características de cada tipo de segurado para aplicá-los corretamente em situações práticas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.38", "page_number": 38, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 150 da Lei Complementar nº 150/2015"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:51:14.419105+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=38", "doc_key": "6a56a7bb7823351bfd7993580e335528"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '39206cd887c41e68425fc190e49f3d39dc0d14a5c5119eb49f5ab2fbf74bbfb8'),
  ('cpiuris2025::905286b4916995ac464e3db9a8f239a4', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Filiação em atividades simultâneas e inscrição no RGPS', '## Filiação em atividades simultâneas e inscrição no RGPS

A filiação ao RGPS ocorre por cada atividade remunerada exercida, sendo o segurado identificado pelo NIT, PIS/PASEP, NIS ou CPF. A inscrição é vinculada à atividade desenvolvida e pode ser realizada pelo empregador ou pelo próprio segurado.

### Conceitos
- **Filiação**: O ato de se registrar no RGPS em relação a cada atividade remunerada exercida
- **Inscrição**: O ato que cadastra o segurado no RGPS, possibilitando o registro de suas contribuições e a futura concessão de benefícios
- **NIT**: Número de Identificação do Trabalhador
- **PIS/PASEP**: Número de identificação para o Sistema de Pagamento de Salários e Benefícios
- **NIS**: Número de Identificação Social, vinculado ao CadÚnico
- **CPF**: Cadastro de Pessoas Físicas, validado pela Receita Federal

### Referências legais
- Art. 2.2.3 da Lei nº 8.213/1991

### Jurisprudência
- {''term'': ''Tema 1065'', ''definition'': ''É constitucional a contribuição previdenciária devida por aposentado pelo RGPS que permaneça em atividade ou a essa retorne''}

### Dicas de prova
- Entenda a diferença entre filiação e inscrição no RGPS
- Conheça as diferentes formas de identificação do segurado (NIT, PIS/PASEP, NIS, CPF)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.39", "page_number": 39, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 2.2.3 da Lei nº 8.213/1991"], "jurisprudence": ["{''term'': ''Tema 1065'', ''definition'': ''É constitucional a contribuição previdenciária devida por aposentado pelo RGPS que permaneça em atividade ou a essa retorne''}"], "confidence": 0.8, "extracted_at": "2026-05-27T16:51:58.584200+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=39", "doc_key": "905286b4916995ac464e3db9a8f239a4"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'eef5f0f00579324389cdf31abb637391741e04d70999b52578067043d784e8b2'),
  ('cpiuris2025::8b467a9ef8eebc66e96057855ae198d2', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Definição de Segurado na Previdência Social', '## Definição de Segurado na Previdência Social

O texto define três categorias de segurados: empregado, empregado doméstico e contribuinte individual, cada uma com suas características específicas.

### Conceitos
- **Segurado Empregado**: Pessoa que presta serviços de natureza urbana ou rural, de forma não eventual, sob subordinação e mediante remuneração.
- **Empregado Doméstico**: Pessoa que presta serviços contínuos, subordinados e sem fins lucrativos no âmbito residencial por mais de dois dias por semana.
- **Contribuinte Individual**: Pessoa física que exerce atividade econômica de natureza urbana ou rural por conta própria, com fins lucrativos ou não.

### Referências legais
- Art. 9º, V do RPS

### Dicas de prova
- Perguntas sobre a definição de segurado podem ser respondidas com base nas características específicas de cada categoria.
- É importante distinguir entre empregado e contribuinte individual, pois têm regras e exigências diferentes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.40 (1)", "page_number": 40, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 9º, V do RPS"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:52:30.074548+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=40", "doc_key": "8b467a9ef8eebc66e96057855ae198d2"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '394f6d75337f111861f63871ab09317b783f3aa8f73b8d0e53767017b8394fb3'),
  ('cpiuris2025::07a4953ad3b37cad5daaa403aa285e2b', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Exigências para o recebimento de benefícios previdenciários', '## Exigências para o recebimento de benefícios previdenciários

Resumo objetivo: Exige-se que os profissionais que exercem atividades de direção em entidades específicas recebam remuneração.

### Conceitos
- **Sócio solidário**: Membro da sociedade que assume a responsabilidade total pela gestão da empresa.
- **Sócio gerente**: Membro da sociedade que exerce a gestão diária da empresa.
- **Sócio cotista**: Membro da sociedade que contribui com capital para a empresa.
- **Administrador**: Pessoal responsável pela administração de uma entidade, como uma cooperativa ou condomínio.
- **Associado eleito**: Membro de uma associação que foi eleito para exercer atividades de direção.
- **Síndico**: Pessoal responsável pela administração de um condomínio.
- **Serviço eventual**: Trabalho realizado por alguém em caráter não remunerado, mas com natureza urbana ou rural.

### Referências legais
- Art. 104 da Lei nº 8.213/1991

### Dicas de prova
- Distinção entre atividades de direção em entidades diferentes.
- Reconhecimento do recebimento de remuneração como exigência para o benefício.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.40 (2)", "page_number": 40, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 104 da Lei nº 8.213/1991"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:53:11.302852+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=40", "doc_key": "07a4953ad3b37cad5daaa403aa285e2b"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '50bc3f99c6d2369b6b0b3f96073572316aae6254bcdcf8a76b005fd55367117a'),
  ('cpiuris2025::eb8a294bd97dd0a3fa337d9031ee4b62', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Trabalhadores Avulsos e Segurados Especiais', '## Trabalhadores Avulsos e Segurados Especiais

Descreve os tipos de trabalhadores avulsos e segurados especiais, incluindo empregados, empregados domésticos, contribuintes individuais e outros.

### Conceitos
- **Trabalhador Avulso**: Trabalha de forma não contínua para diversas empresas, com intermediação de sindicato ou órgão gestor de mão de obra.
- **Segurado Especial**: Abrange trabalhadores rurais que atuam em regime de economia familiar, pescadores artesanais e seus cônjuges, entre outros.
- **Empregado**: Trabalha para uma empresa com vínculo empregatício e recebe remuneração.
- **Empregado Doméstico**: Presta serviços contínuos, subordinados e sem fins lucrativos no âmbito residencial.
- **Contribuinte Individual**: Pessoa física que trabalha por conta própria ou presta serviços de forma independente.

### Referências legais
- Art. 111 da Constituição Federal
- Art. 115 da Constituição Federal
- Art. 116 da Constituição Federal
- Art. 119 da Constituição Federal
- Art. 120 da Constituição Federal

### Dicas de prova
- Entenda a distinção entre trabalhador avulso e empregado.
- Conheça os requisitos para ser considerado segurado especial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.41 (1)", "page_number": 41, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 111 da Constituição Federal", "Art. 115 da Constituição Federal", "Art. 116 da Constituição Federal", "Art. 119 da Constituição Federal", "Art. 120 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:53:50.635701+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=41", "doc_key": "eb8a294bd97dd0a3fa337d9031ee4b62"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '3172db7379cfa47c1a69427626bbc6ed366444daed8785244ab7ecf96f499cd9'),
  ('cpiuris2025::47708e39428168bb739812ccccbf9669', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Trabalhador Avulso e Segurado Especial', '## Trabalhador Avulso e Segurado Especial

Definição de Trabalhador Avulso e Segurado Especial, bem como procedimentos para filiação ao RGPS.

### Conceitos
- **Trabalhador Avulso**: Executa atividades remuneradas de forma não contínua, por intermédio de sindicatos ou órgãos gestores.
- **Segurado Especial**: Trabalhadores rurais em regime de economia familiar, pescadores artesanais e seus respectivos dependentes.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinção entre Trabalhador Avulso e Segurado Especial
- Entendimento do conceito de atividades remuneradas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.41 (2)", "page_number": 41, "discipline": "Direito Previdenciário", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:54:10.862397+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=41", "doc_key": "47708e39428168bb739812ccccbf9669"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'fcc4b04ce5e3852ab6542fb4d9a7edeca5934e08011dbf32e074d876ad59364c'),
  ('cpiuris2025::0a08f4c477f585048c46b19b0767f34c', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Filiação dos segurados obrigatórios e facultativos', '## Filiação dos segurados obrigatórios e facultativos

A filiação ao RGPS é automática para indivíduos que desempenham atividades remuneradas, enquanto os segurados facultativos precisam expressar formalmente o desejo de aderir. A inscrição é essencial para formalizar o vínculo e assegurar os direitos previdenciários.

### Conceitos
- **RGPS**: Regime Geral da Previdência Social
- **Filiação obrigatória**: O processo de filiação automático para indivíduos que desempenham atividades remuneradas
- **Filiação facultativa**: O processo de filiação necessário expresso para os segurados facultativos
- **Inscrição**: O ato formal que registra o segurado no sistema previdenciário

### Referências legais
- Art. 12 da Lei nº 8.213/1991

### Dicas de prova
- Diferenciar entre filiação obrigatória e facultativa
- Entender a importância da inscrição para formalizar o vínculo e assegurar os direitos previdenciários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.42 (1)", "page_number": 42, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 12 da Lei nº 8.213/1991"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:54:55.856789+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=42", "doc_key": "0a08f4c477f585048c46b19b0767f34c"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'aa5e3cacbb6784bea09e523a58244cd324b0f5a51876d6a44c5bea097ec8379c'),
  ('cpiuris2025::3e1c119cc05e14bb2c1249e1c40da2f4', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Inscrição no Registo Previdenciario', '## Inscrição no Registo Previdenciario

A inscrição no registro previdenciário é feita pelo empregador ou pelo próprio segurado, utilizando identificadores como NIT ou CPF.

### Conceitos
- **NIT**: Número de Identificação do Trabalhador
- **PIS/PASEP**: Programa de Integração Social/Programa de Aposentadorias por Requisito Solidário

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Identificar o identificador utilizado pela legislação (NIT ou CPF)
- Diferenciar entre a inscrição do empregador e do próprio segurado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.42 (2)", "page_number": 42, "discipline": "Direito Previdenciário", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:55:14.303662+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=42", "doc_key": "3e1c119cc05e14bb2c1249e1c40da2f4"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '19de2dc8a08bb8f048efc15cf3debbc407b3218a13e3e707ce7445528278fa83'),
  ('cpiuris2025::3427f9919fb011597742410aafe46968', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Inscrição e Seguridade Social', '## Inscrição e Seguridade Social

Descreve as condições para a inscrição em segurança social, incluindo PIS/PASEP, NIS e CPF, bem como as particularidades da inscrição de segurados especiais e trabalhadores rurais contratados.

### Conceitos
- **Segurado Especial**: Pessoa que pode ser inscrita post mortem para garantir o acesso de dependentes a benefícios
- **Trabalhador Rural Contratado**: Pessoa que pode ser inscrita mediante declaração do empregador via sistemas como o eSocial
- **Segurado Facultativo**: Pessoa que pode se enquadrar voluntariamente na segurança social, incluindo estudantes, donas de casa e brasileiros residentes ou domiciliados no exterior

### Referências legais
- Art. 11, § 1º, do RPS
- Art. 132 da Lei n. 8.069, de 13 de julho de 1990

### Dicas de prova
- Entenda a distinção entre segurado especial e trabalhador rural contratado.
- Conheça as condições para a inscrição como segurado facultativo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.43", "page_number": 43, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 11, § 1º, do RPS", "Art. 132 da Lei n. 8.069, de 13 de julho de 1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:55:48.955539+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=43", "doc_key": "3427f9919fb011597742410aafe46968"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '6a276c61934c5ab88bad0af45e28490553288f21bc242843bcb11f8f0404377d'),
  ('cpiuris2025::949da4be0d0bed4622215fff2df47f9d', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Filiação e Inscrição no RGPS', '## Filiação e Inscrição no RGPS

A filiação ao RGPS ocorre automaticamente para segurados obrigatórios, enquanto os segurados facultativos dependem de inscrição voluntária.

### Conceitos
- **RGPS**: Regime Geral da Previdência Social
- **Segurado Obrigatório**: Trabalhador que está automaticamente filiado ao RGPS
- **Segurado Facultativo**: Trabalhador que precisa se inscrever voluntariamente no RGPS
- **Inscrição Voluntária**: Procedimento pelo qual o segurado facultativo se inscreve no RGPS
- **Cadastro Nacional de Informações Sociais (CNIS)**: Sistema que registra os dados pessoais dos trabalhadores

### Referências legais
- Art. 201, § 5º da CF/1988

### Dicas de prova
- Entenda a diferença entre segurado obrigatório e facultativo.
- Conheça os requisitos para inscrição no RGPS.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.44", "page_number": 44, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 201, § 5º da CF/1988"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-27T16:56:30.428432+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=44", "doc_key": "949da4be0d0bed4622215fff2df47f9d"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'da8b189b1445333599731a169c9580eec7c6eb820756af7925370f5b3b5ec001'),
  ('cpiuris2025::4822fbc550691cf3acea7521d7c81583', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Segurados Empregados e Titulares de Mandatos Eletivos', '## Segurados Empregados e Titulares de Mandatos Eletivos

Contratos irregulares podem ser considerados segurados empregados, titulares de mandatos eletivos são segurados obrigatórios desde que não vinculados a RPPS.

### Conceitos
- **Segurado Empregado**: Pessoa que trabalha em regime de emprego e está sujeita à previdência social.
- **Titular de Mandato Eletivo**: Pessoa eleita para um cargo, não vinculada a RPPS.
- **Contribuição Previdenciária**: Taxa paga pelos segurados e empregadores para financiar o sistema previdenciário.

### Referências legais
- Art. 102 da Lei nº 11.788/2008
- Emenda Constitucional nº 20/1998

### Dicas de prova
- Distinção entre contratos irregulares e segurados empregados.
- Vinculação a RPPS para titular de mandato eleito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.45", "page_number": 45, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 102 da Lei nº 11.788/2008", "Emenda Constitucional nº 20/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:56:54.015724+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=45", "doc_key": "4822fbc550691cf3acea7521d7c81583"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '4079c3e3e96a6900620d4c6e9d9984fd2c656e1291ac08575a42f25e9a9c1168'),
  ('cpiuris2025::252f1ee90049edbb2ba886c2c4cd66af', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Financiamento da Seguridade Social', '## Financiamento da Seguridade Social

O financiamento da seguridade social no Brasil é baseado em um princípio de solidariedade, com contribuições diretas e indiretas de indivíduos, empresas e o governo.

### Conceitos
- **Solidariedade**: Princípio que envolve a participação de toda a sociedade no financiamento da seguridade social
- **Contribuições diretas**: Contribuições especiais feitas por indivíduos e empresas para o sistema previdenciário
- **Contribuições indiretas**: Dotações orçamentárias dos entes federativos para financiar a seguridade social
- **Financiamento abrangente**: Caracterização do sistema previdenciário como diversificado e abrangente

### Referências legais
- Art. 195 da Constituição Federal de 1988

### Dicas de prova
- Distinção entre contribuições diretas e indiretas
- Entendimento do princípio solidário no financiamento da seguridade social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.47", "page_number": 47, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 195 da Constituição Federal de 1988"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-27T16:57:26.376111+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=47", "doc_key": "252f1ee90049edbb2ba886c2c4cd66af"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'd4636621b32e7f3ba27e2ac019d995823c120eae17d91357acc702f7d74a8656'),
  ('cpiuris2025::74b47bdac0fbf1939c08c166929aa579', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Equiparação de Entidades e Pessoas Físicas como Empresas', '## Equiparação de Entidades e Pessoas Físicas como Empresas

A legislação previdenciária equipara entidades e pessoas físicas que possuem características que as equiparam para fins de cumprimento das obrigações previdenciárias, visando cobrir todas as relações de trabalho formalmente reconhecidas pelo RGPS.

### Conceitos
- **Empregador Doméstico**: Aquele que admite trabalhadores para funções sem fins lucrativos
- **Equiparadas a Empresa**: Entidades e pessoas físicas equiparadas para fins de cumprimento das obrigações previdenciárias
- **Contribuintes Individuais com Empregados**: Profissionais autônomo que contratam assistência em suas atividades
- **Cooperativas, Associações e Entidades**: Organizações de qualquer natureza consideradas empresas para fins de cumprimento de obrigações previdenciárias
- **Proprietários de Obras de Construção Civil**: Pessoas físicas que realizam pequenas construções e contratam trabalhadores
- **Operadores Portuários e Órgãos Gestores de Mão de Obra (OGMO)**: Responsáveis por trabalhadores avulsos, respondem solidariamente pelas contribuições

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre empregador doméstico e equiparada a empresa
- Conheça as categorias equiparadas para fins de cumprimento das obrigações previdenciárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.48 (1)", "page_number": 48, "discipline": "Direito Previdenciário", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:58:20.378075+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=48", "doc_key": "74b47bdac0fbf1939c08c166929aa579"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'b3291ef51b2a2badd1472f19b20ab17a6c08d413fe7cec67a43eb48ab60c167a'),
  ('cpiuris2025::ec4927e28c4b2b67dc3c90d75e7f7ae1', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Equiparação de pessoas físicas ou jurídicas a empresas', '## Equiparação de pessoas físicas ou jurídicas a empresas

Pessoas físicas ou jurídicas equiparadas a empresas em determinadas situações, como contratação de trabalhadores subordinados e remunerados.

### Conceitos
- **Contribuinte Individual Contratante**: Pessoa física que contrata trabalhadores para prestar serviços de forma subordinada e remunerada
- **Cooperativas, Associações e Entidades Similares**: Organizações sem fins lucrativos

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinção entre contribuinte individual contratante e outras formas de equiparação
- Importância do contrato de trabalho para a equiparação como empresa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.48 (2)", "page_number": 48, "discipline": "Direito Previdenciário", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:58:41.481130+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=48", "doc_key": "ec4927e28c4b2b67dc3c90d75e7f7ae1"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'efa237003c27c8ac341d5f3e07973c10e60501afd648fddb4f1d582833c71b97'),
  ('cpiuris2025::b3af5d3c9f7f0accda021015b3048766', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Entidades equiparadas para fins previdenciários', '## Entidades equiparadas para fins previdenciários

Empresas, operadores portuários e proprietários de obras de construção civil que contratam trabalhadores vinculados ao RGPS devem recolher contribuições e cumprir as exigências legais.

### Conceitos
- **Entidade equiparada**: Pessoa física ou jurídica que deve cumprir as obrigações previdenciárias devido ao contrato de trabalho.
- **Registro e matrícula**: Obrigação de registrar e matricular a entidade ou pessoa física responsável.
- **Recolhimento de contribuições**: Obrigação de recolher as contribuições sobre a remuneração dos trabalhadores.
- **Envio de informações**: Obrigação de enviar informações por meio de sistemas como o eSocial, quando aplicável.

### Referências legais
- Art. 195 da Constituição Federal

### Dicas de prova
- Entenda a distinção entre trabalhador avulso e trabalhador vinculado ao RGPS.
- Conheça as obrigações das entidades equiparadas para fins previdenciários.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.49 (1)", "page_number": 49, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 195 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:59:14.119900+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=49", "doc_key": "b3af5d3c9f7f0accda021015b3048766"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'a33e33df3b1542d00c51fafd8c826af792bee88fe1744f6d1e2b6dfc7c2ddb6d'),
  ('cpiuris2025::eaddad733809d3fd72db20ff3526c1e9', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Fontes de Financiamento do Sistema Previdenciário', '## Fontes de Financiamento do Sistema Previdenciário

As fontes de financiamento do sistema previdenciário incluem receitas da União, que são fundamentais para garantir o pagamento de benefícios e a execução de programas sociais.

### Conceitos
- **Seguridade Social**: sistema de previdência social brasileiro
- **Orçamento da União**: fonte de financiamento do governo federal

### Referências legais
- Art. 197 da Lei nº 8.213/1991

### Dicas de prova
- Entenda a importância das receitas da União no financiamento do sistema previdenciário
- Conheça as diferentes categorias de receitas que compõem o sistema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.49 (2)", "page_number": 49, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 197 da Lei nº 8.213/1991"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T16:59:44.404470+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=49", "doc_key": "eaddad733809d3fd72db20ff3526c1e9"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'c9cc979536138aac0d76f341eb2eca42d77cb6df8374ac6714f5eefa17069239'),
  ('cpiuris2025::7da6378eef2d94019de6a8a33d373964', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Financiamento da Seguridade Social', '## Financiamento da Seguridade Social

O financiamento da seguridade social é composto por contribuições diretas, receitas de outras fontes e contribuições sociais, com a diversificação das fontes visando garantir a estabilidade do sistema.

### Conceitos
- **Contribuição Direta**: Arrecadação proveniente de impostos e contribuições sobre o salário
- **Receitas de Outras Fontes**: Fontes adicionais de arrecadação, como penalidades administrativas, repasses de seguradoras e leilões de bens confiscados
- **Contribuições Sociais**: Principal pilar de financiamento da seguridade social, arrecadadas de diferentes atores econômicos
- **Diversificação da Base de Financiamento**: Princípio que visa garantir a estabilidade do sistema mesmo em cenários de crise econômica ou instabilidade em setores específicos

### Referências legais
- Art. 195 da Constituição Federal

### Dicas de prova
- Entenda a importância da diversificação das fontes de financiamento
- Conheça as diferentes formas de contribuições sociais e suas fontes
- Aprenda a distinguir entre receitas de outras fontes e contribuições sociais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.50", "page_number": 50, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 195 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:00:21.221765+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=50", "doc_key": "7da6378eef2d94019de6a8a33d373964"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'cf999b1d04e0a2e1d33681d42af427b1a48b5f59b66800959eb62190ee16f46f'),
  ('cpiuris2025::ecfe49cffbdec7874a98cc14567006b0', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Financiamento da Seguridade Social e Contribuições Diretas e Indiretas', '## Financiamento da Seguridade Social e Contribuições Diretas e Indiretas

O financiamento da seguridade social é regulado por uma legislação abrangente, que estabelece critérios para a arrecadação e destinação das receitas. As contribuições previdenciárias são a base do sistema, sendo diretas (pagamentos feitos por empregadores, empregados e segurados) e indiretas (repasses do orçamento público e receitas vinculadas a atividades específicas).

### Conceitos
- **Contribuições Diretas**: Pagamentos feitos por empregadores, empregados e segurados, como contribuições previdenciárias descontadas da folha de pagamento.
- **Contribuições Indiretas**: Repasses do orçamento público e receitas vinculadas a atividades específicas, como multas, juros de mora e atualizações monetárias.
- **Financiamento da Seguridade Social**: Regulado por uma legislação abrangente que estabelece critérios para a arrecadação e destinação das receitas.

### Referências legais
- Lei nº 8.212/1991

### Dicas de prova
- Entenda a distinção entre contribuições diretas e indiretas.
- Conheça os critérios para a arrecadação e destinação das receitas do financiamento da seguridade social.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.51 (1)", "page_number": 51, "discipline": "Direito Previdenciário", "legal_refs": ["Lei nº 8.212/1991"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:00:58.182275+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=51", "doc_key": "ecfe49cffbdec7874a98cc14567006b0"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'de18ac9cc6c18246352780f3246669fc08f3594725c41e781ad2582cc1b424f7'),
