  ('cpiuris2025::3baf53344d2b92180a10e2b673b7b0ed', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Contribuições das Empresas', '## Contribuições das Empresas

As empresas são responsáveis por uma parcela significativa das contribuições previdenciárias, incluindo a contribuição de 20% sobre a folha de pagamento e contribuições adicionais como o GILRAT.

### Conceitos
- **Contribuição de 20%**: Contribuição sobre a folha de pagamento das empresas
- **GILRAT**: Grau de Incidência de Incapacidade Laborativa Decorrente dos Riscos Ambientais do Trabalho

### Referências legais
- Art. 12 da Lei nº 8.213/1991

### Dicas de prova
- Entenda a distinção entre contribuição de 20% e GILRAT
