  ('cpiuris2025::ea81b075efc194d97e06026cae51be4b', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Contribuições adicionais e folha de pagamento', '## Contribuições adicionais e folha de pagamento

São discutidos os impostos sobre as remunerações pagas a empregados e trabalhadores avulsos, bem como as contribuições adicionais para atividades de maior risco.

### Conceitos
- **Grau de Incidência de Incapacidade Laborativa Decorrente dos Riscos Ambientais do Trabalho (GILRAT)**: sistema que aplica contribuições adicionais com base no grau de risco
- **Contribuições Adicionais**: impostos pagos por atividades de maior risco
- **Folha de Pagamento**: documento que contém as informações sobre as remunerações pagas a empregados e trabalhadores avulsos

### Referências legais
- Art. X da Lei Y

