  ('cpiuris2025::34cbed8bb5e0bf8c4ce6a3612e3ba3fe', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Financiamento e Contribuições dos Segurados', '## Financiamento e Contribuições dos Segurados

As contribuições dos segurados são fundamentais para o financiamento do sistema previdenciário, variando conforme a categoria e os rendimentos recebidos.

### Conceitos
- **Contribuição Individual**: 20% sobre o salário de contribuição
- **Contribuição Patronal**: incidente sobre o serviço prestado, limitada a 9% do salário de contribuição
- **Alíquota Progressiva**: percentual que aumenta de acordo com o valor do salário de contribuição
- **Tabela de Alíquotas Progressivas**: faixa de rendimentos com alíquota específica
- **Contribuinte Individual**: autônomos e profissionais liberais que recolhem 20% sobre o salário de contribuição
- **Segurado Facultativo**: dona de casa, estudante e desempregado que pode contribuir com 20% sobre o salário de contribuição
- **Alíquota Reduzida**: 5% sobre o salário mínimo para microempreendedores individuais e donas de casa de baixa renda
- **Contribuições Especiais**: regras especiais de contribuição para segurados especiais e microempreendedores individuais

### Referências legais
- Art. 12 da Lei nº 8.213/1991

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância das contribuições dos segurados e como elas variam conforme a categoria e os rendimentos recebidos.
- Conheça as alíquotas progressivas e as tabelas de alíquotas para determinar o percentual efetivo de contribuição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.53", "page_number": 53, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 12 da Lei nº 8.213/1991"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T17:03:10.639449+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=53", "doc_key": "34cbed8bb5e0bf8c4ce6a3612e3ba3fe"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '7a743d604e5ddf18b1d43416b31ca4e6b9c38c877c3790fd70c6db5afd718dfd'),
  ('cpiuris2025::eb0988c503a9a188ea7b9b137b889982', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Financiamento da Seguridade Social', '## Financiamento da Seguridade Social

As contribuições previdenciárias são calculadas com base em fatores definidos pela legislação, sendo destinadas ao GILRAT e garantindo o pagamento de benefícios como aposentadorias, pensões e auxílios.

### Conceitos
- **Fato Gerador**: O momento em que ocorre o pagamento ou crédito da remuneração
- **Base de Cálculo**: O salário de contribuição para os segurados e a folha de pagamento para as empresas
- **Contribuições Previdenciárias**: Desempenham um papel central no sistema de seguridade social

### Referências legais
- Art. 12 da Lei nº 8.212/91

### Dicas de prova
- Entenda a distinção entre Fato Gerador e Base de Cálculo
- Conheça o papel das contribuições previdenciárias no sistema de seguridade social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.54", "page_number": 54, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 12 da Lei nº 8.212/91"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:03:36.035327+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=54", "doc_key": "eb0988c503a9a188ea7b9b137b889982"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '7b8a4f8c891ceaa6012e81941bc8afd5e906a422e5b379512474fc85de625094'),
  ('cpiuris2025::2a0aaf87c0af87110679355c4d39f5f0', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Benefícios Previdenciários e Papel da Seguridade Social', '## Benefícios Previdenciários e Papel da Seguridade Social

Os benefícios previdenciários são a principal expressão do compromisso do sistema de seguridade social com a proteção contra riscos sociais, garantindo suporte financeiro aos segurados e seus dependentes em situações que comprometem sua subsistência.

### Conceitos
- **Benefícios Previdenciários**: suporte financeiro aos segurados e seus dependentes
- **Seguridade Social**: sistema de proteção contra riscos sociais
- **Contribuições**: obrigatórias para trabalhadores e empregadores
- **Princípio da Solidariedade**: equilíbrio entre contribuintes e beneficiários
- **Aposentadorias**: benefícios que permitem o afastamento remunerado do mercado de trabalho
- **Idade Mínima**: 65 anos para homens, 62 anos para mulheres
- **Tempo de Contribuição**: 15 anos

### Referências legais
- Art. 40 da Constituição Federal
- Lei nº 8.213/1991

### Dicas de prova
- Entenda o papel dos benefícios previdenciários na seguridade social
- Conheça as diferentes modalidades de aposentadorias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.56", "page_number": 56, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 40 da Constituição Federal", "Lei nº 8.213/1991"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:04:12.780378+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=56", "doc_key": "2a0aaf87c0af87110679355c4d39f5f0"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '8fbfe4261a83f7894d3f46b99f05057b76d8caf75bd953ce45ddc71133d0c8d9'),
  ('cpiuris2025::7ab70fe658b61dde5da2de4c33dd3f2a', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Benefícios Previdenciários', '## Benefícios Previdenciários

Resumo dos benefícios previdenciários disponíveis, incluindo aposentadoria por tempo de contribuição, aposentadoria especial, aposentadoria por invalidez e auxílios.

### Conceitos
- **Aposentadoria por Tempo de Contribuição**: Benefício concedido a segurados que cumpriram os requisitos antes de 13 de novembro de 2019
- **Aposentadoria Especial**: Concedida a trabalhadores expostos a agentes nocivos à saúde ou integridade física, sem necessidade de idade mínima
- **Aposentadoria por Invalidez**: Destinada aos segurados permanentemente incapacitados de exercer qualquer atividade remunerada
- **Auxílio-Doença**: Concedido aos segurados incapazes de exercer suas atividades habituais por mais de 15 dias consecutivos
- **Auxílio-Acidente**: Pago como indenização ao segurado que sofre redução permanente de sua capacidade laboral em decorrência de acidente de qualquer natureza
- **Salário-Maternidade**: Benefício destinado a seguradas durante o afastamento decorrente de maternidade, adoção ou guarda judicial de criança

### Referências legais
- Art. 103 da EC nº 103/2019

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre aposentadoria por tempo de contribuição e aposentadoria especial
- Importância do tempo de exposição para a concessão da aposentadoria especial
- Requisitos para a concessão da aposentadoria por invalidez', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.57", "page_number": 57, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 103 da EC nº 103/2019"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T17:05:05.970581+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=57", "doc_key": "7ab70fe658b61dde5da2de4c33dd3f2a"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'b4654a37af47462b0b3dba0ce0e373e0f4739f5f952d0fd1b3a791dff115a6de'),
  ('cpiuris2025::c9ad5f186348ed22748460e054d7385a', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Benefícios Previdenciários', '## Benefícios Previdenciários

Benefícios previdenciários asseguram proteção à mulher trabalhadora e à criança, pensão por morte aos dependentes do segurado falecido, auxílio-reclusão para dependentes de segurados presos em regime fechado e benefícios especiais para trabalhadores rurais e pescadores artesanais.

### Conceitos
- **Benefício Previdenciário**: Assegura proteção à mulher trabalhadora e à criança, pensão por morte aos dependentes do segurado falecido, auxílio-reclusão para dependentes de segurados presos em regime fechado e benefícios especiais para trabalhadores rurais e pescadores artesanais.
- **Pensão por Morte**: Paga aos dependentes do segurado falecido, garantindo-lhes sustento financeiro.
- **Auxílio-Reclusão**: Concedido aos dependentes de segurados presos em regime fechado, desde que atendam aos critérios de baixa renda e mantenham contribuições ao RGPS.
- **Benefícios Especiais**: Para trabalhadores rurais e pescadores artesanais, com valor geralmente correspondente ao salário mínimo e contribuição incidente sobre a comercialização de sua produção.
- **Sustentabilidade dos Benefícios**: Depende do equilíbrio entre a arrecadação e os gastos, com regras rígidas de concessão e manutenção, além de cálculos atuariais baseados na expectativa de vida e no comportamento demográfico.
- **Desafios Físcais**: O envelhecimento populacional, informalidade no mercado de trabalho e redução da base contributiva representam um desafio significativo para a manutenção do equilíbrio financeiro.

### Referências legais
- Art. 40 da Lei nº 8.213/1991
- Súmula 394 da STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Benefícios Previdenciários

### Dicas de prova
- Entenda a definição de benefício previdenciário e seus diferentes tipos.
- Conheça as regras para concessão e manutenção dos benefícios, incluindo cálculos atuariais.
- Análise os desafios fiscais enfrentados pelo sistema previdenciário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.58", "page_number": 58, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 40 da Lei nº 8.213/1991", "Súmula 394 da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Benefícios Previdenciários"], "confidence": 0.8, "extracted_at": "2026-05-27T17:06:04.733354+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=58", "doc_key": "c9ad5f186348ed22748460e054d7385a"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '23aac272ed65f98c7a94ce4f504b3aacd8693b1553a50529618ea2dab37ce7b1'),
  ('cpiuris2025::0fbe14c837d25a4f90d6f40eb2649cc3', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Benefícios Previdenciários e Regras de Transição', '## Benefícios Previdenciários e Regras de Transição

Os benefícios previdenciários desempenham um papel essencial na proteção social, garantindo segurança, dignidade e estabilidade social. A regra de transição foi criada para preservar direitos adquiridos e adaptar o sistema às mudanças estruturais.

### Conceitos
- **Benefícios Previdenciários**: segurança financeira aos trabalhadores em situações de incapacidade, velhice ou perda de renda
- **Regras de Transição**: solução para preservar direitos adquiridos e adaptar o sistema às mudanças estruturais
- **Universalidade da Cobertura**: garante acesso aos benefícios a todos os cidadãos que contribuam ou sejam classificados como segurados
- **Diversidade de Fontes de Financiamento**: reduz a dependência de uma única fonte, mitigando impactos de crises econômicas

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda o conceito de regra de transição e sua importância na proteção dos direitos adquiridos.
- Conheça os diferentes tipos de segurados (obrigatórios, facultativos e especiais) e suas contribuições.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.59", "page_number": 59, "discipline": "Direito Previdenciário", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:06:40.283393+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=59", "doc_key": "0fbe14c837d25a4f90d6f40eb2649cc3"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'b142977fcd854ef7bb7713abde21c9f84db89f9850805d54f07de5051845e6fe'),
  ('cpiuris2025::5da476e7fccca3aff0fa5f2df40d2e4c', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Benefícios Previdenciários', '## Benefícios Previdenciários

Os benefícios previdenciários são reforçados pela solidariedade social, visando amparar os mais vulneráveis. A sustentabilidade e a gestão das despesas são fundamentais para o equilíbrio do sistema.

### Conceitos
- **Solidariedade Social**: Reforço da contribuição conjunta de toda a sociedade
- **Sustentabilidade**: Equilíbrio entre arrecadação e despesas

### Referências legais
- Art. 4 da Lei nº X
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da solidariedade social nos benefícios previdenciários
- Avalie o equilíbrio entre arrecadação e despesas para sustentabilidade do sistema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.60", "page_number": 60, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 4 da Lei nº X", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T17:07:10.923151+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=60", "doc_key": "5da476e7fccca3aff0fa5f2df40d2e4c"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '28e3b2188ead26c9b29aeabd2f1f86c2f9190bc258f08fed77e81d8a157f2c7a'),
  ('cpiuris2025::33a9138867b0369cf97bc2baa6bacb9b', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Salário de Contribuição', '## Salário de Contribuição

O salário de contribuição é a base para o cálculo das contribuições previdenciárias e define o valor base sobre o qual incidem as alíquotas, permitindo o financiamento de benefícios como aposentadorias e pensões.

### Conceitos
- **Salário de Contribuição**: Montante sobre o qual incide a contribuição previdenciária
- **Remuneração**: Todos os valores pagos ao trabalhador, sem limites
- **Contribuição Previdenciária**: Base do financiamento do sistema de seguridade social no Brasil

### Referências legais
- Art. 28 da Lei nº 8.212/1991
- Art. 214 do Regulamento da Previdência Social (RPS)

### Dicas de prova
- Entenda a diferença entre salário de contribuição e remuneração
- Conheça as especificidades do salário de contribuição para cada categoria de segurado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.62 (1)", "page_number": 62, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 28 da Lei nº 8.212/1991", "Art. 214 do Regulamento da Previdência Social (RPS)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:07:40.011173+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=62", "doc_key": "33a9138867b0369cf97bc2baa6bacb9b"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '7b7864ca3a3ca26ee316b67d42237607d604b4c4a3a0b6240ddab687fe327e4e'),
  ('cpiuris2025::b1bdab22798b7872c356276ee4d7adf6', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Salário de Contribuição', '## Salário de Contribuição

O salário de contribuição é o valor registrado na carteira de trabalho, respeitados os limites mínimo e máximo. Para empregados domésticos, o salário de contribuição é o piso salarial da categoria ou o salário mínimo nacional.

### Conceitos
- **Salário de Contribuição**: Valor registrado na carteira de trabalho
- **Piso Salarial**: Referência mínima para os empregados domésticos
- **Salário Mínimo Nacional**: Utilizado como base quando não existir piso salarial estadual

### Referências legais
- Art. 102 da Lei nº 8.213/1991
- ...

### Jurisprudência
- Súmula 342 do TST

### Dicas de prova
- Diferenciar entre piso salarial e salário mínimo nacional
- Considerar a categoria de empregado doméstico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.62 (2)", "page_number": 62, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 102 da Lei nº 8.213/1991", "..."], "jurisprudence": ["Súmula 342 do TST"], "confidence": 0.8, "extracted_at": "2026-05-27T17:08:03.565193+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=62", "doc_key": "b1bdab22798b7872c356276ee4d7adf6"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '313ae7d84097c65aedc92111cfe4d687d7cb66a307639cf38504731232164b75'),
  ('cpiuris2025::5c90d72862297595442eb5809d674d4d', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Salário de Contribuição e Limites', '## Salário de Contribuição e Limites

O contribuinte deve informar ao INSS sobre rendimentos que ultrapassam o teto previdenciário para evitar descontos indevidos. O segurado facultativo pode escolher quanto contribuir, respeitando os limites mínimo e máximo.

### Conceitos
- **Salário de Contribuição**: Valor pago pelo trabalhador para contribuir para o sistema previdenciário
- **Teto Previdenciário**: Limite máximo do salário de contribuição, atualmente em R$ 7.786,02
- **Limites Mínimo e Máximo**: Definem a base de cálculo do salário de contribuição

### Referências legais
- Art. 102 da Lei nº 8.213/1991

### Jurisprudência
- Súmula 378/STF

### Dicas de prova
- Entenda a importância da informação sobre rendimentos ultrapassantes do teto previdenciário
- Conheça os limites mínimo e máximo para o salário de contribuição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.63 (1)", "page_number": 63, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 102 da Lei nº 8.213/1991"], "jurisprudence": ["Súmula 378/STF"], "confidence": 0.8, "extracted_at": "2026-05-27T17:08:43.545772+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=63", "doc_key": "5c90d72862297595442eb5809d674d4d"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'c5d9c5810e154be63e90a6dc98dd13a2e616fdb9578839db4712ac999f4e1f18'),
  ('cpiuris2025::1b5ef11018bcdb43b1e37c18b299ce07', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Parcelas que Integram o Salário de Contribuição', '## Parcelas que Integram o Salário de Contribuição

São incluídas no salário de contribuição todas as parcelas remuneratórias habituais, excetuando-se verbas indenizatórias inferiores a 50% do salário.

### Conceitos
- **Salário de Contribuição**: valor pago pelos trabalhadores para o INSS
- **Parcela Remuneratória Habitual**: salários, adicionais, comissões e outras vantagens pagas de forma previsível
- **Verva Indenizatória**: verbas pagas por razão de lesão ou perigo à saúde, férias, etc.

### Referências legais
- Art. 12 da Lei nº 8.213/1991

### Jurisprudência
- Súmula 342 do STJ

### Dicas de prova
- Distinguir entre parcelas remuneratórias habituais e verbas indenizatórias
- Entender que o salário-maternidade também integra o salário de contribuição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.63 (2)", "page_number": 63, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 12 da Lei nº 8.213/1991"], "jurisprudence": ["Súmula 342 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T17:09:06.771755+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=63", "doc_key": "1b5ef11018bcdb43b1e37c18b299ce07"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '70e02fe3b86cf54d104247a1f430ab050e60094aa24f78e59714493d5b6a7ff4'),
  ('cpiuris2025::7c76bd86e6f2f201ad419639facaa100', 'doutrina', 'cp_iuris', 'Direito Previdenciaro — Parcelas do salário de contribuição', '## Parcelas do salário de contribuição

As parcelas que fazem parte do salário de contribuição são todas as remunerações que o trabalhador recebe de forma habitual e previsível, incluindo benefícios como salário-maternidade.

### Conceitos
- **Salário de contribuição**: Remuneração recebida pelo trabalhador de forma habitual e previsível
- **Benefício**: Pagamento concedido por uma entidade, como a previdência social
- **Contribuição previdenciária**: Imposto pago pelos contribuintes para financiar o sistema previdenciário

### Referências legais
- Art. 102 da CLT
- Súmula 244 do STJ

### Jurisprudência
- RE 123456
- Súmula 244/STJ

### Dicas de prova
- Entenda a diferença entre pagamento pelo trabalho e indenização
- Análise cuidadosa das parcelas que fazem parte do salário de contribuição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.64 (1)", "page_number": 64, "discipline": "Direito Previdenciaro", "legal_refs": ["Art. 102 da CLT", "Súmula 244 do STJ"], "jurisprudence": ["RE 123456", "Súmula 244/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T17:09:34.010167+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=64", "doc_key": "7c76bd86e6f2f201ad419639facaa100"}'::jsonb, '{"materia": "Direito Previdenciaro"}'::jsonb, 'cp_iuris_2025', '4e1aa01445e46dfcc7aad33cda6399f6898757968d46fb12066671d82eb43ccc'),
  ('cpiuris2025::59336b733b9c2d7b8cb1a588e5821ede', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Contribuição previdenciária sobre salário-maternidade', '## Contribuição previdenciária sobre salário-maternidade

A contribuição previdenciária sobre o salário-maternidade é questionada pela incidência da contribuição patronal. O salário-maternidade é considerado um benefício previdenciário e não se enquadra na folha de salários, portanto, não pode ser usado como base de cálculo da contribuição previdentiária.

### Conceitos
- **Contribuição previdenciária**: Imposto pago pela segurada à Previdência Social
- **Salário-maternidade**: Benefício previdenciário pago pela Previdência Social à segurada durante a licença-maternidade
- **Folha de salários**: Rendimentos do trabalho pagos ou creditados à pessoa física que lhe presta serviço
- **Contribuição patronal**: Imposto pago pelo empregador à Previdência Social

### Referências legais
- Art. 195, I, a, da Constituição

### Jurisprudência
- RE 576967 (Tema 72)

### Dicas de prova
- Entenda que o salário-maternidade é um benefício previdenciário e não se enquadra na folha de salários.
- Conheça a distinção entre contribuição previdentiária e contribuição patronal.
- Avalie a inconstitucionalidade formal e material da incidência da contribuição previdentiária sobre o salário-maternidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.64 (2)", "page_number": 64, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 195, I, a, da Constituição"], "jurisprudence": ["RE 576967 (Tema 72)"], "confidence": 0.8, "extracted_at": "2026-05-27T17:10:20.774950+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=64", "doc_key": "59336b733b9c2d7b8cb1a588e5821ede"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'aeaeca2a82dd252f7b4712f51e5f3e1d8d38ff72a2b7a1766ab5e8debb771f0f'),
  ('cpiuris2025::62f1a913680aa822637f4e55f5538825', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Inconstitucionalidade da incidência de contribuição previdenciária sobre o salário-maternidade', '## Inconstitucionalidade da incidência de contribuição previdenciária sobre o salário-maternidade

A Corte Suprema de Justiça (STF) declarou inconstitucional a incidência de contribuição previdenciária do empregador sobre o salário-maternidade, considerando que essa discriminação é contra o princípio da isonomia e da proteção à maternidade.

### Conceitos
- **Contribuição Previdenciária**: Taxa cobrada pelo empregador sobre o salário-maternidade
- **Isonomia**: Princípio que estabelece a igualdade entre homens e mulheres
- **Maternidade**: Proteção à mulher durante a gravidez e o parto

### Referências legais
- Art. 195, §4º da Lei n. 8.212/91
- Súmula 376 do STF

### Jurisprudência
- RE 576967
- Tema repetitivo: inconstitucionalidade de discriminação em benefícios previdenciários

### Dicas de prova
- Entenda a noção de contribuição previdenciária e sua incidência sobre o salário-maternidade
- Aprenda a aplicar o princípio da isonomia na interpretação das leis previdenciárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.65 (1)", "page_number": 65, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 195, §4º da Lei n. 8.212/91", "Súmula 376 do STF"], "jurisprudence": ["RE 576967", "Tema repetitivo: inconstitucionalidade de discriminação em benefícios previdenciários"], "confidence": 0.8, "extracted_at": "2026-05-27T17:10:57.311980+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=65", "doc_key": "62f1a913680aa822637f4e55f5538825"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '81a4bf23a085d215a50113f3fc9df7726e674aad4987bc44ba613b36e3b2c2ce'),
  ('cpiuris2025::ae93a871677e09c150a41c35d248a048', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Contribuição Previdenciária e Parcelas Não Integrantes do Salário de Contribuição', '## Contribuição Previdenciária e Parcelas Não Integrantes do Salário de Contribuição

A contribuição previdenciária pode ser exigida sobre o 1/3 de férias, mas não é considerada no cálculo do salário de benefício. As parcelas não integrantes do salário de contribuição incluem benefícios da previdência social, ajuda de custo e alimentação fornecida pela empresa.

### Conceitos
- **Contribuição Previdenciária**: Taxa paga pelos trabalhadores para financiar o sistema previdenciário
- **Parcelas Não Integrantes do Salário de Contribuição**: Benefícios e valores que não são considerados no cálculo do salário de contribuição
- **Salário de Benefício**: Valor pago aos aposentados ou pensionistas
- **Contribuição Social**: Taxa paga pelos trabalhadores para financiar o sistema previdenciário, que pode ser exigida sobre o 1/3 de férias

### Referências legais
- Art. 28, § 9º, da Lei n. 8.212/1991
- Art. 214, § 9º, do RPS

### Jurisprudência
- RE 123456
- Tema repetitivo sobre parcelas não integrantes do salário de contribuição

### Dicas de prova
- Entenda a diferença entre contribuição previdenciária e contribuição social
- Conheça as categorias de parcelas que não integram o salário de contribuição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.65 (2)", "page_number": 65, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 28, § 9º, da Lei n. 8.212/1991", "Art. 214, § 9º, do RPS"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre parcelas não integrantes do salário de contribuição"], "confidence": 0.8, "extracted_at": "2026-05-27T17:11:35.268386+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=65", "doc_key": "ae93a871677e09c150a41c35d248a048"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '46338d8c610004e48384b7f7bd30ea0066ee0d40b86a852ab13637eac494eb0b'),
  ('cpiuris2025::8fd9502d03cb2b26ce457875439ccb7d', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Salário de Contribuição e Pagamentos Não Integrantes', '## Salário de Contribuição e Pagamentos Não Integrantes

Descreve os pagamentos que não fazem parte do salário de contribuição, como indenizações, ajudas de custo, auxílio-alimentação e diárias de viagem.

### Conceitos
- **Salário de Contribuição**: remuneração do empregado que é integrante do salário para contribuições
- **Pagamento Não Integrante**: pagamento que não faz parte do salário de contribuição
- **Indenização**: pagamento feito por uma empresa em favor de um empregado, sem obrigação de pagamento regular
- **Ajudas de Custo**: pagamento que ajuda o empregado a cobrir os custos de vida
- **Auxílio-Alimentação**: pagamento que compensa as despesas alimentares do empregado
- **Diárias de Viagem**: pagamento feito ao empregado por viagens realizadas a serviço da empresa

### Referências legais
- Art. 214, § 9º, do RPS

### Dicas de prova
- Diferenciar entre pagamentos que fazem parte e não fazem parte do salário de contribuição
- Entender a diferença entre ganhos eventuais e abonos
- Verificar se as despesas de viagem foram comprovadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.66 (1)", "page_number": 66, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 214, § 9º, do RPS"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:12:24.676774+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=66", "doc_key": "8fd9502d03cb2b26ce457875439ccb7d"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'f417e829ff7c236365f37486231302105144bdc7ceb85e4d031fc232355dd302'),
  ('cpiuris2025::6fbaa7a84d725cac9ef2997326705e78', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Parte do salário de contribuição', '## Parte do salário de contribuição

Novas decisões judiciais indicam que o vale-transporte pago em dinheiro não é considerado parte do salário de contribuição, assim como a ajuda de custo recebida em parcela única.

### Conceitos
- **Salário de Contribuição**: Conceito jurídico que se refere ao valor pago pelos empregados aos seus empregadores como forma de contribuição para o sistema previdenciário.
- **Vale-Transporte**: Benefício pago aos funcionários públicos e privados para compensar os custos de transporte
- **Ajuda de Custo**: Benefício pago às pessoas que sofrerem mudança de local de trabalho, para compensar os custos de deslocamento
- **Participação nos Lucros ou Resultados**: Direito dos empregados à participação nos lucros ou resultados da empresa, regulamentada pela Lei nº 10.101/2000

### Referências legais
- Art. 19-A da Lei nº 10.522/2002
- Instrução Normativa RFB nº 2.110/2022

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre o vale-transporte pago em dinheiro e o valor integrante do salário de contribuição.
- Regras para a ajuda de custo recebida em parcela única ou dividida em mais de uma parcela.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.66 (2)", "page_number": 66, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 19-A da Lei nº 10.522/2002", "Instrução Normativa RFB nº 2.110/2022"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T17:13:01.215687+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=66", "doc_key": "6fbaa7a84d725cac9ef2997326705e78"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '51ea9642c3b62df12968ccf78e57dc5dac63c96fd0e79e71bae95664223963e6'),
  ('cpiuris2025::a2fcc0a3f61dd9456b1e96c7afe9c167', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Contribuição Previdenciária sobre Participação nos Lucros', '## Contribuição Previdenciária sobre Participação nos Lucros

A contribuição previdenciária incide sobre os pagamentos feitos antes da Medida Provisória nº 794/1994, mesmo que a regulamentação tenha ocorrido após essa data.

### Conceitos
- **Contribuição Previdenciária**: Imposto pago sobre os valores pagos como participação nos lucros
- **Participação nos Lucros**: Valor pago a trabalhadores sob forma de participação nos lucros
- **Medida Provisória nº 794/1994**: Ato normativo que regulamentou a participação nos lucros
- **Eficácia Limitada do Art. 7º, XI, da CF**: Preceito que depende de regulamentação para sua eficácia

### Referências legais
- Art. 7º, XI, da CF
- Medida Provisória nº 794/1994

### Jurisprudência
- RE 569441
- ACÓRDÃO ELETRÔNICO REPERCUSSÃO GERAL – MÉRITO DJe-027 DIVULG 09-02-2015 PUBLIC 10-02-2015

### Dicas de prova
- Entenda a natureza jurídica da contribuição previdenciária e sua incidência sobre os pagamentos de participação nos lucros
- Conheça a regulamentação da Medida Provisória nº 794/1994 e sua relação com a eficácia do art. 7º, XI, da CF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.67 (1)", "page_number": 67, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 7º, XI, da CF", "Medida Provisória nº 794/1994"], "jurisprudence": ["RE 569441", "ACÓRDÃO ELETRÔNICO REPERCUSSÃO GERAL – MÉRITO DJe-027 DIVULG 09-02-2015 PUBLIC 10-02-2015"], "confidence": 0.8, "extracted_at": "2026-05-27T17:13:41.473786+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=67", "doc_key": "a2fcc0a3f61dd9456b1e96c7afe9c167"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '6cff9f3e66e4b337eca7cc7cf2008e2ca37e79e9195dcbd54313034965f309a5'),
  ('cpiuris2025::d10efec1e6de28dce7f8442d3d5db0d4', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Exigências para planos educacionais e bolsas de estudo', '## Exigências para planos educacionais e bolsas de estudo

Regras para planos educacionais e bolsas de estudo para empregados e dependentes, incluindo limitações e condições.

### Conceitos
- **Contribuição**: Prazo pago pelo trabalhador ao INSS
- **Plano de previdência complementar**: Planos que complementam a previdência do INSS
- **Salário de contribuição**: Valor pago pelo trabalhador ao INSS como contribuição para a previdência
- **Roupas e equipamentos fornecidos**: Benefícios que não são considerados no salário de contribuição

### Referências legais
- Art. 102 da Lei nº 8.213/1991

### Jurisprudência
- Súmula 438 da Súmula Técnica do STF

### Dicas de prova
- Entenda a diferença entre planos de previdência complementar e benefícios que não são considerados no salário de contribuição
- Conheça as condições para planos educacionais e bolsas de estudo, incluindo limitações e percentual máximo do salário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.67 (2)", "page_number": 67, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 102 da Lei nº 8.213/1991"], "jurisprudence": ["Súmula 438 da Súmula Técnica do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T17:14:20.742702+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=67", "doc_key": "d10efec1e6de28dce7f8442d3d5db0d4"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'ac6b25979d4ca013eee57e23a7dd08ab14e8973fff3f0237d39cb059a677dcbd'),
  ('cpiuris2025::f98258b43ac8fc5d21ee524db9226c06', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Salário de Contribuição e Indenizações', '## Salário de Contribuição e Indenizações

O salário de contribuição é calculado com base no salário mínimo de contribuição ou 150% do salário mínimo, sendo consideradas indenizações as multas pagas ao empregado em caso de demissão sem aviso prévio. Além disso, os reembolsos de despesas com creche e babá são permitidos desde que comprovados e respeitam o limite do salário de contribuição.

### Conceitos
- **Salário de Contribuição**: Valor pago pelo empregado para a previdência social
- **Multa Paga ao Empregado**: Indenização paga ao empregado em caso de demissão sem aviso prévio
- **Reembolso de Despesas com Creche e Babá**: Período máximo de seis anos para reembolso de despesas com creche e babá

### Referências legais
- Art. 102 da Lei 8.213/1991
- ...

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Distinção entre salário de contribuição e indenização
- Período máximo para reembolso de despesas com creche e babá', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.68 (1)", "page_number": 68, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 102 da Lei 8.213/1991", "..."], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T17:14:54.491715+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=68", "doc_key": "f98258b43ac8fc5d21ee524db9226c06"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '7f32476c701cb5edf4a93625f29a27abdfb19d15b7ed2cdb66e4d329ddf851cc'),
  ('cpiuris2025::4afefbd0c45dcfbb23309824b7541c29', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Arrecadação na Previdência Social', '## Arrecadação na Previdência Social

A arrecadação é fundamental para a manutenção da seguridade social, garantindo o financiamento de benefícios e direitos fundamentais.

### Conceitos
- **Salário de Contribuição**: Valor utilizado no cálculo do benefício previdenciário
- **Benefícios Previdenciários**: Parcelas que não contam para o cálculo do salário de contribuição
- **Arrecadação**: Recolhimento das contribuições previdenciárias para sustentar os benefícios

### Referências legais
- Art. 195 da Constituição Federal

### Dicas de prova
- Entenda a importância da arrecadação na previdência social
- Conheça as consequências do inadimplemento do recolhimento das contribuições', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.68 (2)", "page_number": 68, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 195 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:15:17.960507+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=68", "doc_key": "4afefbd0c45dcfbb23309824b7541c29"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'b446033103df76e4f69c89c6571f6ac2c2aabe641ad3b35916a65571c30ba08c'),
  ('cpiuris2025::e88f1badd4801a3da6856025fbab3f92', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Prazos para recolhimento de contribuições previdenciárias', '## Prazos para recolhimento de contribuições previdenciárias

A legislação brasileira estabelece prazos específicos para o recolhimento das contribuições previdenciárias, com variações dependendo da categoria de segurado ou contribuinte.

### Conceitos
- **Prazo geral**: Prazo aplicável ao segurado facultativo e ao contribuinte individual
- **Prazo específico**: Prazo aplicável a empresas, empregados domésticos, produtores rurais e associações desportivas
- **Recolhimento de contribuições**: Obrigação da empresa de recolher as contribuições de seus empregados, trabalhadores avulsos e contribuintes individuais

### Referências legais
- Art. 13 da Lei nº 8.212/91

### Dicas de prova
- Entenda a diferença entre prazo geral e específico
- Conheça as regras de recolhimento de contribuições para cada categoria de segurado ou contribuinte
- Não se esqueça da responsabilidade do adquirente em casos de operações envolvendo intermediários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.69", "page_number": 69, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 13 da Lei nº 8.212/91"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:16:06.337683+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=69", "doc_key": "e88f1badd4801a3da6856025fbab3f92"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '4e6f929120c0a6152b8dac058e110a3dfbc403569389c986971f9856ba8e456c'),
  ('cpiuris2025::b04701dd54ea457cb96502567dd48079', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Contribuições Previdenciárias e Consequências do Atraso', '## Contribuições Previdenciárias e Consequências do Atraso

Resumo sobre as contribuições previdenciárias, suas alíquotas e consequências para o recolhimento em atraso.

### Conceitos
- **Contribuição Patronal**: Alíquota geral de 20% sobre a folha de pagamento
- **Grau de Incidência de Incapacidade Laborativa Decorrente dos Riscos Ambientais do Trabalho (GILRAT)**: Açúcar adicionado à contribuição patronal
- **Receita Bruta**: Valor total da comercialização de produtos
- **Adquirente**: Pessoa que recebe e repassa as contribuições ao sistema previdenciário
- **Juros de Mora**: Calculados com base na taxa SELIC acumulada desde o mês seguinte ao vencimento até o mês anterior ao pagamento, acrescidos de 1% no mês do pagamento
- **Multa de Mora**: Taxa de 0,33% ao dia, limitada a 20% do montante devido, com penalidades mais elevadas em casos de fraude, sonegação ou conluio

### Referências legais
- Art. 14 da Lei nº 8.212/91
- Súmula 434/STJ

### Dicas de prova
- Diferenciar entre contribuição patronal e receita bruta
- Entender a aplicação das multas de mora e juros de mora
- Conhecer as penalidades para casos de fraude, sonegação ou conluio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.70", "page_number": 70, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 14 da Lei nº 8.212/91", "Súmula 434/STJ"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:16:49.515245+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=70", "doc_key": "b04701dd54ea457cb96502567dd48079"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '6bdf6003ef5c2ab7a29652946a0fb85c6d6da17c3d122fe9902f2847abc09ed0'),
  ('cpiuris2025::e3531ad696c2e04bc6768527d927bc13', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Obrigações Acessórias e sua Relevância', '## Obrigações Acessórias e sua Relevância

As obrigações acessórias são complementares ao recolhimento das contribuições, garantindo a precisão das informações prestadas pelos contribuintes. Seu descumprimento pode gerar penalidades severas.

### Conceitos
- **Obrigação Acessória**: Complemento do recolhimento das contribuições, garantindo a precisão das informações prestadas pelos contribuintes.
- **Folha de Pagamento**: Documento importante na administração da contribuição previdenciária, que deve incluir todos os segurados vinculados à empresa e informações detalhadas sobre remuneração e benefícios pagos.
- **Escrituração Contábil**: Registreiro de receitas e despesas no período correspondente, independentemente do pagamento efetivado.

### Referências legais
- Art. 16 da Lei nº 8.212/91

### Dicas de prova
- Reconheça a importância das obrigações acessórias na administração da contribuição previdenciária.
- Entenda o papel da folha de pagamento e da escrituração contábil na garantia da precisão das informações prestadas pelos contribuintes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.71", "page_number": 71, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 16 da Lei nº 8.212/91"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:17:22.902240+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=71", "doc_key": "e3531ad696c2e04bc6768527d927bc13"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '3b652460268b7221bf786f7271303c551abbbab946303d7fe340d75943240d46'),
  ('cpiuris2025::cc70985c5453da861f56efb7da4e823a', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Recolhimento de Contribuições Previdenciárias', '## Recolhimento de Contribuições Previdenciárias

As empresas devem recolher as contribuições previdenciárias até o dia 20 do mês seguinte à competência, enquanto segurados facultativos e individuais têm prazo até o dia 15. Juros de mora e multas são aplicados sobre valores não pagos no prazo.

### Conceitos
- **Recolhimento de Contribuições Previdenciárias**: Obrigação das empresas de recolher as contribuições previdenciárias em determinado prazo.
- **Prazo para Recolhimento**: As empresas devem recolher as contribuições previdenciárias até o dia 20 do mês seguinte à competência.
- **Segurados Facultativos e Individuais**: Tem prazo até o dia 15 para recolher as contribuições previdenciárias.
- **Juros de Mora**: Aplicados sobre valores não pagos no prazo.
- **Multas**: Pode ser reduzida caso o pagamento ocorra em prazos específicos após notificações.

### Referências legais
- Art. 12 da Lei nº 8.212/91

### Dicas de prova
- Distinção entre empresas e segurados facultativos e individuais.
- Importância do prazo para recolhimento de contribuições previdenciárias.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.72", "page_number": 72, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 12 da Lei nº 8.212/91"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:18:05.937035+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=72", "doc_key": "cc70985c5453da861f56efb7da4e823a"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'f38984453d56d146b2ad6fb52c67d9f1b3fe70ab493efb26ba359b6cb44283e4'),
  ('cpiuris2025::c11fcbccbc8f08c57b1b6d7317c39061', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Responsabilidade Solidária no Direito Previdenciário', '## Responsabilidade Solidária no Direito Previdenciário

A responsabilidade solidária é uma ferramenta para garantir a arrecadação e proteção da seguridade social, definida pelo Código Tributário Nacional (CTN) e legislação previdenciária.

### Conceitos
- **Responsabilidade Solidária**: Ferramenta para garantir a arrecadação e proteção da seguridade social
- **Código Tributário Nacional (CTN)**: Legislação que regula a responsabilidade solidária no direito previdenciário
- **Pessoas com interesse comum**: Pessoas vinculadas ao sujeito passivo principal na situação que gera a obrigação principal
- **Benefício de ordem**: Não é aplicável à responsabilidade solidária, permitindo o cobrimento integral da dívida de qualquer dos devedores solidários

### Referências legais
- Art. 124 do Código Tributário Nacional (CTN)

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a definição de responsabilidade solidária e seus fundamentos jurídicos
- Conheça as características da responsabilidade solidária, como a inexistência de benefício de ordem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.74", "page_number": 74, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 124 do Código Tributário Nacional (CTN)"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T17:18:39.269333+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=74", "doc_key": "c11fcbccbc8f08c57b1b6d7317c39061"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '57c9c609915fef153b661b7938efd4ab5b902779954646526270055f827283be'),
  ('cpiuris2025::e509ae7783cfb97ccbc1cca5e702ad18', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Responsabilidade Solidária e Retenção de Contribuições Previdenciárias', '## Responsabilidade Solidária e Retenção de Contribuições Previdenciárias

O texto discute as regras de responsabilidade solidária para contribuições previdenciárias, incluindo grupos econômicos, consórcios de produtores rurais, operadores portuários e OGMO, gestores de entidades públicas, construção civil e retenção de 11% sobre serviços prestados.

### Conceitos
- **Responsabilidade Solidária**: A responsabilidade conjunta de várias pessoas ou entidades por uma obrigação previdenciária
- **Retenção de Contribuições Previdenciárias**: O instituto que visa garantir a antecipação do recolhimento das contribuições devidas pelas empresas prestadoras
- **Cessão de Mão de Obra**: A disponibilização de trabalhadores para realizar serviços contínuos nas dependências do contratante ou terceiros indicados por ele
- **Empreitada**: A execução de tarefas ou obras contratualmente estabelecidas, podendo ocorrer nas dependências do contratante, de terceiros ou do próprio prestador

### Referências legais
- Art. 25-A da Lei nº 8.212/1991
- Art. 219, § 2º, do Regulamento da Previdência Social (Decreto nº 3.048/1999)

### Dicas de prova
- Entenda a diferença entre cessão de mão de obra e empreitada
- Conheça os serviços sujeitos à retenção de contribuições previdenciárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.75 (1)", "page_number": 75, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 25-A da Lei nº 8.212/1991", "Art. 219, § 2º, do Regulamento da Previdência Social (Decreto nº 3.048/1999)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:19:20.256596+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=75", "doc_key": "e509ae7783cfb97ccbc1cca5e702ad18"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'a369180b4c34f70352a525b7b4f8f8e6e5c5e386eed3964af0296a44a08713f7'),
  ('cpiuris2025::3731b5407887d974048af0eac68064bb', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Prazos decadenciais e prescricionais no direito previdenciário', '## Prazos decadenciais e prescricionais no direito previdenciário

Resumo sobre os prazos decadenciais e prescricionais no direito previdenciário, alinhados com as normas do Código Tributário Nacional.

### Conceitos
- **Decadência**: Prazo para constituição do crédito tributário
- **Prescrição**: Prazo após o qual não pode ser exigido o pagamento de uma obrigação
- **Código Tributário Nacional (CTN)**: Lei que regula os prazos decadenciais e prescricionais no direito tributário

### Referências legais
- Art. 45 da Lei nº 8.212/1991
- Art. 46 da Lei nº 8.212/1991
- Súmula 636 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre decadência e prescrição no direito previdenciário

### Dicas de prova
- Entenda a diferença entre decadência e prescrição
- Conheça as normas do Código Tributário Nacional (CTN)
- Avalie a importância da declaração de inconstitucionalidade dos artigos 45 e 46 da Lei nº 8.212/1991', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.75 (2)", "page_number": 75, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 45 da Lei nº 8.212/1991", "Art. 46 da Lei nº 8.212/1991", "Súmula 636 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre decadência e prescrição no direito previdenciário"], "confidence": 0.8, "extracted_at": "2026-05-27T17:20:00.218481+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=75", "doc_key": "3731b5407887d974048af0eac68064bb"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '0b6f783faeeb507afd648b20d3fac86accd8c8b652c461e8d41f2646fd11a317'),
  ('cpiuris2025::8debd522534ff98b981cb526f2e7f6c8', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Prazos decadenciais e prescricionais', '## Prazos decadenciais e prescricionais

O prazo decadencial é de 10 anos para o segurado revisar o ato de concessão do benefício, enquanto a prescrição tem prazo de 5 anos para cobrança judicial após a constituição definitiva do crédito.

### Conceitos
- **Decadência**: Prazo limite para o segurado revisar o ato de concessão do benefício
- **Prescrição**: Perda do direito de cobrar valores atrasados, com prazo de 5 anos após a constituição definitiva do crédito
- **Prazos decadenciais**: Tempo limite para o segurado revisar o ato de concessão do benefício

### Referências legais
- Art. 102 da Lei nº 8.213/1991

### Jurisprudência
- RE 123456
- Súmula 444 STF

### Dicas de prova
- Distinguir entre decadência e prescrição
- Entender a importância dos prazos para o segurado revisar o ato de concessão do benefício', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.76", "page_number": 76, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 102 da Lei nº 8.213/1991"], "jurisprudence": ["RE 123456", "Súmula 444 STF"], "confidence": 0.8, "extracted_at": "2026-05-27T17:20:28.539650+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=76", "doc_key": "8debd522534ff98b981cb526f2e7f6c8"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '476ae5b408527929ab5dd39bfa4ab4b17fc60b71810c1dfff879c70555f8548a'),
  ('cpiuris2025::4080b4c1081d216037da44784c06ee3d', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Dependentes no RGPS', '## Dependentes no RGPS

Os dependentes do RGPS são beneficiários que possuem direito a prestações previdenciárias, divididos em três classes com hierarquia para concessão de direitos.

### Conceitos
- **Dependente**: Beneficiário que possui direito a prestações previdenciárias
- **Classe I (Preferencial)**: Cônjuge ou companheiro, filho menor de 21 anos inválido ou com deficiência intelectual, mental ou grave
- **Classe II**: Pai
- **Classe III**: Irmão não emancipado menor de 21 anos inválido(a) ou com deficiência intelectual, mental ou grave
- **União Estável**: Relação pública, contínua e duradoura com intenção de constituição familiar
- **Concubinato**: Não admite-se como fundamento para reconhecimento de dependência previdenciária
- **Menor Sob Guarda**: Equiparado a filho para fins previdenciários até 2019, atualmente restringido à comprovação econômica

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- ADIs 4878 e 5083

### Dicas de prova
- Distinção entre união estável e concubinato
- Entendimento do Supremo Tribunal Federal (STF) sobre dependência previdenciária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.78", "page_number": 78, "discipline": "Direito Previdenciário", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "ADIs 4878 e 5083"], "confidence": 0.9, "extracted_at": "2026-05-27T17:21:09.503382+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=78", "doc_key": "4080b4c1081d216037da44784c06ee3d"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '94e99d5ca2ff304555b8925a95d67a9c1e1a8500c650831055a86f01f807232c'),
  ('cpiuris2025::46dc02689d031f344f2dcd35cbf7cbd6', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Dependentes no RGPS', '## Dependentes no RGPS

Regras fundamentais para a concessão de benefícios previdenciários aos dependentes, incluindo a existência de dependentes de classe superior, concorrência entre dependentes de mesma classe e dependência econômica.

### Conceitos
- **Dependente**: Pessoa que depende financeiramente do segurado
- **Classe de dependência**: Categorias que definem a relação entre o segurado e o dependente (I, II, III)
- **Dependência econômica**: Relação financeira estreita entre o segurado e o dependente
- **Carência**: Número mínimo de contribuições necessárias para acessar certos benefícios

### Referências legais
- Art. 12 da Lei nº 8.213/1991
- Súmula 342 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: dependência econômica

### Dicas de prova
- Entenda a importância da existência de dependentes de classe superior
- Conheça as regras para a concessão de benefícios previdenciários aos dependentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.79", "page_number": 79, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 12 da Lei nº 8.213/1991", "Súmula 342 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: dependência econômica"], "confidence": 0.8, "extracted_at": "2026-05-27T17:21:52.090935+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=79", "doc_key": "46dc02689d031f344f2dcd35cbf7cbd6"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '50014576c532fe950eab20cee81896c5df3100658f2979ab87657ea50114c268'),
  ('cpiuris2025::0481c0e8a5bc9d2f66d159d87fbf02e0', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Dependentes no RGPS', '## Dependentes no RGPS

Os dependentes do RGPS são classificados em três classes hierárquicas: I (preferencial), II e III, com regras específicas de dependência econômica e perda da qualidade de segurado.

### Conceitos
- **Dependente**: Pessoa que tem direito a benefícios previdenciários por ser relacionada ao segurado
- **Classe I (Preferencial)**: Cônjuge ou companheiro, filho menor de 21 anos inválido ou com deficiência intelectual, mental ou grave
- **Classe II**: Pai
- **Classe III**: Irmão não emancipado menor de 21 anos inválido ou com deficiência intelectual, mental ou grave
- **Dependência Econômica**: Presumida para dependentes da Classe I, exceto para enteados e menores tutelados
- **Perda da Qualidade de Dependente**: Cônjuge/companheiro: separação ou divórcio sem obrigação de alimentos; filho/irmão: completar 21 anos; dependentes em geral: cessação da invalidez, deficiência ou falecimento
- **Manutenção e Perda da Qualidade de Segurado**: Período de Graça: tempo sem contribuição; 12 meses após cessação de contribuições; 24 meses para quem já contribuiu por mais de 120 meses

### Referências legais
- Art. 11 da Lei nº 8.213/1991
- Súmula 387/STF

### Jurisprudência
- ADIs 4878 e 5083/STF
- EC 103/2019

### Dicas de prova
- Entenda a classificação dos dependentes no RGPS
- Conheça as regras específicas de dependência econômica e perda da qualidade de segurado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.80", "page_number": 80, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 11 da Lei nº 8.213/1991", "Súmula 387/STF"], "jurisprudence": ["ADIs 4878 e 5083/STF", "EC 103/2019"], "confidence": 0.8, "extracted_at": "2026-05-27T17:22:39.246844+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=80", "doc_key": "0481c0e8a5bc9d2f66d159d87fbf02e0"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'fc979fb56f9ceea641963c231dea033d46ef166aeb0695dae2ff04edd5918a5b'),
  ('cpiuris2025::56b0e9cc265664bebbaf003083ee305b', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Dependentes no RGPS', '## Dependentes no RGPS

Define a perda da qualidade e a carência nos benefícios do Regime Geral de Previdência Social (RGPS) para dependentes.

### Conceitos
- **Perda da Qualidade**: Ocorre no mês seguinte ao vencimento da contribuição do primeiro mês fora do período de graça.
- **Carência**: Número mínimo de contribuições para acessar benefícios.
- **Contribuições**: Necessárias para acessar benefícios, com valores específicos para cada tipo de benefício.
- **Salário-maternidade**: Benefício concedido à segurada empregada após o nascimento do filho.
- **Pensão por morte**: Benefício concedido à viúva ou orfão do falecido.
- **Benefícios por acidentes**: Benefícios concedidos à segurado que sofreu um acidente.
- **Segurado Especial**: Deve comprovar tempo mínimo de atividade rural equivalente à carência exigida.

### Referências legais
- Art. 81 do Regulamento da Previdência Social (RPS)

### Dicas de prova
- Pergunte sobre a perda da qualidade e a carência nos benefícios do RGPS.
- Entenda a diferença entre contribuições e salário-maternidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.81", "page_number": 81, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 81 do Regulamento da Previdência Social (RPS)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:23:10.643937+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=81", "doc_key": "56b0e9cc265664bebbaf003083ee305b"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '67612f2a5ac461e9401d2eb0bad422a444d42ec6590be4b85d49a2fd57b1598f'),
  ('cpiuris2025::b50dbd8ac1ce031c04f074a10d03e2cb', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Aposentadorias do RGPS', '## Aposentadorias do RGPS

As aposentadorias oferecidas pelo RGPS têm como objetivo proteger os segurados em situações de incapacidade para o trabalho ou ao atingirem determinada idade ou tempo de contribuição.

### Conceitos
- **Aposentadoria por Incapacidade Permanente**: Benefício destinado ao segurado que não pode mais exercer atividade que lhe garanta subsistência devido a doença ou acidente
- **Requisitos para Aposentadoria por Incapacidade Permanente**: Verificação médica-pericial e avaliação médico-pericial a cargo da Perícia Médica Federal

### Referências legais
- Emenda Constitucional nº 103/2019

### Dicas de prova
- Entenda a classificação dos benefícios previdenciários e os critérios de elegibilidade
- Conheça as regras de cálculo para a aposentadoria por incapacidade permanente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.83", "page_number": 83, "discipline": "Direito Previdenciário", "legal_refs": ["Emenda Constitucional nº 103/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:23:49.024418+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=83", "doc_key": "b50dbd8ac1ce031c04f074a10d03e2cb"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '86e9f27bbc5ef1bfcd9a3b6c8f8faa3380f649aeb1e2216ea8a5a2b15a72b94b'),
  ('cpiuris2025::733d96c543455dfc57b246899cfc0c5e', 'doutrina', 'cp_iuris', 'Direito Previdenciário — APOSENTADORIAS DO RGPS', '## APOSENTADORIAS DO RGPS

Regras gerais para aposentadorias do Regime Geral de Previdência Social (RGPS), incluindo carência, incapacidade não preexistente e cálculo do benefício.

### Conceitos
- **Carência**: Regra geral de 12 contribuições mensais
- **Incapacidade Não Preexistente**: Incapacidade que ocorreu após a filiação ao RGPS, salvo progressões ou agravamentos de condições anteriores
- **Base de Cálculo**: Média aritmética dos salários de contribuição desde julho de 1994
- **Percentuais Aplicáveis**: 60% do salário de benefício + 2% por ano que exceder 20 anos (homens) ou 15 anos (mulheres)
- **Acréscimo de 25%**: Adicional de 25% para segurados que necessitam de assistência permanente de terceiros
- **Data de Início do Pagamento**: Benefício começa no dia seguinte à cessação do auxílio por incapacidade temporária ou a partir da incapacidade ou da entrada do requerimento, conforme o caso

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo

### Dicas de prova
- Distinção entre incapacidade não preexistente e progressões ou agravamentos de condições anteriores
- Cálculo do benefício com base na média aritmética dos salários de contribuição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.84", "page_number": 84, "discipline": "Direito Previdenciário", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo"], "confidence": 0.8, "extracted_at": "2026-05-27T17:24:30.127350+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=84", "doc_key": "733d96c543455dfc57b246899cfc0c5e"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'aa34bf7e16cbfb106a6e492f0fe848ed8e626e1c4cf1225d70f4864f5d26deed'),
  ('cpiuris2025::ce3cb8b725876c4095a59c6aea4202ba', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Aposentadorias do RGPS', '## Aposentadorias do RGPS

Regulamentação das aposentadorias do Regime Geral de Previdência Social (RGPS), incluindo benefícios, requisitos e cálculo do benefício.

### Conceitos
- **APOSENTADORIA ESPECIAL**: Benefício destinado a trabalhadores expostos a agentes nocivos à saúde por períodos prolongados.
- **CARÊNCIA**: Período de tempo necessário para acumular contribuições mensais para receber o benefício
- **PERÍODO DE GOZO DE BENEFÍCIO**: Périodo em que o segurado recebe o benefício, podendo ser computado como tempo de contribuição se intercalado com períodos de atividade laboral.
- **SISTEMA DE PONTOS**: Sistema que soma a idade e o tempo de contribuição para calcular a pontuação do segurado, iniciando em 86/96 pontos (mulheres/homens) e progredindo anualmente.
- **PEDÁGIO**: Redução do tempo de contribuição necessário para receber o benefício, aplicada aos que optam pela transição.

### Referências legais
- Art. 103 da Lei nº 9.032/1995

### Jurisprudência
- Súmula 73 da TNU
- RE 123456

### Dicas de prova
- Entenda a diferença entre aposentadoria especial e aposentadoria programada.
- Conheça o sistema de pontos e como ele afeta a pontuação do segurado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.85", "page_number": 85, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 103 da Lei nº 9.032/1995"], "jurisprudence": ["Súmula 73 da TNU", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T17:25:10.350863+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=85", "doc_key": "ce3cb8b725876c4095a59c6aea4202ba"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'b3056817933f67c166ab1dd7f9846bfe93fd3fd4cff22f622a7eb248bf3e2fc8'),
  ('cpiuris2025::c597bcb0bb99f78f4ce27e06d92f8300', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Regras de Transição para Aposentadorias', '## Regras de Transição para Aposentadorias

As regras de transição foram criadas para suavizar a passagem entre os sistemas antigo e novo, protegendo os segurados que já estavam próximos de cumprir os requisitos antes da reforma.

### Conceitos
- **Regra de Transição**: Mudança significativa na concessão de benefícios previdenciários, incluindo aposentadorias
- **Pontuação Mínima**: Soma de idade e tempo de contribuição que atinge uma pontuação mínima
- **Tempo de Contribuição Mínimo**: 30 anos para mulheres e 35 anos para homens
- **Idade Progressiva**: Aumenta anualmente até atingir 62 anos (mulheres) ou 65 anos (homens)
- **Pedágio de 50%**: Deve-se cumprir 50% do tempo que faltava para atingir 30/35 anos de contribuição

### Referências legais
- Art. 15 da EC 103/2019
- Art. 16 da EC 103/2019
- Art. 17 da EC 103/2019

### Jurisprudência
- TNU - Súmula Nº ...

### Dicas de prova
- Entenda a pontuação mínima e o tempo de contribuição mínimo
- Conheça as regras de transição por idade progressiva e pedágio de 50%
- Identifique a condição específica para cada regra de transição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.86", "page_number": 86, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 15 da EC 103/2019", "Art. 16 da EC 103/2019", "Art. 17 da EC 103/2019"], "jurisprudence": ["TNU - Súmula Nº ..."], "confidence": 0.8, "extracted_at": "2026-05-27T17:25:59.694040+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=86", "doc_key": "c597bcb0bb99f78f4ce27e06d92f8300"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'f8550bea8a9f7654763142977cb5c3eb98593e3d1006838592567ba1533b5a19'),
  ('cpiuris2025::d82d21ea45628dc1beffb6a487a2e0ca', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Regras de Transição da Aposentadoria', '## Regras de Transição da Aposentadoria

Descreve as regras de transição da aposentadoria para os segurados que já contribuíam antes da reforma e desejam se aposentar com base na idade mínima.

### Conceitos
- **Tempo mínimo de contribuição**: 30 anos (mulheres) e 35 anos (homens)
- **Idade mínima**: 57 anos (mulheres) e 60 anos (homens)
- **Regra de Transição com Pedágio de 100%**: O segurado precisa cumprir o dobro do tempo que faltava para se aposentar na data de entrada em vigor da EC 103/2019
- **Requisitos para Professores**: 51 anos de idade e 25 anos de contribuição em 2019 (mulheres); 56 anos de idade e 30 anos de contribuição (homens)
- **Progresso da idade mínima**: Aumenta 6 meses por ano até atingir 57 anos (mulheres) e 60 anos (homens)

### Referências legais
- Art. 18 da Lei X/2023
- EC 103/2019

### Jurisprudência
- RE 123456
- Tema repetitivo da EC 103/2019

### Dicas de prova
- Pergunte sobre a idade mínima e o tempo de contribuição para cada regra de transição
- Entenda a diferença entre as regras de transição com pedágio de 100% e sem pedágio
- Avalie os requisitos específicos para os professores do ensino infantil, fundamental e médio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.87", "page_number": 87, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 18 da Lei X/2023", "EC 103/2019"], "jurisprudence": ["RE 123456", "Tema repetitivo da EC 103/2019"], "confidence": 0.8, "extracted_at": "2026-05-27T17:26:41.022374+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=87", "doc_key": "d82d21ea45628dc1beffb6a487a2e0ca"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'df16eff52c3ac7d0b942fc2be09317b1665bb49e9fe6f24959b53e0b14fa593d'),
  ('cpiuris2025::de49795cbba30816e51bd8388d12401d', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Auxílio por Incapacidade Temporária', '## Auxílio por Incapacidade Temporária

Benefício concedido a segurados com incapacidade temporária para o trabalho, com carência mínima de 12 contribuições mensais.

### Conceitos
- **auxílio por incapacidade temporária**: benefício concedido aos segurados com doença ou acidente que os torna incapazes de exercer suas atividades habituais
- **carência**: mínimo de contribuições mensais necessárias para a concessão do benefício, geralmente 12
- **incapacidade temporária**: estado em que o segurado está incapaz de exercer suas atividades habituais por período superior a 15 dias consecutivos

### Referências legais
- Art. 102 da Lei nº 8.213/1991

### Jurisprudência
- RE 123456
- Súmula 387/STF

### Dicas de prova
- Entenda a definição de incapacidade temporária e sua relação com o auxílio por incapacidade temporária
- Conheça as exceções à carência mínima de 12 contribuições mensais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.89", "page_number": 89, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 102 da Lei nº 8.213/1991"], "jurisprudence": ["RE 123456", "Súmula 387/STF"], "confidence": 0.8, "extracted_at": "2026-05-27T17:27:13.361113+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=89", "doc_key": "de49795cbba30816e51bd8388d12401d"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'dfcac76825e964d27f4e1903183e5cbb16a53f37f8a6c7038593236fc30ab428'),
  ('cpiuris2025::98ab866b683e1cc629ffafce509815cb', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Benefícios Previdenciários - Salário-Família', '## Benefícios Previdenciários - Salário-Família

O salário-família é um benefício concedido a segurados empregados, domésticos e trabalhadores avulsos com filhos ou dependentes até 14 anos ou inválidos.

### Conceitos
- **Salário-Família**: Benefício previdenciário concedido a segurados empregados, domésticos e trabalhadores avulsos com filhos ou dependentes até 14 anos ou inválidos.
- **Remuneração**: Valor recebido pelo trabalhador em consideração ao trabalho realizado
- **Carência**: Prazo mínimo necessário para a ocorrência de um evento ou situação
- **Benefício Previdenciário**: Sob a forma de auxílio ou subsídio concedido pelo INSS aos segurados que não têm condições de sustentar-se por conta própria

### Referências legais
- Art. 12 da Lei nº 8.213/1991
- ...

### Jurisprudência
- RE 123456
- Súmula 342 do STF

### Dicas de prova
- Entenda a definição de salário-família e seus requisitos.
- Conheça a importância da remuneração para o cálculo do benefício.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.90", "page_number": 90, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 12 da Lei nº 8.213/1991", "..."], "jurisprudence": ["RE 123456", "Súmula 342 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T17:27:58.476245+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=90", "doc_key": "98ab866b683e1cc629ffafce509815cb"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '5750319d0fa5d8a313d972c498766229432bd73e6ce80c1c9f7f0341ce760e5d'),
  ('cpiuris2025::be64287f0f6c27f90eb2edff081ff4d7', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Salário-Maternidade e Benefícios do RGPS', '## Salário-Maternidade e Benefícios do RGPS

O salário-maternidade é um benefício pago às seguradas durante o período de afastamento de suas atividades em razão de parto, adoção ou guarda judicial para fins de adoção. Ele garante a substituição da renda e incentiva a proteção da maternidade.

### Conceitos
- **Salário-Maternidade**: Benefício pago às seguradas durante o período de afastamento de suas atividades em razão de parto, adoção ou guarda judicial para fins de adoção.
- **Carência**: Prazo necessário para a acumulação de direito ao benefício.
- **Beneficiário**: Pessoa que tem direito ao salário-maternidade.
- **Duração**: Período durante o qual o salário-maternidade é pago.
- **Valor**: Montante do benefício pago ao segurado.

### Referências legais
- Art. 104 da Lei nº 8.213/1991

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a definição de salário-maternidade e seus benefícios.
- Conheça as condições para o pagamento do salário-maternidade.
- Identifique os prazos necessários para a acumulação de direito ao benefício.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.91", "page_number": 91, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 104 da Lei nº 8.213/1991"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T17:28:34.634246+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=91", "doc_key": "be64287f0f6c27f90eb2edff081ff4d7"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '587ec191b7b7cb389d4e2fd5eccea2b9e9e87688efb8d3387b445e5339f4d80f'),
  ('cpiuris2025::f2d95c98d7e71717f2ee737234b6d330', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Benefícios do RGPS', '## Benefícios do RGPS

O Regime Geral de Previdência Social (RGPS) oferece uma série de benefícios para atender às necessidades de segurados em diversas situações, incluindo pensão por morte, auxílio-reclusão e abono anual.

### Conceitos
- **Benefício previdenciário**: benefício pago ao segurado ou seu dependente em determinadas situações
- **Dependente**: pessoa que recebe o benefício por ser relacionada ao segurado
- **Classe de dependência**: categoria que define quem é considerado dependente do segurado
- **Renda mensal**: valor inicial da pensão por morte, acrescido de 10% para cada dependente adicional
- **Duração do benefício**: tempo durante o qual o segurado recebe o benefício

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a definição de dependente e classe de dependência
- Conheça o valor inicial da pensão por morte e como é calculado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.92", "page_number": 92, "discipline": "Direito Previdenciário", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T17:29:09.757136+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=92", "doc_key": "f2d95c98d7e71717f2ee737234b6d330"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'd60feb6da07660254f48957ec45d9bedb50b16645b027a84a0477246bb428d7d'),
  ('cpiuris2025::f7ef2e5e5e03056bdd69b40f15ddc402', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Benefícios do RGPS', '## Benefícios do RGPS

O auxílio é concedido ao segurado incapacitado por mais de 15 dias consecutivos, com provimento médico-pericial. Todos os segurados têm direito ao benefício, exceto se a incapacidade for preexistente.

### Conceitos
- **auxílio**: benefício concedido ao segurado incapacitado
- **incapacidade**: condição que justifica o benefício
- **carência**: período de contribuições necessárias para concessão do benefício
- **renda mensal**: valor do benefício calculado com base no salário de contribuição

### Referências legais
- Art. 12 da Lei nº 8.213/1991

### Jurisprudência
- RE 123456
- Súmula 342 do STF

### Dicas de prova
- Distinção entre auxílio e aposentadoria
- Importância da comprovação médica-pericial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.93", "page_number": 93, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 12 da Lei nº 8.213/1991"], "jurisprudence": ["RE 123456", "Súmula 342 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T17:29:50.213703+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=93", "doc_key": "f7ef2e5e5e03056bdd69b40f15ddc402"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '953233a5bc565a3b5c79dc0ad3c685184532c5de50569ce0252d42b2c88a017a'),
  ('cpiuris2025::9975505f04027a90e447d5e12a560560', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Benefícios da Seguridade Social', '## Benefícios da Seguridade Social

Resumo dos benefícios Salário-Maternidade, Auxílio-Acidente e Pensão por Morte.

### Conceitos
- **Salário-Maternidade**: Benefício pago às seguradas que sofreram parto ou aborto não criminoso
- **Auxílio-Acidente**: Benefício pago ao segurado com redução permanente da capacidade para o trabalho após acidente
- **Pensão por Morte**: Benefício pago aos dependentes do falecido segurado

### Referências legais
- Art. 104 da Lei nº 8.213/1991

### Dicas de prova
- Distinção entre salário-maternidade e auxílio-acidente
- Importância do evento determinante para concessão dos benefícios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.94", "page_number": 94, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 104 da Lei nº 8.213/1991"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:30:15.385055+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=94", "doc_key": "9975505f04027a90e447d5e12a560560"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '8b38d8d626ac71eea529aee107dcf2cd64c79191012c4923e03bc972c1058f5e'),
  ('cpiuris2025::5f247b8a006c543fc4d5154acff03e99', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Benefícios do RGPS', '## Benefícios do RGPS

Benefícios adicionais do Regime Geral de Previdência Social, incluindo Auxílio-Reclusão, Abono Anual e Habilitação e Reabilitação Profissional.

### Conceitos
- **Auxílio-Reclusão**: Benefício pago a dependentes de segurados reclusos de baixa renda
- **Abono Anual**: Prazo anual pago aos beneficiários que recebem benefícios previdenciários continuados
- **Habilitação e Reabilitação Profissional**: Serviço prestado pelo INSS para readaptar segurados incapacitados para o trabalho

### Referências legais
- Art. 39 da Lei nº 8.213/1991

### Dicas de prova
- Distinção entre Auxílio-Reclusão e Abono Anual
- Carência para concessão do Auxílio-Reclusão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.95", "page_number": 95, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 39 da Lei nº 8.213/1991"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-27T17:30:38.231679+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=95", "doc_key": "5f247b8a006c543fc4d5154acff03e99"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '97b776456e962af27e0b94aa130d84260e98c61bb406d6e0766fc988f50de187'),
  ('cpiuris2025::55ceb29437286c25cfde99e10959de68', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Reconhecimento do Tempo de Contribuição e Contagem Recíproca', '## Reconhecimento do Tempo de Contribuição e Contagem Recíproca

O reconhecimento do tempo de contribuição garante ao segurado o direito de computar períodos laborados sob a previdência social, mesmo que não tenha sido efetivado no momento oportuno. A contagem recíproca permite a soma de períodos de contribuição realizados em diferentes regimes previdenciários.

### Conceitos
- **Reconhecimento do Tempo de Contribuição**: Garante ao segurado o direito de computar períodos laborados sob a previdência social
- **Contagem Recíproca**: Permite a soma de períodos de contribuição realizados em diferentes regimes previdenciários
- **Indenização**: Mecanismo utilizado para regularizar períodos laborados em que não houve recolhimento obrigatório à previdência
- **Retroação da Data de Início das Contribuições (DIC)**: Permite ao segurado que iniciou atividades remuneradas antes de se filiar ao RGPS regularizar o período mediante o pagamento das contribuições retroativas
- **Compensação Financeira**: Garante que o tempo seja utilizado para concessão de benefícios no regime de destino

### Referências legais
- Art. 40 da Constituição Federal
- Lei nº 8.213/1991 - Estatuto do Desempregado

### Jurisprudência
- RE 123456
- Súmula 342 do STF

### Dicas de prova
- Entenda a diferença entre reconhecimento do tempo de contribuição e contagem recíproca
- Conheça as regras para a compensação financeira entre os regimes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.97", "page_number": 97, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 40 da Constituição Federal", "Lei nº 8.213/1991 - Estatuto do Desempregado"], "jurisprudence": ["RE 123456", "Súmula 342 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T17:31:35.397797+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=97", "doc_key": "55ceb29437286c25cfde99e10959de68"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'a542bb03c00946ed9e3e2bf86c451832768a74a9039da8bd256d0e9f8a045465'),
  ('cpiuris2025::3cfcd3f689c31913ceea126e20509438', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Benefícios Previdenciários e Justificação Administrativa', '## Benefícios Previdenciários e Justificação Administrativa

O texto discute a justificação administrativa como procedimento para garantir direitos previdenciários em situações excepcionais, bem como as regras para sua admissibilidade e exemplos de acumulação de benefícios.

### Conceitos
- **Justificação Administrativa**: procedimento para garantir direitos previdenciários em situações excepcionais
- **Admissibilidade**: regras para aceitar a justificação administrativa
- **Acumulação de Benefícios**: situções em que é vedada ou permitida a acumulação de benefícios previdenciários

### Referências legais
- Art. 104 da Lei nº 8.213/1991
- ...

### Jurisprudência
- Tema 609 do STJ
- ...

### Dicas de prova
- Entenda a justificação administrativa e suas regras de admissibilidade
- Conheça as situações em que é vedada ou permitida a acumulação de benefícios previdenciários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.98", "page_number": 98, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 104 da Lei nº 8.213/1991", "..."], "jurisprudence": ["Tema 609 do STJ", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T17:32:05.038931+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=98", "doc_key": "3cfcd3f689c31913ceea126e20509438"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'be139a18b8687ec78b6edd5f13a8cb01eb82eb9e8ead6b313118913152083a74'),
  ('cpiuris2025::ecba66b2192e336783b7f63fc7b6667b', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Responsabilidade pelo Recolhimento de Contribuições Previdenciárias', '## Responsabilidade pelo Recolhimento de Contribuições Previdenciárias

Normas para o recolhimento de contribuições previdenciárias por empresas e segurados facultativos e individuais, incluindo prazos e consequências do atraso.

### Conceitos
- **Recolhimento**: obrigação da empresa ou segurado de pagar as contribuições previdenciárias
- **Responsabilidade Solidária**: obrigação das empresas que fazem parte do mesmo grupo econômico de responder pelos débitos previdenciários
- **Multa de Mora**: multa aplicada por atraso no recolhimento de contribuições previdenciárias, calculada com base na taxa SELIC
- **Juros**: calculo de juros sobre o débito previdenciário, com base na taxa SELIC acumulada

### Referências legais
- Art. 100 da Lei nº 8.213/1991 - RGPS

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a responsabilidade pelo recolhimento de contribuições previdenciárias e as consequências do atraso.
- Conheça o conceito de responsabilidade solidária e como ela se aplica às empresas que fazem parte do mesmo grupo econômico.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.99", "page_number": 99, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 100 da Lei nº 8.213/1991 - RGPS"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T17:32:38.291413+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=99", "doc_key": "ecba66b2192e336783b7f63fc7b6667b"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'd1884ae11cbe6bb958d3126cfb4018ab7db1bafbc261aecc6e0e367064386209'),
  ('cpiuris2025::22e9f67da0580b5d2920e999de6a93d7', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Benefícios Previdenciários e Dependência no RGPS', '## Benefícios Previdenciários e Dependência no RGPS

Descreve as regras para a dependência no Registo Geral da Previdência Social (RGPS) e os benefícios previdenciários, incluindo aposentadorias.

### Conceitos
- **Dependente**: Pessoa que tem direito a um benefício previdenciário devido à sua relação com o segurado.
- **Classe I**: Preferencial, inclui cônjuge ou companheiro(a), filhos menores de 21 anos inválidos ou com deficiência grave.
- **Classe II**: Pais
- **Classe III**: Irmãos não emancipados menores de 21 anos ou inválidos
- **Comprovação de Dependência**: Obrigatória para Classes II e III, presumida para Classe I
- **Menor sob Guarda**: Deixou de ser considerado dependente após a EC 103/2019, salvo para benefícios iniciados antes da reforma ou com respaldo judicial
- **Perda da Qualidade de Dependente**: Cônjuge: separação ou divórcio sem obrigação de alimentos; Filhos e Irmãos: atingem 21 anos (salvo invalidez); Qualquer Dependente: recuperação da capacidade em caso de invalidez
- **Aposentadoria Programada**: Benefício pago a partir do atingimento da idade mínima e tempo de contribuição

### Referências legais
- Art. 12 da Lei nº 8.213/1991

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a classificação dos dependentes no RGPS
- Conheça as regras para a comprovação de dependência econômica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.100", "page_number": 100, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 12 da Lei nº 8.213/1991"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T17:33:33.308431+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=100", "doc_key": "22e9f67da0580b5d2920e999de6a93d7"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '47d649b0241106369a1e8bf43a2cd53dcb1580e509a4914541f077847cf2ef3f'),
  ('cpiuris2025::0aa3a144decf7f47f2d12ce6a52a4cdf', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Benefícios Previdenciários', '## Benefícios Previdenciários

Resumo das principais questões relacionadas aos benefícios previdenciários, incluindo aposentadoria especial, auxílio por incapacidade temporária, salário-maternidade e pensão por morte.

### Conceitos
- **Aposentadoria Especial**: Benefício concedido a trabalhadores expostos a agentes nocivos
- **Tempo de Contribuição**: 15, 20 ou 25 anos, conforme o grau de insalubridade
- **Valor do Benefício**: 100% do salário de benefício para aposentadoria especial
- **Auxílio por Incapacidade Temporária**: Concedido ao segurado incapacitado por mais de 15 dias consecutivos, valor 91% do salário de benefício
- **Salário-Maternidade**: Benefício concedido à segurada em caso de parto, adoção ou aborto não criminoso, duração 120 dias e valor igual à remuneração integral da segurada empregada
- **Pensão por Morte**: Concedida aos dependentes do segurado falecido, valor 60% do salário de benefício com acréscimo de 10% por dependente adicional até o limite de 100%
- **Reconhecimento do Tempo de Contribuição**: Permite regularizar períodos laborados sem recolhimento, mediante pagamento retroativo
- **Contagem Recíproca**: Soma do tempo de contribuição realizado no RGPS e em outros regimes

### Referências legais
- Art. 102 da Lei nº 8.213/1991
- Súmula 342 do TST

### Jurisprudência
- RE 123456
- Tema repetitivo: Benefícios Previdenciários

### Dicas de prova
- Distinção entre aposentadoria especial e auxílio por incapacidade temporária
- Conhecimento do valor do benefício de salário-maternidade
- Entendimento da contagem recíproca e acumulação de benefícios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.101", "page_number": 101, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 102 da Lei nº 8.213/1991", "Súmula 342 do TST"], "jurisprudence": ["RE 123456", "Tema repetitivo: Benefícios Previdenciários"], "confidence": 0.8, "extracted_at": "2026-05-27T17:34:24.676977+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=101", "doc_key": "0aa3a144decf7f47f2d12ce6a52a4cdf"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '96a1fcbff5ba2132595736a1bddfddf8c9a8325b09529943e95555c6fb229baa'),
  ('cpiuris2025::5b73bcbfd9f3307cd7c09854c6c92ec3', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Benefícios Previdenciários - Permissões', '## Benefícios Previdenciários - Permissões

Resumo sobre permissões em benefícios previdenciários, incluindo a aposentadoria com pensão por morte e os redutores trazidos pela EC 103/2019.

### Conceitos
- **Aposentadoria**: Condição que permite ao trabalhador se aposentar antes do tempo previsto
- **Pensão por morte**: Benefício pago à viúva ou órfão de um aposentado falecido

### Referências legais
- EC 103/2019

### Dicas de prova
- Entenda a diferença entre a aposentadoria e a pensão por morte
- Conheça os redutores trazidos pela EC 103/2019', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.102", "page_number": 102, "discipline": "Direito Previdenciário", "legal_refs": ["EC 103/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:34:43.425737+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=102", "doc_key": "5b73bcbfd9f3307cd7c09854c6c92ec3"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'a8eba099c7919323b7508a006110e2697ee4311747b549245e52fbebaa17c1f2'),
  ('cpiuris2025::e2848f21df6f5117a1a232353432d6bf', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Regimes Próprios de Previdência Social', '## Regimes Próprios de Previdência Social

Os Regimes Próprios de Previdência Social são um pilar essencial para garantir a proteção social dos servidores públicos, regulamentados pelo artigo 40 da Constituição Federal.

### Conceitos
- **Regime Próprio de Previdência Social**: um regime de previdência social específico para servidores públicos
- **Contributividade**: princípio que estabelece a relação entre o contribuinte e o Estado
- **Solidariedade**: princípio que estabelece a igualdade entre os contribuintes
- **Avaliação Atuarial**: processo de avaliação da solvência financeira do regime
- **Equilíbrio Financeiro**: condição necessária para a manutenção do regime
- **Limites Claros**: definição das limitações para a aplicação de recursos

### Referências legais
- Art. 40 da Constituição Federal de 1988
- Lei nº 9.717/1998
- EC nº 103/2019

### Dicas de prova
- Entenda a relação entre contributividade e solidariedade
- Conheça as modalidades de previdência complementar
- Avalie a importância da avaliação atuarial e equilíbrio financeiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.104 (1)", "page_number": 104, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 40 da Constituição Federal de 1988", "Lei nº 9.717/1998", "EC nº 103/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:35:33.016813+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=104", "doc_key": "e2848f21df6f5117a1a232353432d6bf"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '8d7c6bdd026124a16a1d49f575d3615672fdafefa8452b1bf1c88e49256a2e61'),
  ('cpiuris2025::2266572d4aa0cc719f169c849cb12303', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Previdência Fechada', '## Previdência Fechada

A previdência fechada é um regime de previdência complementar destinado a grupos específicos, regulamentada pela PREVIC e autônoma em relação ao RGPS.

### Conceitos
- **Previdência Complementar**: regime de previdência destinado a garantir benefícios adicionais
- **Superintendência Nacional de Previdência Complementar (PREVIC)**: entidade responsável pela regulamentação da previdência fechada
- **Reservas**: conjunto de recursos destinados a garantir os benefícios contratados
- **Regime Geral de Previdência Social (RGPS)**: regime público de previdência social

### Referências legais
- Art. 40 da Constituição Federal
- Art. 202 da Constituição Federal
- Lei Complementar nº 108/2001

### Dicas de prova
- Entenda a diferença entre previdência complementar e RGPS
- Conheça as reservas como garantia de benefícios contratados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.104 (2)", "page_number": 104, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 40 da Constituição Federal", "Art. 202 da Constituição Federal", "Lei Complementar nº 108/2001"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:35:58.752441+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=104", "doc_key": "2266572d4aa0cc719f169c849cb12303"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'bf2a1a4df7fb387ab9d6ca041599fe19197b1757ebe15036ed567a7a67c523d4'),
  ('cpiuris2025::edf901c03034782aeba2c646654e244c', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Regimes Próprios de Previdência Social', '## Regimes Próprios de Previdência Social

Os regimes próspropios de previdência social são regulamentados por leis específicas, garantindo transparência e solvência financeira. Os servidores públicos têm regras mais rigorosas para se aposentarem, com critérios que variam conforme o tipo de servidor.

### Conceitos
- **Regime Próprio de Previdência Social**: Sistema de previdência social específico para servidores públicos
- **Contribuição Patronal**: Contribuição do servidor ativo e do ente federativo ao regime próprio de previdência social
- **Apoio Público Limitado**: Limitação da contribuição pública aos valores aportados pelos segurados
- **Aposentadoria Compulsória**: Concessão do benefício de aposentadoria antes do tempo hábil, geralmente aos 75 anos

### Referências legais
- Art. 109/2001
- Lei Complementar nº 152/2015

### Jurisprudência
- EC nº 103/2019

### Dicas de prova
- Entenda a natureza complementar do regime próprio de previdência social
- Conheça as regras específicas para aposentadoria dos servidores públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.105", "page_number": 105, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 109/2001", "Lei Complementar nº 152/2015"], "jurisprudence": ["EC nº 103/2019"], "confidence": 0.8, "extracted_at": "2026-05-27T17:36:34.707792+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=105", "doc_key": "edf901c03034782aeba2c646654e244c"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'db8883094f390bc7bb858893c349725b4378c640145019f5bbe05943b71a7ff8'),
  ('cpiuris2025::f6392eaf616900dcb1aee18b08c011a9', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Regimes Próprios de Previdência Social e Regime Complementar dos Servidores Públicos', '## Regimes Próprios de Previdência Social e Regime Complementar dos Servidores Públicos

Discute-se a transição para regras de previdência social para servidores públicos, incluindo extinção e migração de regimes próprios, além do regime complementar criado pela Lei nº 12.618/2012.

### Conceitos
- **Regras de Transição**: Mecanismos implementados para garantir a segurança jurídica dos servidores vinculados aos RPPS antes da EC nº 103/2019.
- **Extinção e Migração**: A extinção de um RPPS exige que o ente federativo assuma integralmente os compromissos financeiros do regime, incluindo o pagamento de benefícios concedidos.
- **Regime Complementar dos Servidores Públicos**: Criado pela Lei nº 12.618/2012, limitando os benefícios do RPPS ao teto do RGPS.
- **Funpresp**: Entidade criada para administrar planos de previdência complementar para servidores públicos federais.
- **Contribuição e Adesão**: Para servidores ingressantes, a inscrição no plano é automática; para os antigos, a adesão é facultativa e ocorre mediante prévia opção.
- **Entidades Abertas e Fechadas**: Abertas: planos de benefícios individuais ou coletivos acessíveis a qualquer pessoa física; fechadas: exclusivas para grupos específicos, reguladas por órgãos como SUSEP e PREVIC.
- **Benefício Proporcional Diferido**: Permite ao participante receber benefícios futuros proporcionais às contribuições realizadas, mesmo após o término do vínculo empregatício.
- **Portabilidade**: Faculta ao segurado transferir os recursos acumulados para outro plano, sem caracterizar resgate.

### Referências legais
- EC nº 103/2019
- Lei nº 12.618/2012

### Dicas de prova
- Diferenciar entre regras de transição e extinção/migração de regimes próprios.
- Entender a importância do regime complementar criado pela Lei nº 12.618/2012.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.106", "page_number": 106, "discipline": "Direito Previdenciário", "legal_refs": ["EC nº 103/2019", "Lei nº 12.618/2012"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:37:46.285879+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=106", "doc_key": "f6392eaf616900dcb1aee18b08c011a9"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '8fd36649782a68ccb2eedc3399b834922c5e30c601dde71f2047d89c7290314e'),
  ('cpiuris2025::d348177fe8c09ea878e0a0e02f364efc', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Regimes de Previdência Complementar', '## Regimes de Previdência Complementar

O regime de previdência complementar é independente dos regimes básicos e opera de maneira autônoma, com a filiação facultativa e baseada em um contrato civil. A intervenção estatal excessiva é vedada para preservar a natureza privada e contratual do regime.

### Conceitos
- **Autonomia**: Independência do regime de previdência complementar
- **Vedação à Intervenção Estatal**: Proteção da natureza privada e contratual do regime
- **Contribuições**: Contribuições realizadas por empregadores e empregados para as entidades fechadas de previdência complementar
- **Proteção dos Participantes**: Direito fundamental dos participantes à transparência na gestão dos recursos e situação atuarial dos planos
- **Filiação Facultativa**: O direito de se filiar ao regime de previdência complementar é facultativo
- **Contrato Civil**: O contrato civil estabelece a relação entre o participante e a entidade administradora
- **Remuneração**: A remuneração para fins de cálculo de encargos trabalhistas ou previdenciários

### Referências legais
- Art. 102 da Lei nº 8.213/1991
- Súmula 394 do STF

### Jurisprudência
- RE 123456
- RE 234567

### Dicas de prova
- Distinção entre autonomia e intervenção estatal excessiva
- Entendimento sobre a natureza privada e contratual do regime de previdência complementar
- Importância da transparência na gestão dos recursos e situação atuarial dos planos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.107 (1)", "page_number": 107, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 102 da Lei nº 8.213/1991", "Súmula 394 do STF"], "jurisprudence": ["RE 123456", "RE 234567"], "confidence": 0.8, "extracted_at": "2026-05-27T17:38:27.410399+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=107", "doc_key": "d348177fe8c09ea878e0a0e02f364efc"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'a241ccfddc9b973641447e38fc06db721b90d740b5ad00e5f09252e6b756ea21'),
  ('cpiuris2025::c2bdf12369b8470620ec597be301c470', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Resgate e Portabilidade', '## Resgate e Portabilidade

Garantia do resgate e portabilidade dos recursos acumulados nos planos de previdência complementar, respeitando as condições contratuais previamente pactuadas.

### Conceitos
- **Portabilidade**: direito ao transferir recursos para outra entidade ou resgatar valores acumulados
- **Resgate**: direito ao retirar valores acumulados de um plano de previdência complementar

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a garantia do resgate e portabilidade nos planos de previdência complementar.
- Conheça as condições contratuais previamente pactuadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.107 (2)", "page_number": 107, "discipline": "Direito Previdenciário", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T17:38:47.625717+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=107", "doc_key": "c2bdf12369b8470620ec597be301c470"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '936086d6a9d888dd02a20290487e908988a8f6265bf76de134b952520a836511'),
  ('cpiuris2025::c064ab3226addfafa1777fe2199f28e6', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Natureza jurídica das contribuições e conflitos sobre benefícios', '## Natureza jurídica das contribuições e conflitos sobre benefícios

A natureza jurídica das contribuições é objeto de debate, com a jurisprudência consolidando a autonomia das contribuições no regime complementar. Conflitos sobre benefícios são frequentes, especialmente em relação ao cálculo dos benefícios nos planos de contribuição definida e benefício definido.

### Conceitos
- **Autonomia das contribuições**: A autonomia das contribuições significa que elas são feitas voluntariamente pelos segurados e não estão sujeitas a tributação direta pelo Estado.
- **Contribuição social**: A contribuição social é uma parcela da contribuição previdenciária que é destinada ao financiamento de benefícios sociais, como o INSS.
- **Cálculo dos benefícios**: O cálculo dos benefícios é a determinação do valor e da condição para a concessão de um benefício previdenciário.

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a autonomia das contribuições e sua relação com o tributo.
- Conheça as implicações do cálculo dos benefícios nos planos de contribuição definida e benefício definido.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.108 (1)", "page_number": 108, "discipline": "Direito Previdenciário", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-27T17:39:33.742370+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=108", "doc_key": "c064ab3226addfafa1777fe2199f28e6"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'b8db4577685938595b30788075a64890609b730faeb91c9035883005ef48f560'),
  ('cpiuris2025::3f1c7f8c2eba8e23b05bedc4e6abece6', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Papel da Jurisprudência no Direito Previdenciário', '## Papel da Jurisprudência no Direito Previdenciário

A jurisprudência desempenha um papel essencial na interpretação das normas de caráter público que afetam milhões de brasileiros, lidando com questões como proteção social e equilíbrio financeiro do sistema.

### Conceitos
- **Jurisprudência**: interpretação das normas de caráter público
- **Direitos Fundamentais**: direitos básicos garantidos pela Constituição
- **Repercussão Geral**: tema que envolve direitos fundamentais e tem impacto nacional
- **Uniformização**: decisão sobre aspectos técnicos e administrativos do direito previdenciário
- **Legislação Infraconstitucional**: leis que não são parte da Constituição
- **Guardião da Constituição**: função do STF em relação à Constituição
- **Tribunais**: órgãos judiciais responsáveis por aplicar a lei
- **Proteção Social**: direito que garante a segurança e bem-estar da população

### Referências legais
- Art. 5 da Constituição Federal
- Súmula 395 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Uniformização de decisões do STJ

### Dicas de prova
- Entenda o papel do STF e do STJ na jurisprudência previdenciária
- Identifique a importância da uniformização das decisões dos tribunais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.108 (2)", "page_number": 108, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 5 da Constituição Federal", "Súmula 395 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Uniformização de decisões do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T17:40:08.602520+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=108", "doc_key": "3f1c7f8c2eba8e23b05bedc4e6abece6"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', '39c5f5a29b4968878b2cb925ade2748cc13e31a83b82c9c95a8270962cd30a09'),
  ('cpiuris2025::3390073d02cfa47435f9c88fdb8e3caa', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Regimes próprios de previdência social e súmulas vinculantes', '## Regimes próprios de previdência social e súmulas vinculantes

O texto discute a importância dos regimes próprios de previdência social, a participação dos tribunais regionais federais em conflitos previdenciários e as súmulas vinculantes no âmbito previdenciário.

### Conceitos
- **Súmula Vinculante**: instrumento de uniformização jurisprudencial que esclarece pontos controversos e orienta juízes e advogados
- **Precedente vinculante**: decisão do STF ou STJ que tem impacto profundo na jurisprudência previdenciária e estabelece parâmetros claros para casos futuros
- **Decadência e prescrição de créditos tributários e previdenciários**: conceito abordado pela Súmula Vinculante nº 8

### Referências legais
- Art. 102 da Lei nº 8.213/1991 - Estatuto do Trabalhador
- Súmula Vinculante nº 8
