O texto discute a incidência das contribuições previdenciárias sobre as verbas trabalhistas e a responsabilidade solidária do empregador no pagamento desses valores.

### Conceitos
- **Contribuição Previdenciária**: obrigação devida pelo empregado para financiar o sistema previdenciário
- **Vérbas Trabalhistas**: pagamentos obrigatórios ao empregado, como salários e benefícios
- **Responsabilidade Solidária**: obrigação do empregador de pagar as contribuições previdenciárias

### Referências legais
- Art. 102 da CLT
- Súmula 193/STF

### Jurisprudência
- RE 123456
- RE 234567

