  ('cpiuris2025::9c8729ea13c4331608fd3c64a8e0f811', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Súmulas do STF', '## Súmulas do STF

Resumo de súmulas do STF relacionadas a benefícios previdenciários, contribuições e ações judiciais.

