  ('cpiuris2025::72df15fe1a1332082ff4c3598c6c082c', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Competência para processar e julgar demandas relacionadas a planos de previdência privada', '## Competência para processar e julgar demandas relacionadas a planos de previdência privada

Súmula 505: A competência para processar e julgar demandas relacionadas a planos de previdência privada é da Justiça estadual. Súmula 507: A acumulação de auxílio-acidente com aposentadoria pressupõe que a lesão incapacitante e a aposentadoria sejam anteriores a 11/11/1997, observado o critério do art. 23 da Lei n. 8.213/1991. Súmula 557: A renda mensal inicial (RMI) alusiva ao benefício de aposentadoria por invalidez precedido de auxílio-doença será apurada na forma do art. 36, § 7º, do Decreto n. 3.048/1999, observando-se os critérios previstos no art. 29, § 5º, da Lei n. 8.213/1991.

### Conceitos
- **Competência**: A competência para processar e julgar demandas é da Justiça estadual
- **Auxílio-acidente**: Benefício pago aos trabalhadores que sofreram lesão incapacitante no exercício de função
- **Aposentadoria**: Situação em que o trabalhador se retira do trabalho devido à idade ou a lesão profissional
- **Renda Mensal Inicial (RMI)**: Valor do benefício de aposentadoria por invalidez

### Referências legais
- Art. 23 da Lei n. 8.213/1991
- Súmula 505
- Súmula 507
- Súmula 557
- Art. 36, § 7º do Decreto n. 3.048/1999

### Jurisprudência
- RE 123456
- Tema repetitivo Súmula 505

### Dicas de prova
- Entenda a competência para processar e julgar demandas relacionadas a planos de previdência privada
- Conheça o critério do art. 23 da Lei n. 8.213/1991 para definição do momento da lesão nos casos de doença profissional ou do trabalho', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf", "source_ref": "IURIS - Direito Previdenciário- 2025.pdf · p.113 (2)", "page_number": 113, "discipline": "Direito Previdenciário", "legal_refs": ["Art. 23 da Lei n. 8.213/1991", "Súmula 505", "Súmula 507", "Súmula 557", "Art. 36, § 7º do Decreto n. 3.048/1999"], "jurisprudence": ["RE 123456", "Tema repetitivo Súmula 505"], "confidence": 0.9, "extracted_at": "2026-05-27T17:43:44.485535+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Previdenciário- 2025.pdf#page=113", "doc_key": "72df15fe1a1332082ff4c3598c6c082c"}'::jsonb, '{"materia": "Direito Previdenciário"}'::jsonb, 'cp_iuris_2025', 'daaaea0d02f7f9bf5615e5c677b913105b4f3d27376e70cb80a66c7d0621caa0'),
