  ('cpiuris2025::7d16802665ffb2ea265fc89b496c93a0', 'doutrina', 'cp_iuris', 'Direito Previdenciário — Índices de Adesões e Recursos', '## Índices de Adesões e Recursos

Lista de índices de adesões (ADI) e recursos especiais e extraordinários, bem como leis e constituições relevantes.

### Conceitos
- **ADI**: Ação direta de inconstitucionalidade
- **Constituição Federal**: Estatuto fundamental do Brasil
- **Decreto**: Ato do Poder Executivo que estabelece regras ou normas para a execução de uma lei
- **EC (Emenda Constitucional)**: Modificação da Constituição Federal
- **Lei**: Ato do Poder Legislativo que estabelece regras ou normas para a sociedade
- **LOAS (Lei Orgânica das Assembleias Legislativas Estaduais)**: Lei que regula as assembleias legislativas estaduais
- **RE (Recurso Extraordinário) e REsp (Recurso Especial)**: Processo judicial que visa a revisão de uma decisão do tribunal
- **Súmula**: Princípio jurídico que estabelece regra geral para a aplicação da lei

