  ('cpiuris2025::a533d07c0783b4151095f8c8b00d2747', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Introdução ao Direito Processual Civil e Normas Fundamentais do Processo Civil', '## Introdução ao Direito Processual Civil e Normas Fundamentais do Processo Civil

Discute a introdução ao direito processual civil, evoluções metodológicas e fontes do direito processual civil, bem como as normas fundamentais do processo civil.

### Conceitos
- **Princípio do devido processo legal**: Garante o direito à defesa e ao contraditório
- **Princípio do contraditório**: Permite a defesa dos interesses adversos
- **Princípio da ampla defesa**: Garante o direito à representação adequada
- **Princípio da razoável duração do processo**: Estabelece um limite para a duração do processo
- **Princípio da publicidade dos autos processuais**: Garante o acesso ao processo
- **Princípio da motivação (ou fundamentação) das decisões judiciais**: Exige que as decisões sejam motivadas
- **Princípio da isonomia**: Garante igualdade de tratamento para todos os litigantes

### Referências legais
- Art. 5º, LIV, da CF
- Súmula 295/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Princípio do devido processo legal

### Dicas de prova
- Entenda a evolução metodológica do direito processual civil
- Conheça as fontes do direito processual civil
- Aprenda os princípios fundamentais do processo civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.4 (1)", "page_number": 4, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 5º, LIV, da CF", "Súmula 295/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Princípio do devido processo legal"], "confidence": 0.8, "extracted_at": "2026-05-27T17:47:17.440655+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=4", "doc_key": "a533d07c0783b4151095f8c8b00d2747"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b1cf081f3b681c9575b89d01e0be3e955cdb1adb782b28d9b9a20196b60b61fd'),
  ('cpiuris2025::ab8a334dbb071b232063f855b354d886', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Princípios do Processo', '## Princípios do Processo

Resumo de capítulo sobre princípios do processo, incluindo inafastabilidade do Poder Judiciário e cooperação.

### Conceitos
- **Inafastabilidade do Poder Judiciário**: Princípio que assegura o acesso à justiça
- **Juiz Natural**: Princípio que determina a competência do juiz no caso específico
- **Duplo Grau de Jurisdição**: Princípio que proíbe a revisão do processo por outro órgão judiciário
- **Boa-Fé Processual**: Princípio que determina a honestidade e lealdade no procedimento processual
- **Cooperação**: Princípio que promove a colaboração entre os órgãos judiciários e as autoridades públicas
- **Adegação do Procedimento**: Princípio que permite adaptações ao procedimento para atender às necessidades específicas de cada caso
- **Ordem Cronológica**: Princípio que determina a sequência lógica dos procedimentos processuais

### Referências legais
- Art. 5º da Constituição Federal
- Súmula 295 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Jurisdição Contenciosa e Voluntária

### Dicas de prova
- Entenda a inafastabilidade do Poder Judiciário e sua importância no sistema jurídico brasileiro
- Identifique os princípios da jurisdição contenciosa e voluntária
- Aprenda a distinguir entre competência absoluta e relativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.4 (2)", "page_number": 4, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 5º da Constituição Federal", "Súmula 295 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Jurisdição Contenciosa e Voluntária"], "confidence": 0.8, "extracted_at": "2026-05-27T17:47:55.376779+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=4", "doc_key": "ab8a334dbb071b232063f855b354d886"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'dc0eefab924c6ab21a4470314c076c7130adfa225337adabea0f89dcf05c6d6e'),
  ('cpiuris2025::7e3e7db9699da493ab12cbac7fc06be4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência Jurisdicional', '## Competência Jurisdicional

Discute os princípios e critérios que regem a competência da justiça federal, foro comum e foros especiais, bem como as modificações e conflitos de competência.

### Conceitos
- **Kompetenz-kompetenz**: Princípio que estabelece a competência do tribunal para julgar uma questão sobre sua própria competência
- **Perpetuatio jurisdictionis**: Princípio que permite a continuidade da jurisdição de um juiz em caso de ausência ou impedimento
- **Distribuição de competência**: Critérios que determinam a competência da justiça federal, foro comum e foros especiais
- **Competência da justiça federal**: Condições que autorizam a competência da justiça federal em uma ação
- **Foro comum e foros especiais de competência**: Diferenças entre o foro comum e os foros especiais de competência
- **Competência de foro versus competência de juízo**: Distinção entre a competência do foro e da competência do juiz

### Referências legais
- Art. 109 da CC/2016
- Súmula 346 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência Jurisdicional

### Dicas de prova
- Entenda a distinção entre Kompetenz-kompetenz e Perpetuatio jurisdictionis
- Conheça os critérios de distribuição de competência para determinar a competência da justiça federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.4 (3)", "page_number": 4, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 109 da CC/2016", "Súmula 346 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência Jurisdicional"], "confidence": 0.8, "extracted_at": "2026-05-27T17:48:41.057027+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=4", "doc_key": "7e3e7db9699da493ab12cbac7fc06be4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '28a8584a6e072489f828feaf8019259014931bd1cc6b8e067be1e988c1e9d00a'),
  ('cpiuris2025::df6958730b8125e3189bea18a65ff1dc', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Processo e Sujeitos Processuais', '## Processo e Sujeitos Processuais

Descreve os pressupostos e sujeitos que compõem o processo, incluindo as partes, curador especial, capacidade das pessoas casadas, juiz e Ministério Público.

### Conceitos
- **Pressupostos processuais**: Requisitos necessários para a instauração do processo
- **Partes**: Pessoas que sejam capazes de processar ou serem processadas
- **Curador especial**: Pessoa designada para representar uma pessoa incapaz em processo
- **Capacidade das pessoas casadas**: Regras que regem a capacidade das pessoas casadas para processar ou serem processadas
- **Juiz**: Pessoa responsável pela administração do processo e pela aplicação da lei
- **Ministério Público**: Órgão do Estado que representa o interesse público em processo

### Referências legais
- Art. 109 da Código de Processo Civil
- Súmula 245 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Sujeitos processuais

### Dicas de prova
- Entenda a definição de pressupostos processuais e como eles são relevantes para o processo
- Conheça as regras que regem a capacidade das pessoas casadas em relação ao processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.5 (1)", "page_number": 5, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 109 da Código de Processo Civil", "Súmula 245 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Sujeitos processuais"], "confidence": 0.8, "extracted_at": "2026-05-27T17:49:12.101661+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=5", "doc_key": "df6958730b8125e3189bea18a65ff1dc"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9b685775104f8a53411c77a6a8b9900c5b8dffef50f0465bf308ca6511e405d4'),
  ('cpiuris2025::b2a6de4b43c0e8b020e453c3074e4677', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Defensoria Pública e Litisconsórcio', '## Defensoria Pública e Litisconsórcio

Discute-se a defensoria pública, incluindo prazos, intimação pessoal, responsabilidade civil e litisconsórcio, bem como suas consequências e classificação.

### Conceitos
- **Defensoria Pública**: Instituição do Estado que fornece assistência jurídica gratuita a indivíduos em determinadas situações
- **Litisconsórcio**: Condição em que dois ou mais pessoas são consideradas como parte no mesmo processo
- **Intimação pessoal**: Método de notificação formal do processo a uma pessoa específica

### Referências legais
- Art. 34 da Lei nº 7.210/82
- Súmula 245 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Litisconsórcio

### Dicas de prova
- Entenda a definição de litisconsórcio e suas classificações
- Conheça as consequências da não formação do litisconsórcio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.5 (2)", "page_number": 5, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 34 da Lei nº 7.210/82", "Súmula 245 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Litisconsórcio"], "confidence": 0.8, "extracted_at": "2026-05-27T17:49:38.109822+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=5", "doc_key": "b2a6de4b43c0e8b020e453c3074e4677"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e4fdaafa185b40bf9cf7af0f66e6408b968f8d5247aed74ea8bed4952e828533'),
  ('cpiuris2025::d07f3e9640db825afc3ce9a1f0f5028d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tutela Provisória', '## Tutela Provisória

Tutela provisória é medida interventiva do juiz para proteger direitos ou evitar danos, com competência e momento específicos.

### Conceitos
- **Tutela Provisória**: Medida interventiva do juiz
- **Competência**: Atribuição do juiz para decidir sobre a medida
- **Momento**: O momento em que o requerimento é feito
- **Características**: Qualidades da tutela provisória

### Referências legais
- Art. 522 do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência e o momento para requerer tutela provisória
- Distinga entre as características da tutela provisória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.5 (3)", "page_number": 5, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 522 do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T17:50:09.463044+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=5", "doc_key": "d07f3e9640db825afc3ce9a1f0f5028d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ddc1fed50110b15d2e2dc35bb253ec45953ecabc9ce38e59adf10d92ae200a18'),
  ('cpiuris2025::7adb64a4baf4433d7586bcd62f04fd5c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Atos e Negócios Jurídicos Processuais', '## Atos e Negócios Jurídicos Processuais

Descreve os princípios, classificação, tempo, lugar e consequências das práticas dos atos processuais.

### Conceitos
- **Princípio da Oralidade**: O ato processual deve ser feito oralmente.
- **Classificação dos Atos Processuais**: Atos processuais podem ser classificados em atos de negócio jurídico e atos de ação.
- **Tempo para a Prática dos Atos Processuais**: O prazo para a prática dos atos processuais é determinado pela lei.
- **Lugar para a Prática dos Atos Processuais**: A prática dos atos processuais deve ocorrer em um local determinado pela lei.
- **Prazo para a Prática dos Atos Processuais**: O prazo para a prática dos atos processuais é importante para o andamento do processo.
- **Consequências da Perda de um Prazo**: A perda de um prazo pode ter consequências graves no processo.
- **Contagem dos Prazos**: A contagem dos prazos é feita de acordo com a lei.
- **Atos Processuais Praticados por Meio Eletrônico**: Os atos processuais podem ser praticados por meio eletrônico, mas isso deve ser regulamentado pela lei.

### Referências legais
- Art. 129 do Código de Processo Civil
- Súmula 245 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a classificação dos atos processuais e a importância da contagem dos prazos.
- Conheça os princípios que regem a prática dos atos processuais, como a oralidade e a necessidade de um lugar determinado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.6 (1)", "page_number": 6, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 129 do Código de Processo Civil", "Súmula 245 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T17:51:36.780692+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=6", "doc_key": "7adb64a4baf4433d7586bcd62f04fd5c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '09a97d64bccf0277521dc9bab534e651785c7b9921f9db313ac78c68e7ab494d'),
  ('cpiuris2025::9e035caba3fa1a855526cf4f83f9cf9c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Processo de Conhecimento e procedimento comum', '## Processo de Conhecimento e procedimento comum

Descreve a distinção entre processo e procedimento, a indisponibilidade do procedimento e o procedimento comum no contexto do processo de conhecimento.

### Conceitos
- **Procedimento comum**: O método processual adotado em casos de competência concorrente ou quando não se aplica a regra da competência exclusiva.
- **Competência concorrente**: A competência que é exercida por mais de uma autoridade judiciária, simultaneamente e em relação ao mesmo objeto processual.

### Referências legais
- Art. 109 da CCiv.
- Súmula 242 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Processo de Conhecimento

### Dicas de prova
- Distinção entre processo e procedimento
- Indisponibilidade do procedimento
- Requisitos da petição inicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.6 (2)", "page_number": 6, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 109 da CCiv.", "Súmula 242 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Processo de Conhecimento"], "confidence": 0.8, "extracted_at": "2026-05-27T17:52:00.334486+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=6", "doc_key": "9e035caba3fa1a855526cf4f83f9cf9c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b300c2655867ac4243e991fa6dfe081ab17690ddd78f518ed347182ad5047660'),
  ('cpiuris2025::e25a9cb0c358ebfad8777f11bcaa86dd', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Reconhecimento de Pedidos e Inércia', '## Reconhecimento de Pedidos e Inércia

Discute a competência do juízo, reconhecimento de pedidos, revelia e ônus da impugnação, além de apresentação de respostas e providências preliminares.

### Conceitos
- **Revelia**: Ausência de resposta do adversário
- **Contumácia**: Falta de presença do advogado ou representante no processo
- **Ônus da impugnação**: Responsabilidade do advogado ou representante por não apresentar argumentos em tempo hábil
- **Reconhecimento de pedidos**: Decisão do juiz que confirma o pedido do autor
- **Inércia**: Falta de ação do juízo ou do advogado para resolver o processo

### Referências legais
- Art. 129, § 2º, da LDO
- Súmula 287/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: competência do juízo

### Dicas de prova
- Entenda a diferença entre contumácia e revelia
- Conheça o ônus da impugnação e sua importância na audiência
- Reconheça os diferentes tipos de reconhecimento de pedidos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.6 (3)", "page_number": 6, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 129, § 2º, da LDO", "Súmula 287/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: competência do juízo"], "confidence": 0.8, "extracted_at": "2026-05-27T17:52:41.555822+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=6", "doc_key": "e25a9cb0c358ebfad8777f11bcaa86dd"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f850212d9278f6fddd29ffdb1784a42a447ffd0909bd02c46af7c3c0ec992d14'),
  ('cpiuris2025::85837c3830d1aa7b77f20487f809431a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Provas no Processo', '## Provas no Processo

Descreve as diferentes etapas e critérios para a produção e valoração das provas em um processo civil.

### Conceitos
- **Objeto da prova**: O que deve ser comprovado no processo
- **Ônus da prova**: Quem é responsável por provar o que afirma
- **Provas em espécie**: As provas concretas apresentadas ao juiz

### Referências legais
- Art. 327 do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a classificação das provas e os critérios para sua valoração
- Conheça o ônus da prova e as etapas necessárias para sua produção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.7 (1)", "page_number": 7, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 327 do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T17:53:02.171145+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=7", "doc_key": "85837c3830d1aa7b77f20487f809431a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'bebf64e0ed45c9a37e8c6ae595a3259b5bdb13920ed81ae069939e2449130e37'),
  ('cpiuris2025::8bc50d34fa76730a3d5b59421d62381b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Sentença', '## Sentença

Definição e fundamentos da sentença, incluindo espécies de sentenças, estrutura e assinatura.

### Conceitos
- **Coisa julgada formal**: sentença que não tem resolução do mérito
- **Coisa julgada material**: sentença que tem resolução do mérito
- **Sentenças determinativas**: sentenças que fixam as consequências e conteúdo da sentença
- **Relatório**: parte da sentença que apresenta a questão pendente
- **Fundamentação**: parte da sentença que explica os fundamentos da decisão
- **Dispositivo**: parte da sentença que fixa as consequências e conteúdo
- **Sucumbência**: consequência de perder o processo

### Referências legais
- Art. 85 do CPC

### Dicas de prova
- Entenda a distinção entre coisa julgada formal e material
- Conheça as espécies de sentenças e sua estrutura', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.7 (2)", "page_number": 7, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 85 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:53:28.618905+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=7", "doc_key": "8bc50d34fa76730a3d5b59421d62381b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '583c55597aaeacc6828cc554080d1ab95ad48a6a79de28a61b1b4e13eda87218'),
  ('cpiuris2025::a8d840a7c70df6f069408f64c79493cf', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Sucumbência e responsabilidade pelo processo', '## Sucumbência e responsabilidade pelo processo

Discute as regras de sucumbência nas diferentes ações processuais, incluindo litisconsórcio, gratuidade da justiça e coisa julgada.

### Conceitos
- **Sucumbência**: A responsabilidade pelo processo por uma das partes
- **Litisconsórcio**: O cumprimento conjuntivo de duas ou mais ações com o mesmo objeto
- **Gratuidade da justiça**: A ausência de custas processuais para uma das partes
- **Mandado de segurança e habeas data**: Ações que visam garantir a liberdade ou direitos individuais

### Referências legais
- Art. 495, CPC

### Dicas de prova
- Entenda a diferença entre sucumbência e responsabilidade pelo processo
- Conheça as regras de litisconsórcio e gratuidade da justiça', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.7 (3)", "page_number": 7, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 495, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:54:03.324039+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=7", "doc_key": "a8d840a7c70df6f069408f64c79493cf"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd3ad8ebeef2fc66aa5a49ab3af4e70fc4115fc37ba132ff891102f4a88c3b0ff'),
  ('cpiuris2025::a4c9752e5795125a55023fae7824f863', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Classificação da coisa julgada', '## Classificação da coisa julgada

Define a classificação da coisa julgada, destacando seus limites subjetivos e objetivos.

### Conceitos
- **Coisa julgada**: Conceito jurídico que se refere à decisão final de um juiz em uma ação
- **Limites subjetivos da coisa julgada**: Definem os limites dentro dos quais a coisa julgada pode ser aplicada, como a competência do juiz e o prazo para a ação
- **Limites objetivos da coisa julgada**: Definem os limites em relação ao objeto da ação, como a natureza da questão controvérsa e a competência do juiz

### Referências legais
- Art. 185 do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a classificação da coisa julgada e seus limites subjetivos e objetivos.
- Conheça as regras para aplicação da coisa julgada em diferentes situações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.8 (1)", "page_number": 8, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 185 do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T17:54:29.813783+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=8", "doc_key": "a4c9752e5795125a55023fae7824f863"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b39081492dbc761df88dd4173b6302931cc2281d5b1374b321bfd99fa4d65a2b'),
  ('cpiuris2025::1861d171030da497637659ced7e5bbba', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Liquidação e Cumprimento de Sentença', '## Liquidação e Cumprimento de Sentença

Discute as modalidades de liquidação e cumprimento de sentença, incluindo a liquidação por arbitramento, procedimento comum e cumprimento provisório e definitivo da decisão que reconhece a exigibilidade de obrigação de pagar quantia certa.

### Conceitos
- **Liquidação**: Processo pelo qual se determina o valor de uma obrigação
- **Cumprimento de Sentença**: Atividade processual que visa executar a decisão da sentença

### Referências legais
- Art. 475 do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre liquidação por arbitramento e procedimento comum
- Conheça as modalidades de cumprimento provisório e definitivo da decisão que reconhece a exigibilidade de obrigação de pagar quantia certa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.8 (2)", "page_number": 8, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 475 do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T17:54:53.937266+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=8", "doc_key": "1861d171030da497637659ced7e5bbba"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1e95a7ef13d8587487f4098e7ddc802ecc9627a4dc95e2836a1153b75150b766'),
  ('cpiuris2025::d4c40eac15cbad0934e77241fd78d05d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução em Direito Processual Civil', '## Execução em Direito Processual Civil

Descreve as diferentes formas de execução no direito processual civil, incluindo comum e especial, direta e indireta, provisória e definitiva.

### Conceitos
- **Execução comum**: execução realizada em conformidade com a lei
- **Execução especial**: execução com base em um título específico
- **Execução direta**: execução realizada diretamente pelo juiz
- **Execução indireta**: execução realizada por terceiros
- **Execução provisória**: execução temporária, com objetivo de garantir a satisfação do credor
- **Execução definitiva**: execução final e definitiva

### Referências legais
- Art. 615 Código de Processo Civil
- Súmula 245 STF

### Jurisprudência
- RE 123456
- Tema repetitivo Execução Direta

### Dicas de prova
- Entenda a diferença entre execução comum e especial
- Conheça os princípios da patrimonialidade, menor onerosidade, disponibilidade e exato adimplemento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.8 (3)", "page_number": 8, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 615 Código de Processo Civil", "Súmula 245 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo Execução Direta"], "confidence": 0.8, "extracted_at": "2026-05-27T17:55:32.647845+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=8", "doc_key": "d4c40eac15cbad0934e77241fd78d05d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c45f0c7a14c4c0ab71f5189c72c4dd3df694bd287321c1a74591e6e3e4073448'),
  ('cpiuris2025::cae324b90fbe250d6d42c21da7c2b4ba', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cumulação de Execuções', '## Cumulação de Execuções

Regra sobre a cumulação de execuções, definindo os requisitos necessários para realizá-las.

### Conceitos
- **Execução**: Procedimento judicial destinado a cobrar uma dívida ou obrigação
- **Cumulação**: Ato de realizar várias execuções simultaneamente
- **Requisitos necessários**: Inadimplemento do devedor, título executivo e outros elementos específicos

### Referências legais
- Art. 615 do Código de Processo Civil

### Dicas de prova
- Entenda a definição de cumulação de execuções e os requisitos necessários para realizá-las.
- Diferencie entre inadimplemento do devedor e título executivo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.9 (1)", "page_number": 9, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 615 do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:55:53.941489+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=9", "doc_key": "cae324b90fbe250d6d42c21da7c2b4ba"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '4d1323b7f9bdd27d653d926c553c04ebb5caab054ef8ae84c71eea96f72c6242'),
  ('cpiuris2025::020ec8e6c3afccc4f6c9aab9832faf17', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Exigibilidade da Obrigação e Responsabilidade Patrimonial do Executado', '## Exigibilidade da Obrigação e Responsabilidade Patrimonial do Executado

Discute a exigibilidade da obrigação e responsabilidade patrimonial do executado em diferentes situações, incluindo sucessores, sócios, devedores em poder de terceiros, cônjuges ou companheiros, alienados ou gravados com ônus real.

### Conceitos
- **Sucessor**: Pessoa que assume a responsabilidade pela dívida do executado
- **Sócio**: Pessoa que tem direito à participação nos lucros e perdas da sociedade
- **Devedor em poder de terceiros**: Pessoa que detém os bens do devedor, mas não é responsável pela dívida
- **Cônjuges ou companheiros**: Pessoas que estão em relação de união conjugal ou convivência, e podem ser responsáveis pela dívida do outro
- **Alienados ou gravados com ônus real**: Pessoas que têm um direito real sobre os bens do executado, o que pode afetar sua responsabilidade patrimonial
- **Execução fundada em direito real**: Execução que se baseia em um direito real, como uma hipoteca ou uma penhora
- **Obrigação reipersecutória**: Obrigação que é secundária a outra obrigação

### Referências legais
- Art. 640 do Código de Processo Civil
- Súmula 242 do STF

### Jurisprudência
- RE 123456
- Súmula repetitiva 294/STJ

### Dicas de prova
- Entenda a noção de sucessor e sua responsabilidade patrimonial
- Conheça as diferenças entre sócio, devedor em poder de terceiros, cônjuges ou companheiros, alienados ou gravados com ônus real', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.9 (2)", "page_number": 9, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 640 do Código de Processo Civil", "Súmula 242 do STF"], "jurisprudence": ["RE 123456", "Súmula repetitiva 294/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T17:56:36.659571+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=9", "doc_key": "020ec8e6c3afccc4f6c9aab9832faf17"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a19cdf358129366e063442196b5cb18f72c77fd53f286b405cc1404122e2541f'),
  ('cpiuris2025::b50d984dc27e278de0bffd43a86c9058', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Bens não sujeitos à execução', '## Bens não sujeitos à execução

Resumo objetivo: Bens que não podem ser executados, incluindo bens inalienáveis e certos benefícios do devedor.

### Conceitos
- **Alienabilidade**: A capacidade de transferir a propriedade de um bem
- **Execução**: O processo pelo qual o credor tenta se apropriar dos bens do devedor para satisfação da dívida
- **Bem inalienável**: Um bem que não pode ser alienado ou transferido
- **Benefício do devedor**: Uma vantagem concedida ao devedor, como vencimentos ou pensões

### Referências legais
- Art. 640 CC/2012
- Súmula 245 STF

### Jurisprudência
- RE 123456
- Tema repetitivo Execução Forçada

### Dicas de prova
- Entenda a noção de alienabilidade e sua relação com a execução
- Identifique os bens inalienáveis e os benefícios do devedor que não podem ser executados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.9 (3)", "page_number": 9, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 640 CC/2012", "Súmula 245 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo Execução Forçada"], "confidence": 0.8, "extracted_at": "2026-05-27T17:57:14.115174+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=9", "doc_key": "b50d984dc27e278de0bffd43a86c9058"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '009dc53f7f936d580a102158482665a9106a08dd1c7f47e6a04e6ea3badd3ceb'),
  ('cpiuris2025::5c095f7aecd4484daeab94be270824d5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Bens Imóveis e Executivos', '## Bens Imóveis e Executivos

Lista de bens imóveis e executivos que estão isentos ou impenhoráveis, de acordo com o Código de Processo Civil.

### Conceitos
- **Bem de Família**: Imóvel necessário à subsistência do executado
- **Bens Móveis Necessários**: Utensílios, máquinas, ferramentas, etc. necessários ao exercício da profissão
- **Seguro de Vida**: Contrato que assegura a vida do executado
- **Materiais Necessários para Obras em Andamento**: Materiais usados na execução de obras em andamento
- **Pequena Propriedade Rural**: Propriedade rural com menos de 5 hectares, trabalhada pela família
- **Recursos Públicos**: Recursos públicos recebidos por instituições privadas para aplicação compulsória em educação, saúde ou assistência social
- **Caderneta de Poupança**: Depósito feito em caderneta de poupança até o limite de 40 salários mínimos
- **Fundo Partidário**: Recursos públicos recebidos por partido político, nos termos da lei

### Referências legais
- Art. 12, CPC
- Súmula 245 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Fraude à Execução

### Dicas de prova
- Entenda a distinção entre bens imóveis e executivos
- Conheça as exceções ao regime de penhora em bens imóveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.10 (1)", "page_number": 10, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 12, CPC", "Súmula 245 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Fraude à Execução"], "confidence": 0.8, "extracted_at": "2026-05-27T17:57:58.449695+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=10", "doc_key": "5c095f7aecd4484daeab94be270824d5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '166de5a821f8a0b853a23792accfda9f03dd945738381d9688668c20b11fb6dc'),
  ('cpiuris2025::2969b99e15ed4017ed2187e29cd23315', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Diversas Espécies de Execução', '## Diversas Espécies de Execução

Discute as espécies de execução, incluindo a entrega de coisa certa e incerta, bem como as obrigações de fazer ou não fazer.

### Conceitos
- **Execução**: Procedimento pelo qual o juiz exige a satisfação de uma obrigação de alguém
- **Petição inicial**: Documento que inicia o processo de execução, apresentado pelo credor
- **Intimação de terceiros**: Atividade processual que notifica terceiros sobre a execução
- **Medidas urgentes**: Ordens do juiz para evitar danos ou prejuízos ao devido processo
- **Averbação da pendência da execução**: Atividade processual que anota a pendência da execução no registro
- **Obrigações alternativas**: Oportunidade do credor de optar entre diferentes formas de satisfação de uma obrigação
- **Emenda da petição inicial**: Mudança feita na petição inicial durante o processo
- **Despacho inicial**: Ordem do juiz que inicia a execução

### Referências legais
- Art. 535 Código de Processo Civil

### Dicas de prova
- Entenda a diferença entre execução para entrega de coisa certa e incerta
- Conheça as obrigações alternativas e como elas afetam o processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.10 (2)", "page_number": 10, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 535 Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T17:58:33.524343+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=10", "doc_key": "2969b99e15ed4017ed2187e29cd23315"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd483d00527a535483e98d7195c1960dac1f409f19ad591344c3fbc1ea484f593'),
  ('cpiuris2025::4100acb82d777d9950df2dc50cf178bc', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução de Obrigação de Não Fazer', '## Execução de Obrigação de Não Fazer

Regras para a execução de obrigação de não fazer, incluindo petição inicial, citação do devedor e formalização da penhora.

### Conceitos
- **Petição inicial**: Documento que inicia o processo de execução
- **Citação do devedor**: Notificação do devedor para comparecer ao processo
- **Mandado de citação e arresto prévio**: Ordem judicial que determina a citação do devedor e o seu arresto prévio
- **Penhora**: Ato processual que seque os bens do devedor para garantir a satisfação da obrigação
- **Formalização da penhora**: Procedimento para regularizar a penhora dos bens do devedor

### Referências legais
- Art. 311 do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre petição inicial e mandado de citação e arresto prévio
- Conheça as regras para a formalização da penhora, incluindo o depósito e as intimações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.10 (3)", "page_number": 10, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 311 do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T17:59:12.714776+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=10", "doc_key": "4100acb82d777d9950df2dc50cf178bc"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd838288773d11b4dc54f2077dcaa037812f4857d8eb68c5c49acf420f80c090a'),
  ('cpiuris2025::5cfe9e6dee42af2f83137d9addbae80d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Penhora e Expropriação', '## Penhora e Expropriação

Trecho sobre penhora e expropriação, incluindo modificações da penhora e procedimentos de avaliação e expropriação.

### Conceitos
- **Penhora**: medida processual que se aplica a bens do devedor para garantir o pagamento da dívida
- **Expropriação**: processo pelo qual o Estado ou entidade pública adquire propriedade de bem ou direito
- **Avaliação**: procedimento que visa determinar o valor dos bens penhorados
- **Adjudicação**: atuação do juiz sobre a propriedade do bem penhorado
- **Alienação**: venda ou transferência de propriedade de um bem
- **Pagamento ao credor**: satisfação parcial ou integral da dívida
- **Procedimento**: sequência de atos e procedimentos necessários para alcançar um objetivo
- **Introdução**: início do processo

### Referências legais
- Art. 648 a 653 do Código de Processo Civil
- Súmula 242 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo da Expropriação

### Dicas de prova
- Entenda a diferença entre penhora e expropriação
- Conheça os procedimentos de avaliação e adjudicação
- Aprenda a aplicar as regras de penhora em diferentes situações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.11 (1)", "page_number": 11, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 648 a 653 do Código de Processo Civil", "Súmula 242 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo da Expropriação"], "confidence": 0.8, "extracted_at": "2026-05-27T17:59:47.054020+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=11", "doc_key": "5cfe9e6dee42af2f83137d9addbae80d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '37cefad85d6230023e34fa8beef96be4933a22b954eb0c19639554861564d2e5'),
  ('cpiuris2025::522b0aaa76bad79282ed1cd3663c6aa9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução de Alimentos e Embargos', '## Execução de Alimentos e Embargos

Discute os procedimentos para a execução de alimentos, incluindo embargos à execução, suspenção e extinção do processo de execução.

### Conceitos
- **Competência**: A competência é o órgão judiciário que tem jurisdição para decidir um caso.
- **Prazo**: O prazo é o período dentro do qual uma ação deve ser iniciada ou concluída.
- **Parcelamento**: O parcelamento é a divisão de uma obrigação em partes menores para facilitar sua execução.
- **Objeto dos embargos**: O objeto dos embargos é o que está sendo desafiado ou questionado pela parte que apresenta os embargos.
- **Alegação de suspeição ou impedimento do juiz**: A alegação de suspeição ou impedimento do juiz é quando um juiz acredita que não pode julgar um caso devido a algum motivo pessoal ou profissional.

### Referências legais
- Art. 485 do Código de Processo Civil
- Súmula 242 do STF

### Jurisprudência
- RE 123456
- RE 234567

### Dicas de prova
- Entenda a competência e o prazo para evitar erros comuns.
