### Conceitos
- **Ação de exigir contas**: ação para exigir contas de alguém
- **Ações possessórias**: ações relacionadas à propriedade
- **Ação de divisão e de demarcação de terras particulares**: ação para dividir ou demarcar terras
- **Ação de dissolução parcial de sociedade**: ação para dissolver uma parte de uma sociedade
- **Inventário e partilha**: processo de divisão de bens em caso de morte
- **Embargos de terceiro**: embargos apresentados por um terceiro contra uma decisão
- **Oposição**: oposição apresentada por uma parte a uma decisão
- **Ações de família**: ações relacionadas à família, como divórcio ou guarda dos filhos

